BEGIN TRANSACTION;
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('1-happy-family-usa','#1 Happy Family USA','https://image.tmdb.org/t/p/w500/1EzcDTGhbbvTS27iKK4ompIQjva.jpg',2025,'Animation,Cartoon,Comedy,Hindi Dub','An exploration of the experiences of a Muslim-American family that must learn how to code-switch as they navigate the early 2000s: a time of fear, war, and the rapid expansion of the boy-band industrial complex.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('101-dalmatian-street','101 Dalmatian Street','https://image.tmdb.org/t/p/w500/5meA7Ik8h9t2Bd3VR7Pw85pXECV.jpg',2019,'Cartoon,Family,Hindi Dub,Kids','Follow the adventures of eldest siblings Dolly and Dylan, their Mum Delilah and Dad Doug, and their 97 younger brothers and sisters as they embark on urban adventures and extreme sibling rivalry. Together, the pups explore growing up and finding their own spot inside the biggest, messiest, furriest blended family ever.',4);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('365-days-to-the-wedding','365 Days to the Wedding','https://image.tmdb.org/t/p/w500/lMVkOrMaWEkHZLdPksKGcdi6hJg.jpg',2024,'Adult Cast,Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Seinen,Workplace','Takuya and Rika work at the same travel agency in Tokyo and are both happily introverted and single. But their company is opening a new branch in Alaska next year, and employees without a spouse will be recruited to work there. Desperate to avoid the move, and though they’ve hardly spoken before, they decide to fake an engagement. Can these quiet coworkers become a convincing couple?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('3below-tales-of-arcadia','3Below: Tales of Arcadia','https://image.tmdb.org/t/p/w500/eWoplw8QJhSGDnhyYCrs9OugdTj.jpg',2018,'Cartoon,Comedy,Family,Fantasy,Hindi Dub,Sci-Fi','After crash-landing on Earth, two royal teen aliens on the run struggle to blend in with humans as they evade intergalactic bounty hunters.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-condition-called-love-hindi','A Condition Called Love','https://animedekho.app/wp-content/uploads/2024/05/71J54-XfKFL._AC_UF10001000_QL80_.jpg',2024,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Romance,School,Shoujo','High school freshman Hotaru Hinase has a vibrant life full of family and friendship, but not much luck in romance. That all changes when she makes a warm gesture to her handsome and heartbroken classmate, Hananoi, leading to him asking her out and her becoming flustered. Witness a girl who grapples with the enigma of love and a boy who is heavy handed with it.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-couple-of-cuckoos','A Couple of Cuckoos','https://image.tmdb.org/t/p/w500/tdPYDpjvapdSdxroFidhiXvKY4B.jpg',2022,'Anime,Comedy,Crunchyroll,Harem,Hindi Dub,Romance,Shounen,Tamil,Telugu','16-year-old super-studier Nagi Umino, second-year student at the Megurogawa Academy high school, was switched at birth. On his way to a dinner to meet his birth parents, he accidentally meets the brash, outspoken, Erika Amano, who is determined to make Nagi her fake boyfriend as she never wants to actually marry. But once Nagi makes it to dinner, he finds his parents have decided to resolve the hospital switch by conveniently having him marry the daughter his birth parents raised…who turns out to be none other than Erika herself!',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-gatherers-adventure-in-isekai','A Gatherer’s Adventure in Isekai','https://image.tmdb.org/t/p/w500/AtpIf9wnT6IaHoG31XsdqZEEf80.jpg',2025,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Tamil,Telugu','Kamishiro Takeru is a completely ordinary salaryman who reincarnates in another world—a world of swords and magic called Madeus—and starts his new isekai life with lots of new skills! Takeru must make the most of his enhanced physical strength, unbelievable magic power, and the “Search” ability that allows him to find items of worth as his great isekai journey begins!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-kind-of-magic','A Kind of Magic','https://image.tmdb.org/t/p/w500/oeqHs3NmNX49MkFLJ8o3ILnVL5R.jpg',2008,'Cartoon,Comedy,Family,Hindi Dub','A Kind of Magic is a French animated television series created by Charile Skanker and his animation company Xilam. The story deals with a kid named Tom and his family’s problems, including his sister Cindy, who is crazy after every boy she sees, his toad ‘His Highness’, his evil Aunt Ferocia who wants to turn him evil as well, and his parents who have been exiled from Fairyland and now have to live on Earth.The series has been an instant hit and was rated the most popular series at the 2007 MIPCOM Junior trade show, attracting over 280 buyers.',2);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-misanthrope-teaches-a-class-for-demi-humans','A Misanthrope Teaches a Class for Demi-Humans','https://image.tmdb.org/t/p/w500/yOM6DxJblSheZwOeGwAzfIHxnCc.jpg',2026,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,School,Supernatural,Tamil,Telugu,Workplace','After a traumatic incident ends his teaching career, Rei Hitoma is certain he hates humans. Yet when he sees a job for “a teacher who truly cares for their students,” he’s compelled to apply. Before he knows it, he’s hired—only to find out his students are demi-humans. What begins as a job becomes a journey for healing for both a teacher who’s lost faith in humanity and students who dream of it.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-mortals-journey-to-immortality','A Mortal’s Journey to Immortality','https://image.tmdb.org/t/p/original/9pfqNpz2YRdLgg5FUKVbWzz5fLR.jpg',2023,'Amazon Prime,Animation,Anime,Hindi Dub,MX Player','A poor and ordinary boy from a village joins a minor sect in Jiang Hu and becomes an Unofficial Disciple by chance. How will Han Li, a commoner by birth, establish a foothold for himself in his sect? With his mediocre aptitude, he must successfully traverse the treacherous path of cultivation and avoid the notice of those who may do him harm. This is a story of an ordinary mortal who, against all odds, clashes with devilish demons and ancient celestials in order to find his own path towards immortality.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-pup-named-scooby-doo','A Pup Named Scooby-Doo','https://image.tmdb.org/t/p/w500/txYnFha27iv9XUGizNeWBcfkSYu.jpg',1988,'Animation,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery','The world’s favorite chicken-hearted canine, as a puppy? That’s right! And the old gang is back with him. Shaggy, Daphne, Velma, and Freddy are all here as gangly kids — goofing off, solving kid-size mysteries, and having run-ins with ghouls, ghosts, and goblins.',3);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-salad-bowl-of-eccentrics','A Salad Bowl of Eccentrics','https://animedekho.app/wp-content/uploads/2024/05/a-salad.jpeg',2024,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub','Sosuke Kaburaya is a detective struggling to make ends meet. While on a case, he happens upon Sara da Odin, a princess from another world who wields magical powers. Sara quickly adjusts to modern Japanese life as Livia de Udis, a knight from Sara’s kingdom, arrives to find her. Soon enough, both Sara and Livia’s positivity begins to rub off on Sōsuke and the neighborhood’s cast of characters.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('a-wild-last-boss-appeared','A Wild Last Boss Appeared!','https://image.tmdb.org/t/p/w500/wgw4zcjGZ5fy6cVLYiraZofVngU.jpg',2025,'Action,Adventure,Anime,Crunchyroll,Drama,Hindi Dub,Isekai,Tamil,Telugu','An MMO gamer awakens as the Black-Winged Tyrant, Lufas Maphaahl, rising from her sealed fate—only to find this is very real. Her defeat 200 years ago unleashed monsters of death, and the legend is one of terror. Now, trapped in the body of history’s most feared conqueror, he must survive a world that wants her dead…and uncover why he’s here.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('aaron-stone','Aaron Stone','https://image.tmdb.org/t/p/w500/dp5SmLaTcr2v8ndBA6PCmOgJ9XZ.jpg',2009,'Action & Adventure,Comedy,Hindi Dub,Tamil,Telugu','Charlie Landers is a whiz at the online video game Hero Rising. In fact, he and his online avatar, Aaron Stone, hold its highest rank. But Charlie’s life is thrown into chaos when reclusive billionaire T. Abner Hall, creator of the game, asks Charlie to use his avatar to become a real-life crime-fighter. Aided by his Sentient Tactical Assisting Neohuman (S.T.A.N.), Charlie, as Aaron Stone, rights wrongs committed around the world by the Omega Defiance.',35);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('action-pack','Action Pack','https://image.tmdb.org/t/p/w500/uuDysbuWHcg2Xt5a0JsqAxeGH1X.jpg',2022,'Action & Adventure,Animation,Cartoon,Family,Hindi Dub,Kids','The heroic kids of the Action Academy take on the bad guys with their hearts, their wits and their superpowers, and bring out the best in them.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('adventure-time','Adventure Time','https://image.tmdb.org/t/p/w500/qk3eQ8jW4opJ48gFWYUXWaMT4l.jpg',2010,'Animation,Comedy,Sci-Fi & Fantasy','Hook up with Finn and Jake as they travel the Land of Ooo searching for adventure. But remember, adventure isn’t always easy. Sometimes you’ve got to battle fire gnomes that torture old ladies, save a smelly hot dog princess from the Ice King, and thaw out a bunch of frozen businessmen. What the cabbage?!',121);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('after-school-dice-club','After School Dice Club','https://image.tmdb.org/t/p/w500/2i8kS6Lyy3PX6bkQWPhKwMx0xvX.jpg',2019,'Anime,Comedy,Cute Girls Doing Cute Things,Hindi Dub,School,Shounen,Strategy Game,Tamil,Telugu','A story about girls playing board games after school!Kyoto in Spring. Aya is a high school girl who’s just moved to a new town. Miki is her shy classmate, and her first friend. One day after school Aya and Miki follow the committee president Midori to a speciality board games store. The Dice Club!! Without thinking they try out a German board game together.These girls, who are searching for fun, soon fall into the exciting world of games!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('agent-elvis','Agent Elvis','https://image.tmdb.org/t/p/w500/9iFMG4zyAkLnvfEwNqIiiEEQ342.jpg',2023,'Action,Adventure,Cartoon,Comedy,Crime,Hindi Dub,Thriller','Elvis Presley trades in his white jumpsuit for a jet pack when he is covertly inducted into a secret government spy program to help battle the dark forces that threaten the country he loves — all while holding down his day job as the King of Rock & Roll.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('agents-of-the-four-seasons-dance-of-spring','Agents of the Four Seasons Dance of Spring','https://image.tmdb.org/t/p/original/zbzbUDLO3iTAuXDmoqtpOsrtLPi.jpg',2026,'Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Romance,Tamil,Telugu,Urban Fantasy','When the Agent of Spring, Hinagiku Kayo, is abducted, spring itself vanishes—plunging the world into unending winter. Refusing to give up, her devoted guard, Sakura Himedaka, searches for her for years. When Hinagiku suddenly returns, the two set out to restore the lost season, face the past that tore them apart, and reclaim the warmth they refuse to lose again.',14);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('akebis-sailor-uniform','Akebi’s Sailor Uniform','https://image.tmdb.org/t/p/w500/Aan9h4TRapgXeqi4IQLfZZ2Hpyv.jpg',2022,'Anime,Comedy,Crunchyroll,Hindi Dub,School,Slice of Life,Tamil,Telugu','Akebi-chan no Sailor-fukuRobai Private Academy is a well-known girls’ junior high school in the countryside. Komichi Akebi is a girl who, for a certain reason, has dreamed of wearing a Robai Academy sailor uniform. Her dream comes true, and her heart races as the day of the school entrance ceremony arrives. With her heart set on her new sailor uniform, Komichi embarks on the junior high school life of her dreams. Komichi dashes headlong through days full of “firsts”—classmates, school lunches, club activities, and more—in this sparkling diary of girlhood. “I hope I can make a lot of friends.”',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('akudama-drive','Akudama Drive','https://image.tmdb.org/t/p/w500/1s3fwsH3AjuyzObYHiptiYRgFa.jpg',2020,'Action,Adventure,Crime,Crunchyroll,Fantasy,Gore,Hindi Dub,Mystery,Sci-Fi','Many years ago, a Great Civil War ravaged Japan, leaving the country fragmented between two regions: Kansai and Kanto. In Kansai, a group of six Akudama carry out missions given to them by a mysterious black cat, while evading the police. But a dangerous journey is about to unfold when a civilian girl becomes twisted into the Akudama’s way of life and witnesses their criminal drives.Note:In BluRay Episode 12 is Extended with Directors Cut, All Extended Scenes are in English Dub.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('aladdin','Aladdin','https://image.tmdb.org/t/p/w500/nlaiczW81kY46GBdfIcTrBIqr8I.jpg',1994,'Action & Adventure,Animation,Comedy,Kids,Sci-Fi & Fantasy','Aladdin is an animated television series made by Walt Disney Television which aired from 1994 to 1995, based on the original 1992 feature. It was animated at the Slightly Offbeat Productions Studios in Penrose, Auckland, New Zealand. Coming on the heels of the direct-to-video sequel The Return of Jafar, the series picked up where that installment left off, with Aladdin now living in the palace, engaged to beautiful and spunky Princess Jasmine. “Al” and Jasmine went together into peril among sorcerers, monsters, thieves, and more. Monkey sidekick Abu, the animated Magic Carpet, and the fast-talking, shape-shifting Genie came along to help, as did sassy, complaining parrot Iago, formerly Jafar’s pet but now an antihero. Jafar, having previously been destroyed in the second movie, returns in ',43);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('alya-sometimes-hides-her-feelings-in-russian','Alya Sometimes Hides Her Feelings in Russian','https://image.tmdb.org/t/p/w500/hfnzByZIRj6rx8xaxzS2zDilei1.jpg',2024,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,School,Tamil,Telugu','Alya is a transfer student enjoying popularity at her new high school, often sporting a cold shoulder while earning high marks in class. She ignores her nerdy classmate, Kuze Masachika, except for when she blurts out a flirtatious line to him in Russian. Little does she know, Kuze understands Russian, though he pretends not to. Let’s see where this wacky love story takes them!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ameku-m-d-doctor-detective','Ameku M.D.: Doctor Detective','https://image.tmdb.org/t/p/w500/mjTuJbgOssPGzCVGuqGxbnwS6iA.jpg',2025,'Adult Cast,Anime,Crunchyroll,Hindi Dub,Medical,Mystery','Ameku MD Doctor Detective, Ameku Takao’s Detective KarteTen’ikai General Hospital’s Supervisory Department of Diagnostic Pathology handles cases other physicians deem too difficult to treat. It’s also where bizarre mysteries surface, from unexplained illnesses to strange murders even the police can’t solve. At the center of it all is Takao Ameku, a brilliant doctor determined to reveal the shocking truth behind these anomalies.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('american-dragon-jake-long','American Dragon: Jake Long','https://image.tmdb.org/t/p/w500/sAgoJOdvuMa3DD0JDpos9bdaF9S.jpg',2005,'Action & Adventure,Cartoon,Comedy,Family,Hindi Dub,Tamil,Telugu','American Dragon is a coming of age comedy-action series about Jake Long, a 13-year-old Asian-American boy who strives to find balance in his life as a skateboard-grinding, New York ‘tween while learning to master his mystical powers (in his secret identity) as the American Dragon, the protector and guardian of all magical creatures secretly living amidst the human world.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('an-adventurers-daily-grind-at-age-29','An Adventurer’s Daily Grind at Age 29','https://image.tmdb.org/t/p/w500/tx6XZPOJ5UgVzvo8BXb2cNhFBq5.jpg',2026,'Anime,Crunchyroll,Fantasy,Hindi Dub,Shounen,Tamil,Telugu','Born and raised in the slums, 29-year-old adventurer Hajime Shinonome now lives a quiet life in Komai Village. But his peaceful days take a turn when he discovers Lirui, an abandoned young girl, being attacked by a slime. Moved by her desperation and reminded of his own past, he takes her back to the village. Hajime and Lirui begin a new chapter filled with unexpected challenges and gentle days!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('an-archdemons-dilemma-how-to-love-your-elf-bride','An Archdemon’s Dilemma: How to Love Your Elf Bride','https://image.tmdb.org/t/p/w500/yrtmTLOnHWJxlqDHNyxm0eUHr1U.jpg',2024,'Action,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Romance,Tamil,Telugu','Zagan might be the most feared evil sorcerer, but when it comes to social interactions, he’s the most inept. All those days studying the dark arts won’t help him when he falls in love at first sight with Nephelia, the beautiful elven slave, and spends his entire fortune to purchase her. With no clue how to talk to each other, the awkward arrangement for a bumbling sorcerer and timid elf begins.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('an-observation-log-of-my-fiancee-who-calls-herself-a-villainess','An Observation Log of My Fiancée Who Calls Herself a Villainess','https://image.tmdb.org/t/p/w500/ayhpfFHm1MtgPgLw3yN0euOUxsp.jpg',2026,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Tamil,Telugu,Villainess','Bertia is reincarnated into her favorite otome game—not as the heroine, but as the villainess engaged to the perfect Crown Prince Cecil! Fully aware that her role is to sabotage his future romance, she’s determined to bloom as a wicked flower and wither away according to the story. But no matter how hard she tries to scheme, her “evil” plans only make her more endearing!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('angry-birds-summer-madness','Angry Birds: Summer Madness','https://image.tmdb.org/t/p/w500/6ko4jfA5BrcRADDaAfMagZ4ZGpG.jpg',2022,'Adventure,Cartoon,Comedy,Hindi Dub,Kids','Teen birds Red, Chuck, Bomb and Stella are crashing through Camp Splinterwood with their fellow feathered campers for a summer of high-flying hijinks!',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ao-ashi','Ao Ashi','https://image.tmdb.org/t/p/w500/jz0agPanYP6MsjYSeGpZoAfUPjp.jpg',2022,'Anime,Hindi Dub,JioHotstar,Seinen,Sports','AoashiAshito Aoi is a young, aspiring soccer player from a backwater town in Japan. His hopes of getting into a high school with a good soccer club are dashed when he causes an incident during a critical match for his team, which results in their loss and elimination from the tournament. Nevertheless, he catches the eye of someone important who happened to be visiting from Tokyo. How will things turn out for Ashito?',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('arifureta-from-commonplace-to-worlds-strongest','Arifureta: From Commonplace to World’s Strongest','https://image.tmdb.org/t/p/w500/3Te6pYJNdh4YyWY1G7ANxNHpedi.jpg',2019,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation','Hajime Nagumo and his high school class are suddenly summoned to a fantastical land as heroes. But while most of his classmates have powerful stats and abilities, Hajime does not. Underappreciated and unprepared, he tumbles into the depths of a monster-infested dungeon where voracity and sacrifice are his only options. To thrive in this savage world, he’ll have no choice but to welcome the abyss.',44);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('arjun-prince-of-bali','Arjun – Prince of Bali','https://animedekho.app/wp-content/uploads/2024/05/arjun_poster_33.jpg',0,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Tamil,Telugu','Arjun, The Prince of Bali has to go on a journey along with his friends and his pet tiger Zimbu to find the seven pieces of a magical sword, the only weapon that can defeat the Evil Hiranya who has captured his kingdom and parents.',95);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('art-attack','Art Attack','https://image.tmdb.org/t/p/w500/o1QTIgwrkEqjrC4Q6sIWKZ61zcS.jpg',1990,'Hindi Dub,Kids,Tamil,Telugu','Art Attack is a British children’s television series revolving around art. The original series was one of CITV’s longest running programmes, running from 1990 to 2007, and was presented throughout by Neil Buchanan.The new series launched on Disney Junior on 6 June 2011 and was presented by Jassa Ahluwalia. Each show involved Ahluwalia voicing-over footage of an artist producing three works of art, taking the viewer through the various stages of production step by step.The show’s latest series is hosted by Lloyd Warbey. The new series launched on SAB TV on 10 June 2013 at 7 am IST.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('as-a-reincarnated-aristocrat-ill-use-my-appraisal-skill-to-rise-in-the-world','As a Reincarnated Aristocrat, I’ll Use My Appraisal Skill to Rise in the World','https://image.tmdb.org/t/p/w500/kYjQNi15IWz76nbqFBFPlVsO9lL.jpg',2024,'Adventure,Anime,Anime Times,Fantasy,Hindi Dub,Isekai,Kannada,Reincarnation,Tamil,Telugu','Ars Louvent is reincarnated in another world as the young son of a minor noble who owns a small domain. Ars is not particularly strong or intelligent, but he was born with the Appraisal Skill that’s able to see others’ abilities and statuses. He uses his skill to find the best hidden talents in the world to make their small, weak domain into the best.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('assassination-classroom','Assassination Classroom','https://image.tmdb.org/t/p/w500/wOd98jDHkoWy2LZ4gSy67X1ihv1.jpg',2015,'Action,Anime,Comedy,Crunchyroll,Hindi Dub,School,Shounen,Tamil,Telugu','The students of Class 3-E have a mission: kill their teacher before graduation. He has already destroyed the moon, and has promised to destroy the Earth if he can not be killed within a year. But how can this class of misfits kill a tentacled monster, capable of reaching Mach 20 speed, who may be the best teacher any of them have ever had?',47);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('attack-on-titan-muse-dub','Attack on Titan (Muse Dub)','https://image.tmdb.org/t/p/w500/fO1PhiBXn3S2KZuqJXm7HgPnk1F.jpg',2013,'Action,Anime,Drama,Gore,Hindi Dub,Military,Muse India,Shounen,Survival,Suspense,Tamil,Telugu','100 years ago, the last remnants of humanity were forced to retreat behind the towering walls of a fortified city to escape the massive, man-eating Titans that roamed the land outside their fortress. Only the members of the Scouting Legion dared to stray beyond the safety of the walls – but even those brave warriors seldom returned alive. Those within the city clung to the illusion of a peaceful existence until the day that dream was shattered, and their slim chance at survival was reduced to one horrifying choice: kill – or be devoured!',37);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('attack-on-titan','Attack on Titan (Anime Times Dub)','https://image.tmdb.org/t/p/w500/hTP1DtLGFamjfu8WqjnuQdP1n4i.jpg',2013,'Action,Anime,Anime Times,Drama,Gore,Hindi Dub,Kannada,Military,Shounen,Survival,Suspense,Tamil,Telugu','Many years ago, the last remnants of humanity were forced to retreat behind the towering walls of a fortified city to escape the massive, man-eating Titans that roamed the land outside their fortress. Only the heroic members of the Scouting Legion dared to stray beyond the safety of the walls – but even those brave warriors seldom returned alive. Those within the city clung to the illusion of a peaceful existence until the day that dream was shattered, and their slim chance at survival was reduced to one horrifying choice: kill – or be devoured!',97);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('avatar-the-last-airbender','Avatar: The Last Airbender','https://image.tmdb.org/t/p/w500/cHFZA8Tlv03nKTGXhLOYOLtqoSm.jpg',2005,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Malayalam,Sci-Fi,Tamil,Telugu','In a war-torn world of elemental magic, a young boy reawakens to undertake a dangerous mystic quest to fulfill his destiny as the Avatar, and bring peace to the world.',61);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('b-b-bujji-and-bhairava','Kalki 2898 AD Bujji and Bhairava','https://animedekho.app/wp-content/uploads/2024/05/BB_poster1_1717072010.avif',2024,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Mythology,Sci-Fi,Telugu','B & B: Bujji and BhairavaIt’s the year 2896, in future city of Kasi, Bhairava is a bounty hunter with dreams of getting into the Complex, and BU-JZ1, an AI pilot of a Cargo ship, waiting for her promotion. At their lowest point, these two unlikely souls, find each other to set off a crackling story of ambition, adventure, partnership and mainly friendship.',2);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('baahubali-the-lost-legends','Baahubali: The Lost Legends','https://image.tmdb.org/t/p/w500/rvBvJls25aMyYr2B1wIeCxBL5Wc.jpg',2017,'Action,Adventure,Cartoon,Hindi Dub,Kids,Tamil,Telugu','Animated series set before the Kalakeya invasion depicted in the movie, when Baahubali and Bhallaladeva are still both young princes of Mahizhmati.',71);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('baby-looney-tunes','Baby Looney Tunes','https://image.tmdb.org/t/p/w500/e1ZxhAH73P3q7kIUr03qNymPW0K.jpg',2002,'Cartoon,Comedy,Hindi Dub,Kids','The world’s most beloved animated characters as precocious preschoolers, discovering the world one baby step at a time.Episodes Arranged According to AMZN Release and IMDB in which S01 have 38 Episodes and Runtime 22min each. A/c to Wiki this post contains S01(13), S02(13), S03(12) and also Movie Specials included.Season 2 – Episode 4,7 and 12 are in English Only',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('baki-dou-the-invincible-samurai','BAKI-DOU: The Invincible Samurai','https://image.tmdb.org/t/p/w500/frtzbwANetYd0M4zdrZ5gx0E89q.jpg',2026,'Action,Anime,Gore,Hindi Dub,Martial Arts,Netflix,Shounen','Baki and the strongest Underground Arena fighters face a threat of historical proportions: the resurrected Musashi Miyamoto, Japan’s greatest samurai.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('baki-hanma','Baki Hanma','https://image.tmdb.org/t/p/w500/rRprMmPmeAWowqplv3k0v6glxqS.jpg',2021,'Action,Anime,Gore,Hindi Dub,Shounen,Sports','Hanma Baki: Son of OgreTo gain the skills he needs to surpass his powerful father, Baki enters Arizona State Prison to take on the notorious inmate known as Mr. Unchained.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('baki','BAKI','https://image.tmdb.org/t/p/w500/j4bL0G8h8k49MuXKYfZqhXqk2rI.jpg',2018,'Action & Adventure,Animation,Crime,Drama','While martial arts champion Baki Hanma trains hard to surpass his legendary father, five violent death row inmates descend upon Tokyo to take him on.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bakugan-battle-brawlers','Bakugan Battle Brawlers','https://image.tmdb.org/t/p/w500/eEx20DZuY23BqrZP1x5Ckfw8ORz.jpg',2007,'Action & Adventure,Animation,Anime,Hindi Dub,Sci-Fi & Fantasy','Centers on the lives of creatures called Bakugan and the battle brawlers who possess them.',28);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bakugan-battle-planet','Bakugan Battle Planet','https://image.tmdb.org/t/p/w500/go2IfyqSK7YJ403tvugctEQgjxQ.jpg',2018,'Action,Anime,Fantasy,Hindi Dub,Kids,Strategy Game','Follow the adventures of Dan Kouzo and his best friends: the first kids on Earth to bond with the mysterious creatures known as Bakugan!',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bat-fam','BAT-FAM','https://image.tmdb.org/t/p/w500/8C34YTylNBt4DWM1a9oAAXqmTSr.jpg',2025,'Animation,Family','Follow Batman, Alfred, and young Damian Wayne—who has taken on the mantle of Little Batman—alongside a few newcomers to Wayne Manor, as they navigate the fun and frustrations of life as a super family',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('banished-from-the-heros-party-i-decided-to-live-a-quiet-life-in-the-countryside','Banished from the Hero’s Party','https://image.tmdb.org/t/p/w500/hk5qqvJLRBDaPYBc8lKkSYQrR1c.jpg',2021,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Romance,Tamil,Telugu','Banished From The Hero’s Party, I Decided To Live A Quiet Life In The CountrysideAfter being betrayed by the Hero’s party, Red hopes to start anew by opening an apothecary in a small town. He wants to keep his past life secret, but it won’t be easy…especially when a beautiful adventurer from his past asks to move in.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('barbie-dreamhouse-adventures','Barbie: Dreamhouse Adventures','https://image.tmdb.org/t/p/w500/6MraV12DdZjQEgQztjTQ2s9t5CK.jpg',2018,'Cartoon,Family,Hindi Dub,Kids','Barbie Dreamhouse Adventures Go Team Roberts: Season 4-5Barbie, her sisters, friends and neighbour Ken share vlogs filmed in her Dreamhouse.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('barbie-dreamtopia','Barbie Dreamtopia','https://image.tmdb.org/t/p/w500/pZIqoUstOEyaoImA1Uk3lSNO5hq.jpg',2017,'Cartoon,Family,Hindi Dub,Kids','Barbie and her sister, Chelsea, take an adventure through incredible lands and unbelievable sights, like rainbow rivers and cotton candy clouds, which stir their imagination.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('barbie-it-takes-two','Barbie: It Takes Two','https://image.tmdb.org/t/p/w500/4KFeoNVIAKKxETRrbika8mAbswl.jpg',2022,'Cartoon,Family,Hindi Dub,Kids','Barbie “Malibu” Roberts and Barbie “Brooklyn” Roberts chase their dreams of musical stardom.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bartender-glass-of-god-hindi','BARTENDER Glass of God','https://animedekho.app/wp-content/uploads/2024/05/Bartender.Kami_.no_.Glass_.600.4148131.jpg',2024,'Anime,Crunchyroll,Drama,Gourmet,Hindi Dub,Seinen,Workplace','At Eden Hall, each glass has a story. A quiet bar lies tucked away in the streets of Tokyo, and it seems only the most desperate souls burdened by their own troubles manage to find its doors. But after a glass of God poured by the brilliant bartender Ryu, they leave renewed. Ryu has a gift—he knows how to soothe the soul with the perfect drink. Who will he meet next?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('batman-the-animated-series','Batman: The Animated Series','https://image.tmdb.org/t/p/w500/9P3FQqRuFJSjQHO2a1nDsfVxBGi.jpg',1992,'Action,Adventure,Cartoon,Crime,Drama,Hindi Dub,Mystery','Vowing to avenge the murder of his parents, Bruce Wayne devotes his life to wiping out crime in Gotham City as the masked vigilante “Batman”.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('batwheels','Batwheels','https://image.tmdb.org/t/p/w500/2ULWo7qnQvj6KkcgLEOYfwbkspQ.jpg',2022,'Cartoon,Comedy,Hindi Dub,Kids,Super Power','The Batwheels are a team of sentient super-powered crimefighting vehicles that help Batman, Robin and Batgirl—as well as a host of additional DC Super Heroes—keep Gotham City safe. Created only recently by the Batcomputer, our mechanized heroes must navigate the growing pains of being a newly formed super-team as well as the growing pains that come with just being a kid.',19);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('be-cool-scooby-doo','Be Cool, Scooby-Doo!','https://image.tmdb.org/t/p/w500/rJksJvJnvrVQL9dMdqy1XwjD5KQ.jpg',2015,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Be Cool Scooby Doo!Be Cool ScoobyDoo!The gang decide to go traveling in the Mystery Machine, seeking fun and adventure during what could possibly be their last summer break together. However, havoc-wreaking monsters seem to be drawn to them, appearing almost every stop of the way.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bee-and-puppycat-lazy-in-space','Bee and PuppyCat: Lazy in Space','https://image.tmdb.org/t/p/w500/gqn9QudYySxvzyMJ4HNwx5qLbli.jpg',2022,'Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','Bee is a young lady trying to make her way in the world. She often acts before thinking, which can lead her into trouble (and adventure!). She also has a strong, nurturing personality, and doesn’t think twice about taking in Puppycat when he needs help. Although her laid-back-space-casey attitude and lack of skills tend to keep her from maintaining a job for long in the human world, she isn’t someone who easily gives up, and with the experiences she gains at the magical temp agency she stumbles on, she’ll finally have the chance to find out what she’s meant to do with her life.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ben-10-alien-force','Ben 10: Alien Force','https://image.tmdb.org/t/p/w500/pGhCUqPaXZ0Xp4dUCT7Q6hjJArf.jpg',2008,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Five years later, 15-year-old Ben Tennyson chooses to once again put on the Omnitrix and discovers that it has reconfigured his Dna and can now transform him into 10 brand new aliens. Joined by his super-powered cousin Gwen Tennyson and his equally powerful former enemy Kevin Levin, Ben is on a mission to find his missing Grandpa Max. In order to save his Grandpa, Ben must defeat the evil Dnaliens, a powerful alien race intent on destroying the galaxy, starting with planet Earth.',46);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ben-10-omniverse','Ben 10: Omniverse','https://image.tmdb.org/t/p/w500/Re9I5tauOspaJxYCIqRqavKT4F.jpg',2012,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','A year after the events that took place during the “Final Battle” and after the destruction of Omnitrix, 16-year-old Ben Tennyson has to face new enemies.',80);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ben-10-reboot','Ben 10 Reboot','https://image.tmdb.org/t/p/w500/a4H0UR7aUkGZlT6Q9r9grBrjJWR.jpg',2016,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Kids,Sci-Fi','With the fifth offshoot of the “Ben 10” franchise, the animated series returns to its roots and its original name, bringing teenager Benjamin “Ben” Tennyson, his cousin Gwen and Grandpa Max back to life on a new summer vacation journey. As in the original, the stories in the remake of the series also spin around an alien wristwatch called “Omnitrix,” with the help of Ben can turn into ten different friendly aliens, which come up with different supernatural powers. He fights enemy aliens and experiences with grandfather and cousin the most exciting vacation imaginable.Please Note That Episode Numbers and Name Will not Match Because Episode List is Imported From TheMovieDatabse But Episodes are Ripped From Amazon Prime (Different Order)',100);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ben-10-ultimate-alien','Ben 10: Ultimate Alien','https://image.tmdb.org/t/p/w500/rPL79g4jFntZBJJqxKhWrnXxKQg.jpg',2010,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','With his secret identity now revealed to the world, Ben Tennyson continues to fight evil as a superhero with the help of the newly acquired Ultimatrix.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ben-10','Ben 10 Classic','https://image.tmdb.org/t/p/w500/pT0NlYVIkwM2zAw9oUkePwrOlxW.jpg',2005,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Ben 10 ClassicWhen 10-year-old Ben Tennyson discovers a mysterious device, he gains the power to change into ten different alien heroes, each with uniquely awesome powers. With such abilities at his disposal, Ben realizes a greater responsibility to help others and stop evildoers, but that doesn’t mean he’s above a little superpowered mischief now and then.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bernard','Bernard','https://image.tmdb.org/t/p/w500/9SXIJY21rm67eQvlPBTTXIiRumG.jpg',2006,'Animation,Cartoon,Comedy,Hindi Dub','Bernard is a series of animated shorts centered on the fictional polar bear and main character of the same name. It is a Korean-Spanish-French co-production.Each three-minute episode focuses on the bear’s curiosity and have many moments of slapstick. Bernard never speaks with the exception of unintelligible noises.Bernard is accompanied in the cartoons by a few other characters: Lloyd and Eva the penguins, Zack the lizard, Goliat the chihuahua, Sam the baby, Pilot the dog, Pokey the porcupine and Santa Claus.He usually gets knocked unconscious or severely injured at the end of an episode, due to some calamity caused by his bumbling.',156);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('berserk-of-gluttony','Berserk of Gluttony','https://image.tmdb.org/t/p/w500/wQMcq5YUjMfoIEqLRzrNQVt4ROl.jpg',2023,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu','Fate Graphite was born into a world where magical skills shape your destiny. His skill is Gluttony, a seemingly useless curse of unending hunger that has left him shunned and looked down upon. Until one day, after he takes the life of a thief, his true power awakens: he can devour the skill of anyone he kills to feed his appetite. Will he learn to control this gruesome ability for the better?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('best-of-luck-nikki','Best of Luck Nikki','https://image.tmdb.org/t/p/w500/oHZ4ZGgeF3AtsBXu3HyUMkZvpn7.jpg',2011,'Comedy,Hindi Dub,Live-Action,Tamil,Telugu','Dolly creates a video diary for Nikki about their family and life which shows what she might go through in the future so that she can always know how to figure things out when she gets older.Please note that episode number and name might not match. Season 3-4-5 not Available in Tamil-Telugu',100);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('beyblade-burst','Beyblade Burst','https://image.tmdb.org/t/p/w500/9Nr7ZDlBV8Jt2NiiuCsc25W9cIG.jpg',2016,'Action,Adventure,Anime,Hindi Dub,Kids,Sci-Fi,Sports,Tamil,Telugu','Beyblade Burst (Burst Saga – Season 1)Beyblade Burst Evolution/God (Burst Saga – Season 2)Beyblade Burst Turbo/Super Z (Burst Saga – Season 3)Beyblade Burst Rise/GT (Burst Saga – Season 4)Beyblade Burst Surge/Sparking/Superking (Burst Saga – Season 5)Beyblade Burst QuadDrive/Dynamite Battle/DB (Burst Saga – Season 6)The story revolves around Valt Aoi and Shu Kurenai as well as their teammates, Rantaro Kiyama, Daina Kurogami and Wakiya Komurasaki at the Beigoma Academy school in Japan. When not studying, the close friends are obsessed with their Beyblade, creating a school bey club later in the season and challenging each other to battles at their Bey Stadium. The friends eventually become friendly rivals as they compete against each other in a competition to claim the title of Japan’s top ',231);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('beyblade-metal-saga','Beyblade: Metal Saga','https://image.tmdb.org/t/p/w500/AdkdM97Sa7SXLZA9bOkm610Y7Ab.jpg',2009,'Action,Adventure,Anime,Hindi Dub,Kids,Sci-Fi,Sports','Beyblade Metal Fusion (Metal Saga – Season 1)Beyblade Metal Masters (Metal Saga – Season 2)Beyblade Metal Fury (Metal Saga – Season 3)A new cast of characters take on the continued battle between good and evil. Ginga, our hero, and his group of loyal friends take on a dangerous group called the Dark Nebula. Dark Nebula’s mission is to take over the world and unleash their evil upon it; but before they can do so, they must destroy Ginga as he is the only person that’s strong enough to stand in their way. The plot thickens as friends become enemies and enemies become allies. Everything starts and ends with Ginga as he struggles to find the strength to defend his world and the honor of Beyblade.',141);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('beyblade-shogun-steel','Beyblade: Shogun Steel','https://image.tmdb.org/t/p/w500/iC0Lrx5PZ5eeAKPApTrS07vC4ho.jpg',2012,'Action,Adventure,Anime,Hindi Dub,Kids,Sci-Fi,Sports,Tamil,Telugu','Beyblade Shogun Steel (Metal Saga – Season 4)It’s time for an ALL-NEW generation to battle it out in the action-packed story of BEYBLADE: Shogun Steel! The WBBA has worked tirelessly over the last 7 years to rebuild the BEYBLADE world by introducing a new Bey system and train the next generation of Bladers. Zyro Kurogane aspires to be just like Gingka and become the World’s Best Blader. With the help of his new friends, Zyro trains hard, gains strength and learns ground-breaking new battle techniques along the way! Unknowingly, there are mysterious and sinister powers at work with plots to take over the WBBA! Friends will battle each other and dark forces come out of the shadows, in and unprecedented event where totally strategic new combinations create EVEN MORE powerful NEW Beys! Will Zy',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('beyblade','Beyblade','https://image.tmdb.org/t/p/w500/l6ZQhEHjtOd9t6lOvVGzs5YEHcG.jpg',2001,'Action,Adventure,Anime,Hindi Dub,Kids,Sci-Fi,Sports','Beyblade Original SeriesBeyblade (Season 1)Beyblade V-force (Season 2)Beyblade G-revolution (Season 3)Thirteen-year-old Tyson Granger (Takao Kinomiya), along with his fellow teammates, Kai Hiwatari, Max Tate (Max Mizuhura), and Ray Kon (Rei Kon), strive to become the greatest Beybladers in the world. With the technical help of the team’s resident genius, Kenny (Kyouju), and with the powerful strength of their BitBeasts, the Bladebreakers armed with their tops (AKA: Blades) attempt to reach their goal.',154);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('beywheelz','BeyWheelz / BeyWarriors','https://image.tmdb.org/t/p/w500/8xN1xNPzvxNMZlc7c9FsNbk1wN5.jpg',2012,'Action,Adventure,Anime,Hindi Dub,Kids,Sci-Fi,Sports','Beywheelz (Beyblade Spinoff – Season 1)Beywarriors Beyraiderz/Shogun (Beyblade Spinoff – Season 2)Beywarriors Cyborg (Beyblade Spinoff – Season 3)BeyWheelz: Powered by Beyblade, commonly referred to as BeyWheelz is a anime mini-series based on the, Hasbro toyline, BeyWheelz. It was commissioned by Nelvana and is produced by Synergy SP and d-rights.',54);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bharat-hain-hum','Bharat Hain Hum','https://animedekho.app/wp-content/uploads/2024/05/bharat-hai-hum.jpg',0,'Cartoon,Hindi Dub,History,Kannada,Malayalam,Tamil,Telugu','Krish, Trish & Baltiboy Bharat Hain HumKTB Bharat Hai HumThe journey of some of the most prominent yet unrecognised freedom fighters who played a pivotal role in securing independence from the British.India has been attacked by so many foreign invaders for its riches. We had to fight so many battles till we eventually won our freedom from the British on 15th of August, 1947. The iconic trio Krish, Trish and Baltiboy present the stories about the heroes who fought the war of freedom. This series attempts to bring alive glorious tales of valour and sacrifice using the medium of animation.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('big-city-greens','Big City Greens','https://image.tmdb.org/t/p/w500/buRk2Vrz8UhF5nZUOADSRZLEU1f.jpg',2018,'Animation,Comedy,Family','The offbeat adventures of 10-year-old Cricket Green, a mischievous and optimistic country boy who moves to the big city with his wildly out of place family – older sister Tilly, father Bill and Gramma Alice.',30);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('big-hero-6-the-series','Big Hero 6 The Series','https://image.tmdb.org/t/p/w500/ldG4xXImCPyv5U5gbRmlB8On842.jpg',2017,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Tamil,Telugu','Picking up immediately following the events in the feature film, these are the continuing adventures and friendship of 14-year-old tech genius Hiro and his compassionate, cutting-edge robot Baymax. As the new prodigy at San Fransokyo Institute of Technology, Hiro now faces daunting academic challenges and the social trials of being the little man on campus. Off campus, the stakes are raised for the high-tech heroes as they must protect their city from an array of scientifically enhanced villains.',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('billy-dilleys-super-duper-subterranean-summer','Billy Dilley’s Super-Duper Subterranean Summer','https://image.tmdb.org/t/p/w500/c5Uv3AcLG1Uce4NsqmGBhk7p477.jpg',2017,'Animation,Cartoon,Comedy,Hindi Dub,Tamil,Telugu','The adventures of science-obsessed Billy Dilley and his lab partners Zeke and Marsha',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('black-butler','Black Butler','https://image.tmdb.org/t/p/w500/xfkfvQixv1C5kyVvx9nN93LBRIP.jpg',2008,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,Historical,Mystery,Mythology,School,Shounen,Tamil,Telugu','Black Butler Season 4: Public School ArcButler Sebastian Michaelis works with his 13-year-old master, the earl Ciel Phantomhive, to do the dirty work of “the Queen’s guard dog” in nineteenth century England’s gritty underworld.One day, Ciel receives a letter from Queen Victoria telling him that several students at Weston College, one of England’s top public schools, have seemingly disappeared… including a relative of hers named Derrick. And so, Sebastian and Ciel infiltrate Weston College to get the bottom of the matter. What truly happened to these students?',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('black-clover','Black Clover','https://image.tmdb.org/t/p/w500/yCk1EaEaH0kfyut1KBodZaReJ5z.jpg',2017,'Action,Anime,Comedy,Fantasy,Hindi Dub,Malayalam,Shounen,Tamil','Asta and Yuno are two orphans who want the same thing: to become the Wizard King. Locked in a friendly rivalry, they work hard towards their goal. While Yuno excels at magic, Asta has a problem uncommon in this world: he has no powers! But, on the day they receive their grimoires, they surprise everyone. To reach their goal, they’ll each find their own path to greatness—with or without magic.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('black-rock-shooter-dawn-fall','Black Rock Shooter: Dawn Fall','https://image.tmdb.org/t/p/w500/fjwT6zU73MTptIkqta16dBKycGq.jpg',2022,'Action,Adventure,Anime,Drama,Fantasy,Hindi Dub,Sci-Fi','BlackRock Shooter: Dawn FallThe year is 2062. Earth has been left in ruin after the failure of a labor automation project when the AI called Artemis waged war against humanity. A girl, Empress, awakens in a research lab. As one of the three surviving guardians, she must destroy the Orbital Elevator before Artemis can complete its construction. Failure will result in a machine army overrunning Earth.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('black-torch','BLACK TORCH','https://image.tmdb.org/t/p/original/fkZ19fifxAOAxbE2ZJvXGVvDDGs.jpg',2026,'Action & Adventure,Animation,Hindi Dub,Mystery,Sci-Fi & Fantasy','Jiro Azuma is no average high schooler. A descendant of ninjas and trained in the ancient warrior art of the shinobi, Jiro is also able to talk with animals. After a mysterious encounter with an injured cat named Rago, Jiro discovers the feline is actually the legendary Black Star of Doom! Joined by the Bureau of Espionage, they fight off swarms of mononoke lying in wait to exploit Rago’s powers.',5);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('blade-anime','Blade Anime','https://image.tmdb.org/t/p/w500/ql9YpFD8J1zeWzLMHHjp4nKKD4n.jpg',2011,'Action,Drama,Hindi Dub,Vampire','Legendary half-vampire, half-human vampire hunter Blade is tracking Deacon Frost, a very powerful and influential vampire who killed his mother and who heads Existence, a secretive vampire organization that operates in Southeast Asia.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('blazing-team-masters-of-yo-kwon-do','Blazing Team: Masters of Yo Kwon Do','https://image.tmdb.org/t/p/w500/s9Xu9Hu81ri1eKFoVUF06liXOoI.jpg',2015,'Action,Adventure,Anime,Hindi Dub,Kids','As a mysterious ‘darkness’ rises, a group of heroic teens is assembled to harness the awesome mystical power of YO KWON DO, a practice that defeats evil by blending the skill of yo-yo with the martial art of Kung Fu.',42);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bleach-hindi','Bleach','https://image.tmdb.org/t/p/w500/7bSQNQuhHeInFMfzMwevfCiqcTm.jpg',2004,'Action,Adventure,Anime,Hindi Dub,Shounen,Supernatural','For as long as he can remember, Ichigo Kurosaki has been able to see ghosts. But when he meets Rukia, a Soul Reaper who battles evil spirits known as Hollows, he finds his life is changed forever. Now, with a newfound wealth of spiritual energy, Ichigo discovers his true calling: to protect the living and the dead from evil.',51);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bleach','Bleach: Thousand-Year Blood War','https://image.tmdb.org/t/p/original/xAiiPhRm1zOyPwBLjcA2RsFtG8G.jpgXe72ogD0EaWM8gqa0ccIw.jpg',2004,'Action,Adventure,Anime,Hindi Dub,Shounen,Supernatural','For as long as he can remember, Ichigo Kurosaki has been able to see ghosts. But when he meets Rukia, a Soul Reaper who battles evil spirits known as Hollows, he finds his life is changed forever. Now, with a newfound wealth of spiritual energy, Ichigo discovers his true calling: to protect the living and the dead from evil.',48);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('blood-of-zeus','Blood of Zeus','https://image.tmdb.org/t/p/w500/zXRR5tgGLtKrRmuN4ko9SLAdCiZ.jpg',2020,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi','In a brewing war between the gods of Olympus and the titans, Heron, a commoner living on the outskirts of ancient Greece, becomes mankind’s best hope of surviving an evil demon army, when he discovers the secrets of his past.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('blue-eye-samurai','BLUE EYE SAMURAI','https://image.tmdb.org/t/p/w500/fXm3JT4WLQVnwukdvghtAblc1wc.jpg',2023,'Action,Adventure,Cartoon,Drama,Hindi Dub','Driven by a dream of revenge against those who made her an outcast in Edo-period Japan, a young warrior cuts a bloody path toward her destiny.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('blue-lock-hindi','BLUE LOCK','https://image.tmdb.org/t/p/w500/tP16wAT98CLwnQ14iWTMZZwfLBr.jpg',2022,'Anime,Crunchyroll,Drama,Hindi Dub,Shounen,Sports,Tamil,Telugu,Thriller','After a disastrous defeat at the 2018 World Cup, Japan’s team struggles to regroup. But what’s missing? An absolute Ace Striker, who can guide them to the win. The Japan Football Union is hell-bent on creating a striker who hungers for goals and thirsts for victory, and who can be the decisive instrument in turning around a losing match…and to do so, they’ve gathered 300 of Japan’s best and brightest youth players. Who will emerge to lead the team…and will they be able to out-muscle and out-ego everyone who stands in their way?',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bob-the-builder','Bob the Builder','https://image.tmdb.org/t/p/w500/shADJt16bXpuyGphWCTg17tMN3u.jpg',1999,'Cartoon,Comedy,Family,Hindi Dub,Kids','Bob the Builder and his machine team are ready to tackle any project. Bob and the Can-Do Crew demonstrate the power of positive thinking, problem-solving, teamwork, and follow-through. The team always shows that “The Fun Is In Getting It Done!”',78);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('boboiboy','BoBoiBoy','https://image.tmdb.org/t/p/w500/zRZ1Y90mhKXrLDYnnfJf4By8hca.jpg',2011,'Action,Cartoon,Hindi Dub,Kids','A kid name boboiboy found out there was an alien that try to invade their planet.a robot name ochobot give boboiboy and his friend a power to save their planet',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bofuri-i-dont-want-to-get-hurt-so-ill-max-out-my-defense','BOFURI: I Don’t Want to Get Hurt, so I’ll Max Out My Defense.','https://image.tmdb.org/t/p/w500/wwxVI9a0jrxRx8U5Auf90YP1O1M.jpg',2020,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Video Game','Kaede Honjou is invited by her friend Risa Shiramine to play a virtual reality MMO game with her. While Kaede doesn’t dislike games, what she really, truly dislikes is being in pain. She creates a character named Maple, and decides to put all her points in VIT to minimize pain. As a result, she moves slowly, can’t use magic, and even a rabbit can get the best of her. But as it turns out, she acquires a skill known as “Absolute Defense” as a result of her pumping points into VIT, as well as a “Counter Skill” that works against special moves. Now, with her ability to nullify all damage, she goes on adventures.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bubu-chacha','BuBu ChaCha','https://image.tmdb.org/t/p/w500/fUU72WS8irv4JWAdujNmu7LP1jz.jpg',1999,'Anime,Bengali,Hindi Dub,Kids,Malayalam,Tamil,Telugu','Randy and ChaCha (Randy’s pet dog) are best of friends. One day, ChaCha passes away, and turns into a star to watch over Randy. But ChaCha decides to return to Randy in the form of a toy car. Randy and ChaCha keep this secret to their own selves, and off they go to their adventures, where they learn that every little thing is a big discovery.',17);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bucchigiri','BUCCHIGIRI?!','https://image.tmdb.org/t/p/w500/bhtkmLdMleHtGTq267VqhePgp5S.jpg',2024,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,School,Tamil,Telugu','Arajin Tomoshibi’s reunion with his old pal Matakara Asamine takes an unexpected turn when they stumble into a brawl with the toughest guys in town. And just when you thought things couldn’t get weirder, a colossal genie decides to drop in. Brace yourself for the ultimate showdown. It’s the clash of the cool and the magical!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('buddy-daddies','Buddy Daddies','https://image.tmdb.org/t/p/w500/qjRWZ1Ak9Ag6EvcA5LNhphqX8oV.jpg',2023,'Action,Anime,Comedy,Crime,Crunchyroll,Hindi Dub','When two hit men take out a dangerous mobster, the last thing they expect is for him to have a four-year-old daughter – now an orphan. But when they decide to take custody of the child, their life turns upside down! Between a mission here and a shootout there, the two hired killers will have to find time to prepare nutritious meals, stimulate the child’s intellectual growth, and take the little one to daycare!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('buzz-lightyear-of-star-command','Buzz Lightyear of Star Command','https://image.tmdb.org/t/p/w500/jxxwtAbfG4es0rWOUQ5NFJ354nH.jpg',2000,'Animation,Cartoon,Comedy,Family,Hindi Dub,Kids,Sci-Fi & Fantasy,Tamil,Telugu','Buzz Lightyear of Star Command is an American animated science fiction/adventure/comedy series produced by Walt Disney Television Animation. The series originally aired on UPN and ABC from October 2000 to January 2001 as part of Disney’s One Saturday Morning programming block. It follows the adventures of space ranger Buzz Lightyear, who first appeared in the film Toy Story as an action figure and one of the film’s protagonists.',15);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('bye-bye-earth','Bye Bye, Earth','https://image.tmdb.org/t/p/w500/hBsy7irEeiSNRYuNopi2c7qdD4q.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu','Belle Lablac doesn’t really fit in as the only human being in a world full of anthropomorphic animals. No fangs, no fur, no scales, no claws. Lonely and eager to discover where she comes from, Belle journeys to find answers to the questions of her heart. Carrying nothing but her giant sword, the Runding, she faces a world of possibilities and pitfalls in hopes of discovering the truth.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('campfire-cooking-in-another-world-with-my-absurd-skill','Campfire Cooking in Another World with My Absurd Skill','https://image.tmdb.org/t/p/w500/rAfnEjWKCam13IFFIrzAzep4hIH.jpg',2023,'Adventure,Anime,Comedy,Fantasy,Gourmet,Hindi Dub,Isekai','Tsuyoshi Mukohda, an ordinary salaryman, is suddenly transported to another world one day. The unique skill he gains upon arrival in this world is the seemingly useless “Online Grocery.” Mukohda is discouraged at first, but the modern foods he’s able to bring to his new world using this skill prove to have some unbelievable effects!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('captain-laserhawk-a-blood-dragon-remix','Captain Laserhawk: A Blood Dragon Remix','https://image.tmdb.org/t/p/w500/o2sjO1T4h1PkLoW3cnQ8vwGAKDf.jpg',2023,'Action,Adventure,Cartoon,Comedy,Drama,Hindi Dub,Sci-Fi','Branded an enemy of the state, a cyborg supersoldier struggles to find a cause worth fighting for in a dystopian society where nothing is what it seems.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('captain-tsubasa','Captain Tsubasa','https://image.tmdb.org/t/p/w500/zHgc9nTXiP77qoy14BO7WUFTwkp.jpg',2018,'Anime,Anime Times,Comedy,Drama,Hindi Dub,Shounen,Sports','The passionate story of an elementary school student whose thoughts and dreams revolve almost entirely around the love of soccer. 11-year-old Tsubasa Oozora started playing football at a very young age, and while it was mostly just a recreational sport for his friends, for him, it developed into something of an obsession. In order to pursue his dream to the best of his elementary school abilities, Tsubasa moves with his mother to Nankatsu city, which is well-known for its excellent elementary school soccer teams. But although he was easily the best in his old town, Nankatsu has a lot more competition, and he will need all of his skill and talent in order to stand out from this new crowd.',86);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('case-closed-the-culprit-hanzawa','Detective Conan: The Culprit Hanzawa','https://image.tmdb.org/t/p/w500/gL8OdtyhWQ9i8vY7CbmJtqSbMPC.jpg',2022,'Animation,Anime,Comedy,Hindi Dub','A silhouetted suspect moves to the crime-infested town of Beika with murder in mind, in this spinoff spoof of “Detective Conan.”',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('case-closed-zeros-tea-time','Detective Conan: Zeros Tea Time','https://image.tmdb.org/t/p/w500/e5T5tLm2EqzfjxhYNEchcuzyLcs.jpg',2022,'Animation,Anime,Drama,Hindi Dub,Mystery','A detective who’s also a public security agent and a member of a shadowy organization juggles his triple identities.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('castlevania-nocturne','Castlevania: Nocturne','https://image.tmdb.org/t/p/w500/tslJx5LPn2aXX3USGYbh0KbglnB.jpg',2023,'Action,Adventure,Cartoon,Drama,Fantasy,Hindi Dub,Sci-Fi','In the thick of the French Revolution, members of the so-called lower classes are rising up to fight inequality. Meanwhile, Richter Belmont senses a far grimmer and greater danger. He’s picked up his family’s long-held tradition of vampire hunting, a vocation that goes back almost as long as a vampiric life span (in other words, forever) but he’s never seen anything quite like what he’s witnessing now.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('catch-me-at-the-ballpark','Catch Me at the Ballpark!','https://image.tmdb.org/t/p/w500/iJLVG8W3kp0JTPejChjPWrXEwI3.jpg',2025,'Adult Cast,Anime,Comedy,Crunchyroll,Hindi Dub,Seinen,Sports','To escape his tiring job, weary Murata finds escape at a nearby baseball stadium. While the games are thrilling, it’s Ruriko, the gyaru as cold as the beer she serves but secretly a sweetheart, who keeps him coming back. As her first regular, Murata discovers the warmth behind her frosty demeanor, and their hilarious, heartwarming encounters light up the ballpark and maybe even their hearts.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('cells-at-work-code-black','Cells at Work! CODE BLACK','https://image.tmdb.org/t/p/original/lZQKzmE3P5CJ9Bj0wK4jMZuengp.jpg',2021,'Action & Adventure,Animation,Anime,Hindi Dub','Alcohol, smoking, and stress—in the body subjected to these irritants, the cells responsible for maintaining life seem to fight a war that never ends. Due to a severe shortage of workers, Red Blood Cell AA2153 has to quickly learn to deliver oxygen and collect carbon dioxide, even in dangerous conditions. Meanwhile, White Blood Cell U-1196 has to do her part by dealing with germs and viruses during life-threatening situations. In the midst of these crises, they have to work together to keep the body healthy, despite not knowing if their sacrifices will be worthwhile. Cells at Work! Code Black takes a different approach by showing the grittier side of the jobs our cells perform.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('chainsaw-man','Chainsaw Man','https://image.tmdb.org/t/p/w500/npdB6eFzizki0WaZ1OvKcJrWe97.jpg',2022,'Action,Comedy,Crunchyroll,Fantasy,Gore,Hindi Dub,Shounen','Denji has a simple dream—to live a happy and peaceful life, spending time with a girl he likes. This is a far cry from reality, however, as Denji is forced by the yakuza into killing devils in order to pay off his crushing debts. Using his pet devil Pochita as a weapon, he is ready to do anything for a bit of cash.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('chainsmoker-cat','Chainsmoker Cat','https://image.tmdb.org/t/p/original/kqeKlSd7o9BCbTraZsDnksRSfxm.jpg',2026,'Animation,Anime,Comedy,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Catgirl Yani struggles to pay her rent and keep a job while feeding her smoking habit. As her loved ones’ concerns grow, she must rethink her future.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('chillin-in-another-world-with-level-2-super-cheat-powers','Chillin’ in Another World with Level 2 (Tamil-Telugu)','https://image.tmdb.org/t/p/w500/3eBu6hYDRe72ZPUfLbhaHfF7EM9.jpg',2024,'Adventure,Anime,Crunchyroll,Fantasy,Isekai,Romance,Tamil,Telugu','Chillin’ in Another World with Level 2 Super Cheat PowersThe Magical Kingdom of Klyrode summons hundreds of heroes from other worlds every year to fight in their war against the Dark One and his army of powerful demons. Banaza is one of those heroes, summoned from the Royal Capital Paluma, but something’s not right—Banaza is only an average merchant. He has no magic, no fighting ability, and his stats are abysmal. Worse, a mishap leaves him unable to return home! Rejected as a hero and stranded in another world, abandoned to the far reaches of the kingdom by a cruel king who just wants him gone, Banaza’s fate looks pretty bleak. But what will happen once the failed hero candidate finds himself with super cheat powers once he hits level two?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('cinderella-chef','Cinderella Chef','https://image.tmdb.org/t/p/original/1cbkl8loxuF6BgUoPTVjcorad27.jpg',2018,'Action & Adventure,Animation,Anime,Comedy,Drama,Hindi Dub','Ye Jiayao finds herself back in time in the body of Ye Jinxuan. After many twists, she thought that she would finally be able to lead a simple life and achieve her dream of opening the best restaurant in Huai Song. However, there are villains constantly trying to bring her down.',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('classroom-of-the-elite','Classroom of the Elite','https://image.tmdb.org/t/p/w500/yuHanbUUIv2UWRxxQFt9n8jtmOJ.jpg',2017,'Anime,Drama,Hindi Dub,Psychological,School,Suspense','Kiyotaka Ayanokoji has just enrolled at Tokyo Koudo Ikusei Senior High School, where it’s said that 100% of students go on to college or find employment. But he ends up in Class 1-D, which is full of all the school’s problem children.What’s more, every month, the school awards students points with a cash value of 100,000 yen, and the classes employ a laissez-faire policy in which talking, sleeping, and even sabotage are permitted during class.One month later, Ayanokoji, Horikita, and the students of Class D learn the truth of the system in place within their school…',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('clevatess','Clevatess','https://image.tmdb.org/t/p/original/qJc32lffkMs34KfltQITySHAbJ0.jpg',2025,'Action,Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Tamil,Telugu','One of the Lords of Dark Beasts, Clevatess’s reign shatters when he revives a hero he personally slayed and adopts an orphaned humanoid baby—the last hope to save a dying world. Now bound together, what fate awaits this unlikely trio?',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('codename-kids-next-door','Codename: Kids Next Door','https://image.tmdb.org/t/p/w500/ppM8Pl6e8JIr39HPLRFgqDH3Vf1.jpg',2002,'Action & Adventure,Animation,Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy','Taking numbers instead of names, five extraordinary 10-year-olds form a covert team called the Kids Next Door with one dedicated mission: to free all children from the tyrannical rule of adults.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('courage-the-cowardly-dog','Courage the Cowardly Dog','https://image.tmdb.org/t/p/w500/dzD8EWDvtg7rBCINu0RCH5EUejh.jpg',1999,'Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','The bizarre misadventures of a cowardly dog named Courage and his elderly owners in a farmhouse in Nowhere, Kansas.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('crayon-shin-chan-spin-off','Crayon Shin-chan Spin-off','https://image.tmdb.org/t/p/w500/zL7zV68jIpq2IBOtlK38mlwfgI9.jpg',2016,'Animation,Comedy,Kids','Unlike the main television anime series which is mostly set in modern-day Japan, the new series will be a “sealed room” suspense comedy set 100 years in the future. The story begins when Shinnosuke and the entire Nohara family wake up from cold sleep to find themselves aboard a space ship drifting in space. The anime will depict the various events that take place inside the ship.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dan-da-dan','Dan Da Dan','https://image.tmdb.org/t/p/w500/tiF5I6wF6tEUy39gmNtw3G1GYyz.jpg',2024,'Action,Comedy,Crunchyroll,Hindi Dub,Shounen,Supernatural,Tamil,Telugu','DandadanIn a bet to prove whether ghosts or aliens exist, two high schoolers face terrifying paranormal threats, gain superpowers and maybe even fall in love?!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('danny-phantom','Danny Phantom','https://image.tmdb.org/t/p/w500/u5gI5aZgpqT42sIVsHzmhS283pP.jpg',2004,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','Danny Fenton was once your typical kid until he accidentally blew up his parents’ laboratory and became ghost-hunting superhero Danny Phantom. Now half-ghost, Danny’s picked up paranormal powers, but only his sister, Jazz, and best friends, Samantha and Tucker, know his secret. Danny’s busy fighting ghosts, saving Casper High and hiding his new identity all while trying to graduate.',27);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('days-with-my-stepsister','Days with My Stepsister','https://image.tmdb.org/t/p/w500/81HdXCynJtZhgfHUz7XHmsf5j7Q.jpg',2024,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Slice of Life','When his father remarries, Yuta Asamura winds up sharing a roof with his new stepsister, Saki Ayase, the hottest girl in his grade. Carrying the scars of their parents’ troubled divorces, they vow to maintain a respectful distance. But what starts as cautious camaraderie blossoms into something deeper from shared experiences. Is it admiration, familial love, or something more?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dc-super-hero-girls','DC Super Hero Girls','https://image.tmdb.org/t/p/w500/xpOW4hlnkqlIXrjkUHUWPF3Hws2.jpg',2019,'Action,Cartoon,Family,Fantasy,Hindi Dub,Kids,Sci-Fi','The world may know them as Wonder Woman, Supergirl and Batgirl, but not-so-typical teenagers Diana, Kara and Barbara, alongside their Super Hero friends have much more to deal with than just protecting Metropolis from some of the most sinister school-aged Super-Villains. After all, being teens is tough enough, what with school, friends, family and the chaos that comes with managing a social life. But add super powers and a secret identity to the mix, and things can get a lot more complicated.Please Note That Episode Numbers and Name Will not Match Because Episode List is Imported From TheMovieDatabse But Episodes are Ripped From Netflix (Different Order)',49);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dekin-no-mogura-the-earthbound-mole','Dekin no Mogura: The Earthbound Mole','https://image.tmdb.org/t/p/w500/xnEForFiNATvYS4MUwYyFuPyiok.jpg',2025,'Anime,Comedy,Drama,Hindi Dub,Mystery,Seinen,Supernatural','A shady self-proclaimed hermit named Momoyuki Mogura, AKA: Mogura, is banned from the afterlife due to an incident. Now he collects spirit possessed will-o’-wisps in his lantern, hoping to make a comeback.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('delicious-in-dungeon','Delicious in Dungeon','https://image.tmdb.org/t/p/w500/9t3DYdGxK3i4WRzKvIZwJd4kBnr.jpg',2024,'Anime,Comedy,Fantasy,Gourmet,Hindi Dub,Seinen','Dungeons, dragons… and delicious monster stew!? Adventurers foray into a cursed buried kingdom to save their friend, cooking up a storm along the way.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('demon-lord-retry','Demon Lord, Retry!','https://image.tmdb.org/t/p/w500/lsefcgTQPO5f0XrTXaYuVHcGS6U.jpg',2019,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai','Akira Oono awakens in the body of his online character: Demon Lord Hakuto Kunai. With powerful game mechanics and abilities on his side, this gamer turned badass plots his course through a new world filled with saints, demons, and charming companions!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('demon-slayer-kimetsu-no-yaiba','Demon Slayer: Kimetsu no Yaiba','https://image.tmdb.org/t/p/w500/ctR9Kv2MNhuIjgb96wARbT1BNts.jpg',2019,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,Historical,Shounen,Tamil,Telugu','It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family.',64);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('detective-conan','Detective Conan','https://image.tmdb.org/t/p/w500/hSKD1ysKYJ36t6iUSf8dN3C76Se.jpg',1996,'Anime,Comedy,Crime,Detective,Family,Hindi Dub,Malayalam,Mystery,Shounen,Tamil,Telugu','Case ClosedThe son of a world famous mystery writer, Jimmy Kudo, has achieved his own notoriety by assisting the local police as a student detective. He has always been able to solve the most difficult of criminal cases using his wits and power of reason.',278);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('disenchantment','Disenchantment','https://image.tmdb.org/t/p/w500/1WynayCqKRzrl4cFZR8NOfiDwd6.jpg',2018,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','Set in a ruined medieval city called Dreamland, Disenchantment follows the grubby adventures of a hard-drinking princess, her feisty elf companion and her personal demon.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('doc-mcstuffins','Doc McStuffins','https://image.tmdb.org/t/p/w500/eeGWJaFkxX0vvOFFpNFXrh9QVxl.jpg',2012,'Animation,Cartoon,Family,Hindi Dub,Kids,Tamil,Telugu','A young African-American girl aspires to be a doctor like her mom.',63);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dolls-frontline','Girls’ Frontline','https://image.tmdb.org/t/p/w500/ip5Zx3RWxzNuRUDYpPwPrjsPOo.jpg',2022,'Action,Anime,Crunchyroll,Drama,Hindi Dub,Military,Sci-Fi,Tamil,Telugu','Dolls’ FrontlineIn the fallout of nuclear war, the last of humanity survives with the help of life-like androids known as Dolls. Built to serve, some fight in wars as Tactical Dolls or T-Dolls. Now, an elite team comprised of T-Dolls are sent to face a new rogue threat, Sangvis Ferri. Leading them into battle is their new human commander, M4A1.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('doraemon-all','Doraemon','https://image.tmdb.org/t/p/w500/aL9BRFZuLzbuvhtrlTYs1ix1apu.jpg',0,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Robotic cat Doraemon is sent back in time from the 22nd century to protect 10-year-old Noby, a lazy and uncoordinated boy who is destined to have a tragic future. Doraemon can create secret gadgets from a pocket on his stomach, but they usually cause more bad than good because of Noby’s propensity to misuse them.',883);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('doraemon-classic-1979','Doraemon Classic (1979)','https://cdn.myanimelist.net/images/anime/1106/109532l.jpg',1979,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Sci-Fi','Doraemon is an anime TV series created by Fujiko F. Fujio and based on the manga series of the same name. This anime is the much more successful successor of the 1973 anime.Please Note That Episode Numbers and Name Will not Match.',55);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dorohedoro','Dorohedoro','https://image.tmdb.org/t/p/original/zSMmRTopPIRr6913KX8pyiV6zsK.jpg',2020,'Action,Anime,Anime Times,Comedy,Fantasy,Gore,Hindi Dub,Horror,Seinen','Amnesiac Caiman seeks to undo his lizard head curse by killing the sorcerer responsible, with his friend Nikaido’s help. In the Hole, that’s a threat.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('doug-unplugs','Doug Unplugs','https://image.tmdb.org/t/p/w500/iIDiGOoeupsWvPDbi6qfikgjngm.jpg',2020,'Animation,Hindi Dub,Kids','Doug is a young robot who senses there’s more to life than just the facts. While other robots plug in for their daily download, Doug unplugs and journeys into the human world with his best friend Emma to experience its wonders firsthand.',7);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dr-stone','Dr. STONE','https://image.tmdb.org/t/p/w500/2C7lHKeWY7k1qEtTKecUHuqKv1X.jpg',2019,'Adventure,Anime,Comedy,Crunchyroll,Hindi Dub,Sci-Fi,Shounen,Survival,Tamil,Telugu','Doctor StoneOne fateful day, all of humanity was petrified by a blinding flash of light. After several millennia, high schooler Taiju awakens and finds himself lost in a world of statues. However, he’s not alone! His science-loving friend Senku’s been up and running for a few months and he’s got a grand plan in mind, to kickstart civilization with the power of science!',95);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dragon-ball','Dragon Ball','https://image.tmdb.org/t/p/w500/onCLyCOgszTIyyVs2XKYSkKPOPG.jpg',1986,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Kannada,Malayalam,Martial Arts,Shounen,Super Power,Tamil,Telugu','Long ago in the mountains, a fighting master known as Son Gohan discovered a strange boy whom he named Son Goku. Gohan raised him and trained Goku in martial arts until he died. The young and very strong boy was on his own, but easily managed. Then one day, Goku met a teenage girl named Bulma, whose search for the mystical Dragon Balls brought her to Goku’s home. Together, they set off to find all seven and to grant her wish.',57);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('drake-josh','Drake & Josh','https://image.tmdb.org/t/p/w500/udCvGctktHvvf8w51XyTPfcmzDa.jpg',2004,'Comedy,Hindi Dub','15-year-old Drake and Josh are schoolmates, but not close friends. Drake views Josh as weird and a bit of a goof. So, imagine Drake’s shock when he finds out that this “goof” is about to become his new step-brother and roommate when his mother marries Josh’s father. A spin off of The Amanda Show.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('duck-dodgers','Duck Dodgers','https://image.tmdb.org/t/p/w500/l9gmVRHxMy4F49DnpqWDD8ODAXf.jpg',2003,'Animation,Cartoon,Comedy,Hindi Dub,Kids,Sci-Fi & Fantasy','Duck Dodgers battles evil in the 24th century.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ducktales-old','DuckTales Old','https://image.tmdb.org/t/p/w500/muplnM90daPCQ5Bn1olcwN1EO22.jpg',1987,'Cartoon,Family,Hindi Dub,Kids,Mystery','Duck TalesScrooge McDuck finds his hands full at home when nephews Huey, Dewey and Louie move to Duckburg. Joined by their loyal pals Launchpad McQuack, Gyro Gearloose and Mrs. Beakley, the DuckTales gang never fails to deliver a wealth of adventure. Get ready for a fortune of fun with DuckTales!',97);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ed-edd-n-eddy','Ed, Edd n Eddy','https://image.tmdb.org/t/p/w500/8BguP5zLyf3AzlTgRRhpXdz9bnS.jpg',1999,'Animation,Cartoon,Comedy,Family,Hindi Dub','Three adolescent boys, Ed, Edd “Double D”, and Eddy, collectively known as “the Eds”, constantly invent schemes to make money from their peers to purchase their favorite confectionery, jawbreakers. Their plans usually fail though, leaving them in various predicaments.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('edgar-rice-burroughs-tarzan-and-jane','Edgar Rice Burroughs’ Tarzan and Jane','https://image.tmdb.org/t/p/w500/60IcVtP9l8tDjt9toY6Sfo5jZ25.jpg',2017,'Action & Adventure,Animation,Cartoon,Hindi Dub,Tamil,Telugu','Saved from a plane crash and given supernatural powers, teen Tarzan joins forces with brave city girl Jane to protect his jungle home from threats.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ejen-ali','Ejen Ali','https://image.tmdb.org/t/p/w500/pC7MTsEjJVXlCEaTRFWhVUS113i.jpg',2016,'Action,Adventure,Comedy,Hindi Dub,Kids,Tamil,Telugu,Thriller','The story of an elementary school student who accidentally involved himself in the world of intelligence. It all started when the dose of an agent of evil who are trying to steal a high-tech tool that can change the world, namely I.R.I.S (Infinity Retinal Intelligence System) were stolen from the training center M.A.T.A (Meta Advance Tactical Agency).',23);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('eren-the-southpaw','Eren the Southpaw','https://image.tmdb.org/t/p/original/AkhxnKGDcNKikr1xDP4mi1wpfEr.jpg',2026,'Adult Cast,Anime,Crunchyroll,Drama,Hindi Dub,Shounen,Tamil,Telugu,Visual Arts','As high school reaches its midpoint, Koichi Asakura—who dreams of studying design at art school—has his plans shaken by explosive graffiti on a museum wall. The artist is Eren Yamagishi, a left-handed girl who buried her talent after a past incident. Drawn together by art, Koichi pursues design as Eren returns to painting, but fear, ambition, and old scars threaten their paths.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('farzar','Farzar','https://image.tmdb.org/t/p/w500/h89bKlWrHcFSBGXsNNi1ArnUPHf.jpg',2022,'Animation,Comedy,Sci-Fi & Fantasy','Follow the adventures of Prince Fichael and his crew as they venture out of their domed human city to fight the evil aliens that want to kill and/or eat them.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fraggle-rock-back-to-the-rock','Fraggle Rock: Back to the Rock','https://image.tmdb.org/t/p/w500/uMtPzxmZAumXC3e9vYpNLKMK6Je.jpg',2022,'Animation,Cartoon,Comedy,Hindi Dub,Kids','Join Gobo, Red, Wembley, Mokey, Boober, and new Fraggle friends on hilarious, epic adventures about the magic that happens when we celebrate and care for our interconnected world.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('frieren-beyond-journeys-end-hindi','Frieren: Beyond Journey’s End','https://image.tmdb.org/t/p/w500/dqZENchTd7lp5zht7BdlqM7RBhD.jpg',2023,'Adventure,Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Shounen,Tamil,Telugu','After the party of heroes defeated the Demon King, they restored peace to the land and returned to lives of solitude. Generations pass, and the elven mage Frieren comes face to face with humanity’s mortality. She takes on a new apprentice and promises to fulfill old friends’ dying wishes. Can an elven mind make peace with the nature of life and death? Frieren embarks on her quest to find out.',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fullmetal-alchemist-brotherhood-cr-dub','Fullmetal Alchemist: Brotherhood (CR Dub)','https://image.tmdb.org/t/p/w440_and_h660_face/Ak3WnvXyhIGezca0BmMUuPppLg8.jpg',2009,'Action & Adventure,Animation,Anime,Drama,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Disregard for alchemy’s laws ripped half of Edward Elric’s limbs from his body and left his brother Alphonse’s soul clinging to a suit of armor. To restore what was lost, the brothers seek the Philosopher’s Stone. Enemies and allies – the corrupt military, the Homunculi, and foreign alchemists – will alter the Elric brothers course, but their purpose will remain unchanged and their bond unbreakable.',19);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fullmetal-alchemist-brotherhood','Fullmetal Alchemist: Brotherhood','https://image.tmdb.org/t/p/w440_and_h660_face/5ZFUEOULaVml7pQuXxhpR2SmVUw.jpg',2009,'Action,Adventure,Anime,Anime Times,Drama,Fantasy,Hindi Dub,Military,Shounen','Disregard for alchemy’s laws ripped half of Edward Elric’s limbs from his body and left his brother Alphonse’s soul clinging to a suit of armor. To restore what was lost, the brothers seek the Philosopher’s Stone. Enemies and allies – the corrupt military, the Homunculi, and foreign alchemists – will alter the Elric brothers course, but their purpose will remain unchanged and their bond unbreakable.',64);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fullmetal-alchemist','Fullmetal Alchemist','https://image.tmdb.org/t/p/w500/kKOQbCKbGB75h1d3Jlx9Gy4ZTfv.jpg',2003,'Action,Adventure,Anime,Anime Times,Drama,Fantasy,Hindi Dub,Military,Shounen','Edward Elric, a young, brilliant alchemist, has lost much in his twelve-year life: when he and his brother Alphonse try to resurrect their dead mother through the forbidden act of human transmutation, Edward loses his brother as well as two of his limbs. With his supreme alchemy skills, Edward binds Alphonse’s soul to a large suit of armor.A year later, Edward, now promoted to the fullmetal alchemist of the state, embarks on a journey with his younger brother to obtain the Philosopher’s Stone. The fabled mythical object is rumored to be capable of amplifying an alchemist’s abilities by leaps and bounds, thus allowing them to override the fundamental law of alchemy: to gain something, an alchemist must sacrifice something of equal value. Edward hopes to draw into the military’s resources to',51);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('future-worm','Future-Worm!','https://image.tmdb.org/t/p/w500/s57Rjemt8tsjGhZ8taZpgcTMaVR.jpg',2016,'Animation,Cartoon,Hindi Dub','The show follows Danny Douglas and his friend Future-Worm as they go on adventures and travel through time.',5);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('generator-rex','Generator Rex','https://image.tmdb.org/t/p/w500/fL7S22SWWOjJTgHEkk68VZ4Z8RO.jpg',2010,'Action & Adventure,Animation,Cartoon,Family,Hindi Dub,Kids,Mystery','Generator Rex, an average teenager with the ability to turn his body into amazing machines, helps the secret organization Providence save the world from the nanite threat and dangerous EVO monsters.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ghost-in-the-shell-stand-alone-complex','Ghost in the Shell: Stand Alone Complex','https://image.tmdb.org/t/p/w500/x6ZDEMRqOnCVd4jzvX8MukUoz1S.jpg',2002,'Action,Adult Cast,Anime,Anime Times,Crime,Detective,Hindi Dub,Mecha,Military,Mystery,Sci-Fi,Tamil,Telugu','In the future when technological enhancements and robotics are a way of life, Major Motoko Kusanagi and Section 9 take care of the jobs that are too difficult for the police. Section 9 employs hackers, sharpshooters, detectives and cyborgs all in an effort to thwart cyber criminals and their plans to attack the innocent.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gintama','Gintama','https://image.tmdb.org/t/p/w500/f7vK8pzZIqhyA8sYmBpWmp9Ae7.jpg',2006,'Action & Adventure,Animation,Comedy,Hindi Dub,Sci-Fi & Fantasy','In a world where aliens have invaded Edo Period Japan, skyscrapers, trains and motor bikes have replaced the simple life of Earth inhabitants. One man however, still carries the soul of a samurai, Gintoki Sakata, otherwise known as Yorozuya Gin-san. As reckless as he is, Gintoki carries his own resolve and is ready to take on any challenge with his fellow companions.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('goblin-slayer','Goblin Slayer','https://image.tmdb.org/t/p/w500/qe5Igtb8pVHLFvPxTq0ZYZ3cHq5.jpg',2018,'Action,Adventure,Anime,Fantasy,Gore,Hindi Dub','“I’m not saving the world. I just kill goblins.”Rumor has it that, in a certain guild in the middle of nowhere, there is an extraordinary man who has climbed all the way to the Silver rank just by killing goblins. At the same guild, a priestess who’s just become a new adventurer has formed her first party… and the man who ends up rescuing that party when they get into trouble is none other than the Goblin Slayer.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gods-games-we-play-hindi','Gods’ Games We Play','https://image.tmdb.org/t/p/w500/gkpFc791zeyQEO7Ds7mlnaC1cmj.jpg',2024,'Anime,Crunchyroll,Drama,Ecchi,Fantasy,Hindi Dub,Tamil,Telugu','In a world of idle gods, humans are forced into brain challenges with them. With three defeats, gods lose their right to challenge, while 10 victories spell human triumph. Fay, determined to achieve the impossible, enters the ultimate test of wits against the gods. Will he defy divinity, or is he just another loss in the making?',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gortimer-gibbons-life-on-normal-street','Gortimer Gibbon’s Life on Normal Street','https://image.tmdb.org/t/p/w500/7rg22mGHtJkirhVEOTbcxTdWiqB.jpg',2014,'Family,Hindi Dub,Kids','Life is anything but normal for Gortimer and his two best friends, Ranger and Mel, as they navigate Normal Street – an ordinary suburb that has a hint of something magical just beneath the surface.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('grand-blue-dreaming','Grand Blue Dreaming','https://image.tmdb.org/t/p/original/ii1yrluzWisy1rygSKz8lJkAkil.jpg',2018,'Adult Cast,Anime,Anime Times,Comedy,Gag Humor,Hindi Dub,Seinen','A college student joins the local diving club after meeting some rowdy upperclassmen. New adventures in booze and the ocean await.',29);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('haikyuu-hotstar-dub','Haikyuu!! (Hotstar Dub)','https://image.tmdb.org/t/p/w500/8WEr48swcqe89Zsy5sdrGCASlIg.jpg',2014,'Animation,Comedy,Drama,Hindi Dub,Tamil,Telugu','Haikyu!!Inspired by a small-statured pro volleyball player, Shouyou Hinata creates a volleyball team in his last year of middle school. Unfortunately the team is matched up against the “King of the Court” Tobio Kageyama’s team in their first tournament and inevitably lose. After the crushing defeat, Hinata vows to surpass Kageyama. After entering high school, Hinata joins the volleyball team only to find that Tobio has also joined.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('handy-manny','Handy Manny','https://image.tmdb.org/t/p/w500/o5hZxR34tSgigW3xV6WG4H9FOcS.jpg',2006,'Animation,Cartoon,Comedy,Hindi Dub','Handy Manny is a Disney animated children’s television program that premiered on September 16, 2006.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hoops','Hoops','https://image.tmdb.org/t/p/w500/3umUQ5DcZe7mSZGImCAStl2FRbm.jpg',2020,'Animation,Cartoon,Comedy,Hindi Dub','A foul-mouthed high school basketball coach is sure he’ll hit the big leagues if he can only turn his terrible team around. Good luck with that.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hannah-montana','Hannah Montana','https://image.tmdb.org/t/p/w500/sRqLl0SHA4diTL8zvUTgBw6DQeM.jpg',2006,'Comedy,Kids','At home and school, she’s Miley Stewart, a typical teenager, but when the lights go down and the curtain goes up, she emerges as the glamorous and talented Hannah Montana. Having the “Best of Both Worlds” is a complicated proposition, and keeping her identity under wraps leads Miley and her friends into some hilarious capers as she tries to balance her normal life with her rock star persona.',86);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('heaven-officials-blessing','Heaven Official’s Blessing','https://image.tmdb.org/t/p/original/4psWk1qJZKXlH78DjZUnvXCwSAM.jpg',2020,'Amazon Prime,Animation,Anime,Hindi Dub,Sci-Fi & Fantasy','Banished to the mortal realm to exorcise ghosts, an eight-century-old deity reckons with a demon and slowly uncovers dark secrets behind the many heavenly gods.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('heroines-run-the-show','Heroines Run the Show','https://image.tmdb.org/t/p/w500/nFjr0X8DkObtdDxzI4knKDK1OuR.jpg',2022,'Anime,Comedy,Drama,Hindi Dub,Idols,School,Tamil,Telugu','Heroines Run the Show: The Unpopular Girl and the Secret TaskWhat would you do to pursue your passion? For Hiyori Suzumi, it’s leaving her simple rural hometown for the bustling city of Tokyo to join Sakuragaoka High School’s track team. Between being a manager-in-training for two cutthroat schoolboy idols, track, and friends, Hiyori shows no signs of slowing down.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hokkaido-gals-are-super-adorable','Hokkaido Gals Are Super Adorable!','https://image.tmdb.org/t/p/w500/nCJKNJ3rtgLDAhAN5S881z8PHKU.jpg',2024,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,School,Shounen,Tamil,Telugu','Hokaido Gals Are Super Adorable!Snowflakes aren’t the only things dropping in Hokkaido—so are jaws, thanks to the super adorable gals who are turning the icy north into a hotbed of fashion and fun. Brace yourself for a winter storm of laughs, love, and killer outfits as these gals prove that being cute is an all-season affair. Here, frostbite meets fashionista!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hot-wheels-battle-force-5','Hot Wheels Battle Force 5','https://image.tmdb.org/t/p/w500/eVAPZukaKJfkIfnsBxoAbOm6Zsc.jpg',2009,'Action,Cartoon,Hindi Dub,Sci-Fi,Sports','In this series based on the legendary toy brand, an elite team of drivers in five ultracool, ultrafast vehicles are given a mission to save Earth from two evil species of alien invaders, the Sark and the Vandals. Led by Vert Wheeler, Battle Force 5 take on the predators in unique BattleZones, engaging their weaponized supervehicles to secure the key in each zone that, in the hands of the Sark and Vandals, unlocks a secure pathway to Earth.',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('human-resources','Human Resources','https://image.tmdb.org/t/p/w500/pOJC46PNC4ivjkkDnUNx209YIw4.jpg',2022,'Animation,Cartoon,Comedy,Hindi Dub','Lovebugs, Hormone Monsters and a parade of other creatures juggle romance, workplace drama and their human clients’ needs in this “Big Mouth” spinoff.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hunter-x-hunter-hindi-dub','Hunter x Hunter','https://image.tmdb.org/t/p/w500/ucpgmUR1h5Te1BYegKItoPjOeF7.jpg',2011,'Action,Adventure,Anime,Fantasy,Hindi Dub,Shounen','Twelve-year-old Gon Freecss one day discovers that the father he had always been told was dead was alive. His Father, Ging, is a Hunter — a member of society’s elite with a license to go anywhere or do almost anything. Gon, determined to follow in his father’s footsteps, decides to take the Hunter Examination and eventually find his father to prove himself as a Hunter in his own right. But on the way, he learns that there is more to becoming a Hunter than previously thought, and the challenges that he must face are considered the toughest in the world.',148);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('i-was-reincarnated-as-the-7th-prince-so-i-can-take-my-time-perfecting-my-magical-ability','I Was Reincarnated as the 7th Prince','https://image.tmdb.org/t/p/w500/1P1EB1ntw8dKQEXYmMbUmWjYqaJ.jpg',2024,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Reincarnation','I Was Reincarnated as the 7th Prince so I Can Take My Time Perfecting My Magical AbilityPrince Lloyd wasn’t always a prince…in fact, his previous life is one he remembers perfectly: he was a sorcerer, of sorts. So when he was forced to reincarnate, he decided to continue his studies, prince of the realm or no! But his new life has its own sets of challenges…including being a 10-year-old! What’s the 7th prince/sorcerer to do?!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('im-getting-married-to-a-girl-i-hate-in-my-class','I’m Getting Married to a Girl I Hate in My Class','https://image.tmdb.org/t/p/w500/k0Yb8KjspVjNlmvHNgqRRbhZ6LA.jpg',2025,'Animation,Anime,Comedy,Crunchyroll,Hindi Dub,Tamil,Telugu','High school student Saito Hojo is set to inherit his grandfather’s major corporation. First, he must marry Akane Sakuramori, the girl he despises the most, and who hates him just as much. The two are determined to keep their unexpected marriage a secret from their classmates. But as they begin their newlywed life, the distance between them starts to close.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('im-in-love-with-the-villainess','I’m in Love with the Villainess!','https://image.tmdb.org/t/p/w500/29jtBbv4eSk0QHdVMLwl8P4p6NX.jpg',2023,'Anime,Comedy,Crunchyroll,Fantasy,Girls Love,Hindi Dub,Isekai,School,Tamil,Telugu','I am in Love with the VillainessOrdinary office worker Ohashi Rei wakes up in the body of the protagonist of her favorite otome game, Revolution. To her delight, the first person to greet her is also her favorite character, Claire Francois—the main antagonist of the story! Now, Rei is determined to romance Claire instead of the game’s male leads. But how will her villainous ladylove react to this new courtship?!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('infinity-nado','Infinity Nado','https://image.tmdb.org/t/p/w500/3XzeK6Y3ESvn2JO5zLbWnUcRSMj.jpg',2012,'Action,Adventure,Anime,Hindi Dub,Kids','Dawn and Athas find a mysterious sleeping boy, Pandora, who suffers from amnesia after he comes around. When Pandora just arrives at Freewheel Town, he becomes the chasing target of an organization called Ancient Hunter Group, which demands of him to carry out the “Great Mission”. Under the attack of Jin and his friends, Ancient Hunter Group is temporarily repelled.With the assistance of Jin and his friends, Pandora gradually gets used to life in this world and his skill on top is much improved.Can Pandora regain his memories? What is his “Great Mission”? The story will tell you……',46);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('inspector-gadget','Inspector Gadget','https://image.tmdb.org/t/p/w500/ayYkEcvuArO5mpI4Dxnqq3Z5WEQ.jpg',1983,'Animation,Comedy,Hindi Dub,Kids','Inspector Gadget is a clumsy, dim-witted human cyborg detective with various bionic gadgets built into his body. Gadget stumbles around working the cases while his niece and dog do most of the investigating. Gadget’s arch-nemesis is Dr. Claw, the leader of an evil organisation, known as “M.A.D.”',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jing-ju-cats','Jing-Ju Cats','https://image.tmdb.org/t/p/w500/3yDVGxupDMwe4A8DIKY0yro566L.jpg',2015,'Action & Adventure,Animation,Comedy','Formally a paradise for all cats, the Cat Land Purpetua has been invaded and occupied by the dark lord AN, aided by his enslaved mutant monsters. The evil chaos reigns throughout the Purpetua and leads everything down to a wrong path. Only Jing-Ju Cats can overthrow An and resist the forces of evil chaos. A cat named LIL’PAI from the Clangour Town was once rescued by a Jing- Ju Cat at a very young age. He swore to be a great Jing-Ju Cat when he grows up. Once in a fight with monsters, he met the descendants of Jing- Ju Cats WU, ZAD and JEAN, and started to learn Kung Fu from their master Tang Ming and Granny GIN. The young LIL’PAI had neither blue blood nor outstanding talents. However, because of his amazing endeavor and the will of never giving up, he had succeeded through many trials an',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('johnny-bravo','Johnny Bravo','https://image.tmdb.org/t/p/w500/obbdeoOk8XSXzJrWGiBbaeMMSMl.jpg',1997,'Animation,Comedy,Family,Hindi Dub','Johnny Bravo tells the story of a biceps-bulging, karate-chopping free spirit who believes he is a gift from God to the women of the earth. Unfortunately for Johnny, everyone else sees him as a narcissistic Mama’s boy with big muscles and even bigger hair. In short, he is the quintessential guy who ‘just doesn’t get it.’ No matter what he does, or where he finds himself, he always winds up being his own worst enemy.',132);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('johnny-test-new','Johnny Test (New)','https://image.tmdb.org/t/p/w500/drA7JI2BqdI3sdvPIUyp2gDMkBN.jpg',2021,'Animation,Comedy','How much trouble could one imaginative boy, his faithful dog and two science-loving sisters possibly get into? Hmm, that sounds like a challenge!',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jonas-l-a','JONAS L.A.','https://image.tmdb.org/t/p/w500/qwQMWsaytTISHhZs4jMNqQsgzNb.jpg',2009,'Comedy,Family,Hindi Dub,Kids','The show follows the Jonas Brothers through fun and unusual situations as they try to live ordinary lives.',34);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jungle-junction','Jungle Junction','https://image.tmdb.org/t/p/w500/nbvsTq54Rno0HMjeWVQwS8C5C1.jpg',2009,'Animation,Cartoon,Hindi Dub,Tamil,Telugu','Jungle Junction is a current CGI animated children’s television series created by Trevor Ricketts. It airs on Disney Junior in the United States and in the Netherlands, as well as Playhouse Disney in the United Kingdom and Ireland, Portugal, Spain, Turkey and on Playhouse Disney in Asia. It is produced in the UK by animation company Spider Eye Productions. In the United States, the programme was originally part of the Playhouse Disney daily block intended for preschoolers. On February 14, 2011, it was moved to the Disney Junior block, serving as Playhouse Disney’s replacement.A second series of 26 episodes has been ordered by Disney.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('justice-league-unlimited','Justice League Unlimited','https://image.tmdb.org/t/p/w500/8PY0OZ1xUbguPipb0a1uL6mg5Ka.jpg',2004,'Action,Adventure,Cartoon,Hindi Dub,Sci-Fi','Justice League Unlimited is an American animated television series that was produced by Warner Bros. Animation and aired on Cartoon Network. Featuring a wide array of superheroes from the DC Comics universe, and specifically based on the Justice League superhero team, it is a direct sequel to the previous Justice League animated series.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kaiju-no-8-hin','Kaiju No. 8','https://image.tmdb.org/t/p/w500/q2ihpco7zy6WEBMicHUgr1SqVvP.jpg',2024,'Action,Anime,Crunchyroll,Hindi Dub,Military,Sci-Fi,Shounen,Tamil,Telugu','In a world plagued by creatures known as Kaiju, Kafka Hibino aspired to enlist in The Defense Force. He makes a promise to enlist with his childhood friend, Mina Ashiro. Soon, life takes them in separate ways. While employed cleaning up after Kaiju battles, Kafka meets Reno Ichikawa. Reno’s determination to join The Defense Force reawakens Kafka’s promise to join Mina and protect humanity.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kim-possible','Kim Possible','https://image.tmdb.org/t/p/w500/qsDNX8DPwWydDn9oUIhe1WcTuUH.jpg',2002,'Action,Adventure,Cartoon,Comedy,Kids,Tamil,Telugu','If there’s danger or trouble, Kim Possible is there on the double to save the world from villains… and still make it home in time for cheerleading practice! Luckily, Kim has her sidekick Ron Stoppable and his pet naked mole-rat Rufus by her side.',51);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kochikame-sony-yay-dub','KochiKame (Sony Yay Dub)','https://image.tmdb.org/t/p/w500/htNRLdAlMRTH1bqgIqyZWiggTiW.jpg',1996,'Action & Adventure,Animation,Comedy,Crime,Family','Ryoutsu, being an underpayed policeman, is always coming up with ways to make some quick money. But in the end, his plans which are ridiculous from the beginning always go wrong and land him in big trouble.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kochikame','KochiKame (Hungama Dub)','https://image.tmdb.org/t/p/w500/ujltFuzCZ9FLe07kTRLZ2gpIJVY.jpg',1996,'Action,Adventure,Anime,Comedy,Crime,Family,Hindi Dub','Ryoutsu, being an underpayed policeman, is always coming up with ways to make some quick money. But in the end, his plans which are ridiculous from the beginning always go wrong and land him in big trouble.',75);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kung-fu-panda-the-dragon-knight','Kung Fu Panda: The Dragon Knight','https://image.tmdb.org/t/p/w500/7C9TKvU5dNyhvoG9kQvRFsg6vlA.jpg',2022,'Action,Adventure,Cartoon,Comedy,Hindi Dub','Follow the adventures of Po, who partners up with a no-nonsense English knight named Wandering Blade to find a collection of four powerful weapons before a mysterious pair of weasels do, and save the world from destruction.',42);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kung-fu-panda-the-paws-of-destiny','Kung Fu Panda: The Paws of Destiny','https://image.tmdb.org/t/p/w500/x4yvmIVuXxYKfTlgRtSJnGC1Izs.jpg',2018,'Action,Adventure,Cartoon,Comedy,Drama,Hindi Dub','As the Dragon Master, Po has endured his fair share of epic challenges but nothing could prepare him for his greatest one yet-as a Kung Fu teacher to a group of rambunctious kids from Panda Village who have been imbued with a mysterious and powerful chi energy. Together they embark on amazing adventures, battle ferocious villains, and become legends!',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kurokos-basketball','Kuroko’s Basketball','https://image.tmdb.org/t/p/original/qi8dlAgQEeahpEn1AOb5BJEOcVB.jpg',2012,'Amazon Prime,Ani-One India,Animation,Anime,Comedy,Drama,Hindi Dub','In the story, Kagami Taiga has just enrolled into Seirin High School when he meets Kuroko Tetsuya of the school’s basketball team. Kuroko happens to be the shadowy sixth member of the legendary Generation of Miracles basketball team. Together, Kagami and Kuroko aim to take their team to the inter-high school championship – against Kuroko’s former teammates.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kurozuka','Kurozuka','https://image.tmdb.org/t/p/w500/hez6h5LZxedDfzHHPu3iqj2Gm82.jpg',2008,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','In feudal Japan, Kurou and his servant Benkei are fleeing from Kurou’s elder brother, who has recently ascended to the throne. In a forest, they come across a house and a strange woman by the name of Kuromitsu, who agrees to harbor them under one condition: that they do not peer into the inner chambers. Soon, they are attacked by the Red Army; they are searching for Kuromitsu, whose blood holds immortality. Fatally wounded, Kurou drinks some of Kuromitsu’s blood and gains immortality along with strange abilities; but shortly after, Kurou is seemingly decapitated and wakes up centuries later in a ruined city. In this twisted future the Red Army is omnipresent and still searching for Kuromitsu’s blood, while a rebel army seeks to keep them from acquiring it. With threats at every turn and fu',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lego-frozen-northern-lights','LEGO Frozen Northern Lights','https://image.tmdb.org/t/p/w500/fBuc52aHBy9mAb8AwIJqAXy4o2y.jpg',2016,'Cartoon,Hindi Dub','Anna, Elsa, Kristoff, Olaf and Sven will be embarking on an epic journey to “restore the glimmer of the Northern Lights”.',4);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lego-jurassic-world-legend-of-isla-nublar','Lego Jurassic World : Legend of Isla Nublar','https://image.tmdb.org/t/p/w500/wMoL1JuARTsAPxf8b85rQfT6Opp.jpg',2019,'Action,Cartoon,Family,Hindi Dub,Kids,Sci-Fi','Set in 2012, three years before the Jurassic World movie, Owen Grady and Claire Dearing team up on Isla Nublar to deal with everything the Jurassic World park throws their way, including a mysterious saboteur who wants to destroy the park forever!',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lego-marvel-avengers-climate-conundrum','LEGO Marvel Avengers: Climate Conundrum','https://image.tmdb.org/t/p/w500/yeCEBB9eLeJ4nmj00ePD7eqeWYx.jpg',2020,'Action,Cartoon,Family,Hindi Dub,Kids','The Environmental Clean-up Conference is off to anything but a smooth start when Tony Stark realizes his fellow competitor is his rival Justin Hammer!',4);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lego-star-wars-the-freemaker-adventures','LEGO Star Wars: The Freemaker Adventures','https://image.tmdb.org/t/p/w500/89lb0Dg0OjnGNZ92shxduhz3TVN.jpg',2016,'Animation,Cartoon,Hindi Dub','Set between The Empire Strikes Back and Return of the Jedi, The Freemaker Adventures centers on a family of three young siblings—young boy Rowan, his sister Kordi, and their brother Zander—known as the Freemakers, who salvage parts from destroyed or damaged ships which they use to build new ones, which they sell in order to make their living. They are accompanied by their salvaged battle droid Roger.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('let-this-grieving-soul-retire-hindi','Let This Grieving Soul Retire','https://image.tmdb.org/t/p/w500/5BMsYRsMb5lvY97bMfDckCoksyR.jpg',2024,'Action,Adventure,Anime,Anime Times,Comedy,Fantasy,Hindi Dub,Kannada,Tamil,Telugu','Six childhood friends make a vow one day to become treasure hunters, and eventually grow to be the strongest heroes in the world. During his first quest, Krai Andrey realizes he isn’t cut out for the job. Even so, his friends make him their leader. Underpowered in the face of great expectations, Krai embarks on a reluctant hero’s tale of glory, headaches, and wanting to retire early.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('liar-game','LIAR GAME','https://image.tmdb.org/t/p/original/9npgB8fyf7qN8F4ngkuY2eHczxD.jpg',2026,'Anime,Crunchyroll,Drama,High Stakes Game,Hindi Dub,Psychological,Seinen,Strategy Game,Suspense,Tamil,Telugu','When Nao Kanzaki receives a strange letter and a suitcase containing 100 million yen, she learns that she has been selected to participate in the LIAR GAME. In this high-stakes psychological battle, lies, deception, and betrayal reign supreme. Naïve and honest, Nao turns to Shinichi Akiyama, a brilliant former con artist, to survive the twisted game. In a game built on lies, can honesty prevail?',23);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('little-krishna','Little Krishna','https://image.tmdb.org/t/p/w500/pCrB6WALVxDbpZ7MoPGuq9UNdk5.jpg',0,'Adventure,Cartoon,Drama,Family,Hindi Dub,History,Tamil','Little Krishna is a 3D computer-animated series which is a co-creation between BIG Animation and India Heritage Foundation. The series started showing on Indian television on Nickelodeon from 11 May 2009.It depicts the childhood pastimes of Lord Sri Krishna, The Supreme Personality of Godhead. The stories revolve around Little Krishna, the land of Vrindavan and the life of villagers there. Little Krishna is a lovable and mischievous character who enjoys helping his friends and villagers.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lizzie-mcguire','Lizzie McGuire','https://image.tmdb.org/t/p/w500/vaaF94ogtMCPnFNyX7YUo9Ebfc8.jpg',2001,'Comedy,Hindi Dub','Lizzie McGuire is all about the ordinary and not-so-ordinary adventures of a junior high student and her two best friends as they try to deal with the ups and downs of school, popularity, boys, parents, a bratty little brother–just life in general. And if Lizzie leaves anything unsaid, you can bet that her cartoon alter ego will say it for her!',63);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('log-horizon-hindi','Log Horizon','https://image.tmdb.org/t/p/w500/xLGdRuWCn2AlByL5Y9OLB3ZwItg.jpg',2013,'Action,Adventure,Anime,Comedy,Crunchyroll,FanDub,Hindi Dub,Isekai,Video Game','One day, while playing the online game Elder Tales, 30,000 players suddenly find themselves trapped in another world. There, eight-year veteran gamer Shiroe also gets left behind. The trapped players are still alive, but they remain in combat with the monsters. The players don’t understand what has happened to them, and they flee to Akiba, the largest city in Tokyo, where they are thrown into chaos. Once proud of his loner lifestyle, Shiroe forms a guild called Log Horizon with his old friend Naotsugu, female assassin Akatsuki and others.',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lord-of-mysteries','Lord of Mysteries','https://image.tmdb.org/t/p/w500/c8fHePq3yTn3WvZd4hupkHwsjm5.jpg',2025,'Action,Adult Cast,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Mystery,Suspense','In a Victorian world of steam, dreadnoughts, and occult horrors, Zhou Mingrui awakens as Klein Moretti. He walks a razor’s edge between light and darkness, entangled with warring Churches. This is the legend of unlimited potential…and unspeakable danger.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('magic-maker-how-to-make-magic-in-another-world','Magic Maker: How to Make Magic in Another World','https://image.tmdb.org/t/p/w500/lXcADJ8Yxx7Bev1eiH0WEX6b1f9.jpg',2025,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','A man who was thirty years old and wanted to use magic died unexpectedly, and when he woke up, he was reborn in another world. Named Theon, he had high hopes that there would be magic in another world, but there was no magic in that world.Theon became depressed and lethargic, but an event led him to discover the existence of magic.“That’s right. If there is no magic, then I will make it myself.”With this in mind, Theon began researching magic from that day onwards. Eventually, through the spread of a disease that can only be cured by magic, and a chance encounter with an enemy that can only be defeated by magic, Theon becomes a hero who saves the world. This is the story of a simple magic fool who, while tossed about by fate, overcomes it with the power of magic and an indomitable fighting',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marriage-toxin','Marriage Toxin','https://image.tmdb.org/t/p/original/2b1akkaoutSo3xbykjAKnEb92Rs.jpg',2026,'Action,Adult Cast,Anime,Comedy,Crunchyroll,Hindi Dub,Shounen,Tamil,Telugu','For centuries, the deadly arts have been perfected by Masters, and Five Great Families hold the greatest power and influence. Hikaru Gero, an heir to the Gero family, lives in the underworld as an elite assassin. When his sister is pressured to produce an heir, Hikaru asks Mei Kinosaki, a brilliant marriage swindler, to find him a bride. The most challenging mission of his life begins!',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvel-disk-wars-the-avengers','Marvel Disk Wars: The Avengers','https://image.tmdb.org/t/p/w500/6wQAZaWSvBJOIIt68cqmC0KJjeE.jpg',2014,'Action & Adventure,Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy','A group of teenagers join forces with the Avengers, Earth’s mightiest heroes, to fight against the tyrannical Loki and his mighty empire.',17);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvels-avengers','Avengers Assemble','https://image.tmdb.org/t/p/w500/vchDkX1DtqTy3bIDJ7YqmSbX965.jpg',2013,'Action,Adventure,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Marvel’s Avengers AssembleThe further adventures of the Marvel Universe’s mightiest general membership superhero team. With an all-star roster consisting of Iron Man, Captain America, Thor, Hulk, Hawkeye, Falcon and, occasionally–when she feels like it and only when she feels like it–Black Widow, the Avengers are a team in the truest sense. The Avengers save the world from the biggest threats imaginable–threats no single super hero could withstand.Please Note That Seasons 3-4-5 are not available in Tamil and Telugu.',132);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvels-future-avengers','Marvel’s Future Avengers','https://image.tmdb.org/t/p/w500/buxBvftqx3g57FTYtdrfGSHlWfQ.jpg',2017,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi','Makoto, Adi, and Chloe attend a special training school where they train to become the heroes of the next generation. Unfortunately for them they are actually science experiments for Hydra. When Adi and Chloe get captured by Hydra for learning the truth, Makoto seeks out the one group he believes could help them- The Avengers. After rescuing the kids The Avengers decide to take them in and train them to be the heroes of the future.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvels-guardians-of-the-galaxy','Guardians of the Galaxy','https://image.tmdb.org/t/p/w500/oXwe3wVhdvvxiixL9UJf6PgBybZ.jpg',2015,'Action,Adventure,Cartoon,Hindi Dub,Sci-Fi,Tamil,Telugu','Marvel’s Guardians of the GalaxyPeter Quill is Star-Lord, the brash adventurer who, to save the universe from its greatest threats, joins forces with a quartet of disparate misfits — fan-favorite Rocket Raccoon, a tree-like humanoid named Groot, the enigmatic, expert fighter Gamora and the rough edged warrior Drax the Destroyer.Please Note That Season 3 is not available in Tamil and Telugu.',77);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mashle-magic-and-muscles-hindi','MASHLE: MAGIC AND MUSCLES','https://image.tmdb.org/t/p/w500/j4uI3VfubinCGzatlZcRcjrLyZ1.jpg',2023,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Mashle: Magic and Muscles – The Divine Visionary Candidate Exam ArcIn the magic realm, magic is everything—everyone can use it, and one’s social status is determined by their skill level. Deep in the forest, oblivious to the ways of the world, lives Mash. Thanks to his daily training, he’s become a fitness god, but he harbors a secret that could turn his life upside down—he can’t use magic! When he’s found out, rather than his life being over, he’s unexpectedly enrolled in magic school, where he must beat the competition!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('max-steel','Max Steel','https://image.tmdb.org/t/p/w500/fuLkBrqnA5hzGkRoSN4lbVbXK0x.jpg',2013,'Action & Adventure,Animation,Hindi Dub,Sci-Fi & Fantasy','Max Steel is a science fiction–comedy, CGI–animated series. It is a re-imagining of its predecessor of the same name, as well as being based on the Mattel action-figure also of the same name. Max Steel premiered on March 25, 2013 on Disney XD.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mechanical-marie','Mechanical Marie','https://image.tmdb.org/t/p/w500/vsH56qFI4GEjeIPcIFIBEF6aaT9.jpg',2025,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Shoujo,Tamil,Telugu','Former martial arts legend Marie has accepted a new job as a “mechanical maid”… except she’s 100% human, and Arthur, her new boss, despises humans. Luckily, Marie’s naturally expressionless face helps her keep up the robot act while secretly protecting Arthur from constant assassination attempts. But when Arthur falls in love with his “perfect” maid, things quickly spiral out of control!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('metallic-rouge-hindi','Metallic Rouge','https://image.tmdb.org/t/p/w500/oLMLxZBmIFE6tWg5s8UwuYOWTVI.jpg',2024,'Action,Anime,Crunchyroll,Hindi Dub,Sci-Fi,Tamil,Telugu','Metalic RougeIn a world where humans coexist with androids called Neans, a group known as the Immortal Nine rises up against society. Tasked with disposing of the revolters, a Nean named Rouge Redstar (aka Metal Rouge) and investigator Naomi Orthmann head to Mars to track them down…but first, Rouge wants some chocolate.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('monster-kid','Monster Kid','https://image.tmdb.org/t/p/w500/xpBE2Y2drI7pbyuzOZIJrS8uWiz.jpg',1980,'Anime,Comedy,Family,Hindi Dub,Horror,Kids','As part of his training to succeed the throne, he visits the human world, where he has various adventures with other monsters.',63);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('cells-at-work','Cells at Work!','https://image.tmdb.org/t/p/w500/fds2pm7Ug8bZo45qdoJ3gFuvA8o.jpg',2018,'Anime,Anthropomorphic,Comedy,Educational,Hindi Dub,Medical,Shounen','This is a story about you. A tale about the inside of your body… According to a new study, the human body consists of approximately 37 trillion cells. These cells are hard at work every day within a world that is your body. From the oxygen-carrying red blood cells to the bacteria-fighting white blood cells, get to know the unsung heroes and the drama that unfolds inside of you! It’s the oddly relatable and interesting story that is the life of cells!',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('chip-n-dale-rescue-rangers','Chip ‘n’ Dale Rescue Rangers','https://image.tmdb.org/t/p/w500/3V9MXtyTgsxUkjGbTZtVF4EUh25.jpg',1989,'Animation,Cartoon,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','Chip and Dale head a small, eccentric group of animal characters who monitor not only the human world, but the animal community as well, solving mysteries wherever they may be. The “Rescue Rangers” take the cases that fall through the cracks.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('chorr-police','Chorr Police','https://image.tmdb.org/t/p/w500/pT5YsGAi48HocitQH3oFdpoEKfr.jpg',0,'Animation,Cartoon,Comedy,Hindi Dub,Kids','Anthony is a thief who lives in the slums of Mumbai. He usually steals not for himself, but for other people. Because of which, he is known as the Robinhood Slumdog of Mumbai. Not that it matters who he steals for, since the police will try to catch him anyway. His constant battle to outwit Lovely Singh, and they both find themselves in adventures one after the other.',81);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('clifford-the-big-red-dog','Clifford the Big Red Dog','https://image.tmdb.org/t/p/w500/z1iZDanC2hlBF5puxAdxaLg5h4M.jpg',2000,'Animation,Kids','The adventures of a larger-than-life red dog on Bridwell Island.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('code-geass-lelouch-of-the-rebellion','Code Geass: Lelouch of the Rebellion','https://image.tmdb.org/t/p/w500/nF0qzl8jfQYxynra99WrC1zFq4C.jpg',2006,'Action,Anime,Crunchyroll,Drama,Hindi Dub,Mecha,Military,School,Sci-Fi,Super Power','Japan has been invaded and conquered by the Britannian Empire. Japan is now known as Area 11 and its citizens known as Elevens. The Britannian Empire takes away Japan’s autonomous power and imposes its rule through the use of Knightmares. The Empire’s rule has never faltered, but cracks have begun to show…',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('cyberpunk-edgerunners','Cyberpunk: Edgerunners','https://image.tmdb.org/t/p/w500/7jSWOc6jWSw5hZ78HB8Hw3pJxuk.jpg',2022,'Action,Anime,Crime,FanDub,Gore,Hindi Dub,Sci-Fi','In a dystopia riddled with corruption and cybernetic implants, a talented but reckless street kid strives to become a mercenary outlaw — an edgerunner.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('daemons-of-the-shadow-realm','Daemons of the Shadow Realm','https://image.tmdb.org/t/p/original/x9tqZfZLzu6T6q7wuySI8k7Qytf.jpg',2026,'Action,Adventure,Anime,Crunchyroll,Hindi Dub,Shounen,Supernatural,Tamil,Telugu','In a remote mountain village under the watchful eyes of two stone guardians, the young Yuru contentedly lives off the land while staying close to the only family he has left—Asa, his precious twin sister. Asa, meanwhile, carries out a mysterious “duty” on behalf of the village while locked in a cage. Why is Asa a prisoner? And what other secrets does Yuru’s otherwise idyllic home hide?',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dandelion','Dandelion','https://image.tmdb.org/t/p/w500/r5Cq5wax0sQ1ModcZXWKyXF1xpy.jpg',2026,'Animation,Anime,Comedy,Drama,Hindi Dub,Sci-Fi & Fantasy','At an afterlife agency where angels guide lingering souls, Tetsuo and Misaki take on any challenge to help the dead find peace in their own offbeat style.',7);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('daniel-spellbound','Daniel Spellbound','https://image.tmdb.org/t/p/w500/83jBawRjY6YF8RjoopVZ92UvFYM.jpg',2022,'Action,Adventure,Cartoon,Fantasy,Hindi Dub','In New York City, a teenage tracker makes his living selling hard-to-find mystical items to sorcerers — but dealing in magic can be risky business.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dark-moon-the-blood-altar','DARK MOON: THE BLOOD ALTAR','https://image.tmdb.org/t/p/w500/68HcRvCpiajsPhKn1MnV4hqeCAN.jpg',2026,'Anime,Crunchyroll,Fantasy,Hindi Dub,School,Tamil,Telugu,Vampire','In the seaside city of Riverfield stands Decelis Academy, home to seven mysterious boys sharing the same secret: They’re vampires, hiding their murky pasts. When Sooha, a female student who hates vampires, transfers to the academy, the boys find themselves irresistibly drawn to her. As strange events shake the city, old sins and buried secrets resurface, and their world begins to fracture.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('darling-in-the-franxx','DARLING in the FRANXX','https://image.tmdb.org/t/p/w500/rR8HgnD9tqFaSiJ69FpruHo9Gm9.jpg',2018,'Action,Crunchyroll,Drama,Hindi Dub,Mecha,Romance,Sci-Fi,Tamil,Telugu','The story is set in the distant future. The land is ruined, and humanity establishes the mobile fort city Plantation. Pilots produced inside Plantation live in Mistilteinn, also know as the “birdcage.” Children live there knowing nothing of the outside world or the freedom of the sky. Their lives consist of battling to carry out missions. Their enemies are mysterious giant lifeforms known as Kyouryuu, and the children pilot robots called Franxx to face off against them. For the children, riding the Franxx proves their existence.A boy named Hiro is called Code:016, and he was once known as a prodigy. However, he has fallen behind, and his existence seems unnecessary. Not piloting a Franxx is the same as ceasing to exist. One day, a mysterious girl known as “Zero Two” appears before him. Two',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dave-the-barbarian','Dave the Barbarian','https://image.tmdb.org/t/p/w500/ipzGJybXsUyqP78Wn6zC1XXbyRy.jpg',2004,'Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','This animated comedy series is set in the Middle Ages and follows the title character, Dave, in his comedic adventures with his family (his sisters, Candy and Fang) as they protect themselves and their family from a world of oddball foes. Dave himself combines strength with an appreciation of the finer things in life, including origami, bird watching, and even gourmet cooking.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dead-mount-death-play','Dead Mount Death Play','https://image.tmdb.org/t/p/w500/t22CwD44ZmtNozu3RKxNSZ3hzKq.jpg',2023,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,Reincarnation,Seinen,Tamil,Telugu','As a legendary hero nears victory against a necromancer known as The Corpse God, things take an unexpected turn with the dark sorcerer’s final gambit—reincarnation magic. This last-ditch effort catches the brave fighter off guard, and now he’s a boy named Polka Shinoyama in a whole new world! The showdown between good and evil just got epic.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('death-note','Death Note','https://image.tmdb.org/t/p/w500/tCZFfYTIwrR7n94J6G14Y4hAFU6.jpg',2006,'Anime,Anime Times,Hindi Dub,Mystery,Psychological,Shounen,Supernatural,Suspense,Tamil,Telugu','Light Yagami is an ace student with great prospects—and he’s bored out of his mind. But all that changes when he finds the Death Note, a notebook dropped by a rogue Shinigami death god. Any human whose name is written in the notebook dies, and Light has vowed to use the power of the Death Note to rid the world of evil. But will Light succeed in his noble goal, or will the Death Note turn him into the very thing he fights against?',37);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dexters-laboratory','Dexter’s Laboratory','https://image.tmdb.org/t/p/w500/inJJn8lUPWdvdy2h259UnoHWVqC.jpg',1996,'Cartoon,Comedy,Fantasy,Hindi Dub,Kids,Sci-Fi','Dexter, a boy-genius with a secret laboratory, constantly battles his sister Dee Dee, who always gains access despite his best efforts to keep her out, as well as his arch-rival and neighbor, Mandark.Please Note That Episode Numbers and Name Will not Match Because Episode List is Imported From TheMovieDatabse But Episodes are Ripped From Amazon Prime (Different Order)',163);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('digimon-adventure','Digimon Adventure:','https://image.tmdb.org/t/p/w500/7Qspx2eFX0uBSQLLlAKnYrjZgse.jpg',2020,'Action,Adventure,Comedy,Fantasy,Hindi Dub,Isekai,Kids,Tamil,Telugu','It’s the year 2020. The Network has become something humans can no longer do without in their daily lives. But what humans don’t know is that on the other side of the Network is the Digital World, a realm of light and darkness. Nor are they aware of the Digimon who live there. Fifth grader Taichi Yagami]s mother and little sister Hikari went to Shibuya, and now they’re aboard a runaway train. Taichi hurries to Shibuya to save his mother and sister, but the instant he heads toward the station platform… a strange phenomenon befalls the DigiDestined, and Taichi goes to the Digital World!',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('digimon-fusion','Digimon Fusion','https://image.tmdb.org/t/p/w500/4jX2k06hM9p489ML1byyBQHEKl5.jpg',2010,'Action & Adventure,Animation','Digimon Fusion, known in Japan as Digimon Xros Wars and in Malaysia as Digimon Fusion Battles, is the sixth anime children television series in the Digimon franchise by Akiyoshi Hongō, produced by Toei Animation. It follows a boy named Taiki Kudō who utilizes the power of joining together Digimon in order to save the Digital World. The series’ was broadcast on TV Asahi and Asahi Broadcasting Corporation between July 6, 2010 and March 25, 2012, divided into three seasons, titled Xros Wars, The Evil Death Generals and the Seven Kingdoms and The Young Hunters Who Leapt Through Time respectively.The series has been licensed outside of Asia by Saban Brands and is internationally by MarVista Entertainment. An English-language version, produced by Saban, began airing in North America on Nickelode',54);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dino-girl-gauko','Dino Girl Gauko','https://image.tmdb.org/t/p/w500/cH7utN2b5YbqPTcz9p24YVUf1Za.jpg',2019,'Animation,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','When she gets angry, middle schooler Naoko turns into fierce dinosaur Gauko! Thanks to friends, aliens and more, her life is full of wacky incidents.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dinosaur-king','Dinosaur King','https://image.tmdb.org/t/p/w500/y6KWd6u4sU6vXMA9b9Gj9M5NvtJ.jpg',2007,'Action & Adventure,Animation,Comedy,Hindi Dub,Sci-Fi & Fantasy','Dinosaur King is a card-based arcade game from Sega that uses the same gameplay mechanics from Mushiking but uses super-powered dinosaurs instead of beetles. The game was revealed in JAMMA 2005 and is available in Japanese and English versions. A Nintendo DS version has also been released in North America.In the fall of 2008, Upper Deck Company released a Dinosaur King Trading Card Game. This card game is not to be confused with the cards used for the arcade machines.The series has been adapted into an anime TV series, Ancient Ruler Dinosaur King DKidz Adventure, which is made by Sunrise and premiered on TV Asahi on February 4, 2007. As of 2008, an English adaptation aired on the 4Kids TV block on the Fox Network, but moved to The CW’s The CW4Kids block on September 6, 2008.A sequel was an',79);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dragon-ball-daima','Dragon Ball DAIMA','https://image.tmdb.org/t/p/w500/cIDPZMGsiVHkHA6HPJmEmGcgyyw.jpg',2024,'Action,Adventure,Comedy,Crunchyroll,Fantasy,Hindi Dub,Martial Arts,Shounen,Super Power,Tamil,Telugu','Mysteriously transformed into mini versions of themselves, Goku and his friends travel to the Demon Realm to uncover the truth and find a cure.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dragon-ball-super','Dragon Ball Super','https://image.tmdb.org/t/p/w500/kbhu0tIv5E1PbAw2YPjrhoQ7I1s.jpg',2015,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Shounen,Tamil,Telugu','DBSWith Majin Boo defeated half-a-year prior, peace returns to Earth, where Son Goku (now a radish farmer) and his friends now live peaceful lives. However, a new threat appears in the form of Beerus, the God of Destruction. Considered the most terrifying being in the entire universe, Beerus is eager to fight the legendary warrior seen in a prophecy foretold decades ago known as the Super Saiyan God. The series retells the events from the two Dragon Ball Z films, Battle of Gods and Resurrection ‘F’ before proceeding to an original story about the exploration of alternate universes.',131);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('dragon-ball-z-kai','Dragon Ball Z Kai','https://image.tmdb.org/t/p/w500/mU7i4WdnBrtDKJAxU8vl41ej6Ly.jpg',2009,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Shounen,Tamil,Telugu','Rejoin Goku and his friends in a series of cosmic battles! Toei has redubbed, recut, and cleaned up the animation of the original 1989 animated series. The show’s story arc has been refined to better follow the comic book series on which it is based. The show also features a new opening and ending. In the series, martial artist Goku, and his various friends, battle increasingly powerful enemies to defend the world against evil. Can Earth’s defender defeat demons, aliens, and other villains?',167);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ducktales','DuckTales','https://image.tmdb.org/t/p/w500/mBXPGrYd9wEzk7jpi5GkZJNDzZf.jpg',2017,'Cartoon,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','Duck TalesThe adventures of billionaire Scrooge McDuck and his nephews Huey, Dewey and Louie, their famous uncle Donald Duck, pilot extraordinaire Launchpad, Mrs. Beakly, Webby and Roboduck. Adventures and hidden treasures are everywhere, in their hometown Duckburg and all around the world.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('easygoing-territory-defense-by-the-optimistic-lord','Easygoing Territory Defense by the Optimistic Lord','https://image.tmdb.org/t/p/w500/2ctXv1LyyVad5VLToS1t2ZqSCQa.jpg',2026,'Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','Reborn as a marquis’ fourth son, Van was once hailed as a genius prodigy—until he’s exiled to a nameless frontier village for possessing Production Magic, a useless type of magic in this world. But when he uses his “useless” power to craft weapons, tools, and wonders beyond imagination, the village begins to thrive! What began as exile is now the start of a new life—and a world-changing adventure!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('el-deafo','El Deafo','https://image.tmdb.org/t/p/w500/uVlojXidNz6CHpkEXuj0rt4ealz.jpg',2022,'Animation,Cartoon,Hindi Dub,Kids','Going to school and making new friends can be tough. Having to do both while wearing a bulky hearing aid on your chest? That takes superpowers! With a little help from her superhero alter ego, El Deafo, Cece learns to embrace her differences.',3);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('elena-of-avalor','Elena of Avalor','https://image.tmdb.org/t/p/w500/se8bejjwLz56qm1gOCLpVjK8iVk.jpg',2016,'Action & Adventure,Cartoon,Hindi Dub,Kids,Tamil,Telugu','The story of a brave teenager who has saved her kingdom from an evil sorceress and must now learn to rule as a crown princess until she’s old enough to be queen.',29);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('even-given-the-worthless-appraiser-class-im-actually-the-strongest','Even Given the Worthless “Appraiser” Class, I’m Actually the Strongest','https://image.tmdb.org/t/p/w500/lUAGrruGGj2PB6CYkw6tGLQD41G.jpg',2025,'Action,Adventure,Anime,Drama,Fantasy,Hindi Dub','In a world where heroes are born, not made, Ein’s god-given gift is the weakest: the power to appraise things. Treated cruelly by his peers, Ein spends his days in self-abasement—until he meets Yuri, the spirit of the World Tree. Yuri and her protector, Ursula, bless Ein with the Spirit Eye, unlocking new strength. As his abilities grow, Ein embarks on a journey to uncover his true purpose.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fairy-tail-100-years-quest','FAIRY TAIL 100 YEARS QUEST','https://image.tmdb.org/t/p/w500/wj5i6YgZj7LltRE3yE6VTgfdbK0.jpg',2024,'Action,Adventure,Anime,Fantasy,Hindi Dub,Shounen','The rowdiest guild in Fiore Kingdom is back! Natsu, Lucy, Gray, Erza, and the whole Fairy Tail guild tackle the legendary “100 Years Quest,” tougher than any S-Class quest. Their goal: find the first wizard guild ever, located in the far north of Guiltina. Facing new gods, mysterious towns, and ominous foes, they’ll have their work cut out for them. Will they succeed where no wizard has before?',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fairy-tail','Fairy Tail','https://image.tmdb.org/t/p/w500/bxk8SZU232wrRm0C5x3R6smHZOP.jpg',2009,'Action,Adventure,Anime,Comedy,Ecchi,Fantasy,Hindi Dub,Shounen','Lucy is a 17-year-old girl, who wants to be a full-fledged mage. One day when visiting Harujion Town, she meets Natsu, a young man who gets sick easily by any type of transportation. But Natsu isn’t just any ordinary kid, he’s a member of one of the world’s most infamous mage guilds: Fairy Tail.',279);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('farming-life-in-another-world','Farming Life in Another World','https://image.tmdb.org/t/p/w500/pT4OoVQE8zGJ0Z0GZpJotK5Vzsj.jpg',2023,'Anime,Anime Times,Comedy,Fantasy,Hindi Dub,Isekai,Slice of Life','After Hiraku dies of a serious illness, God brings him back to life, gives his health and youth back, and sends him to a fantasy world of his choice. In order to enjoy his second shot, God bestows upon him the almighty farming tool! Watch as Hiraku digs, chops, and ploughs in another world in this laidback farming fantasy!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fast-furious-spy-racers','Fast & Furious Spy Racers','https://image.tmdb.org/t/p/w500/ejqbIUDbSWlgDeCoKBFGwbFML3N.jpg',2019,'Action,Adventure,Cartoon,Family,Hindi Dub,Kids','Fast and Furious Spy RacersA government agency recruits teen driver Tony Toretto and his thrill-seeking friends to infiltrate a criminal street racing circuit as undercover spies.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fire-force','Fire Force','https://image.tmdb.org/t/p/w500/GXPzNvuDGzWikMEduV99kocohn.jpg',2019,'Action,Anime,Comedy,Crunchyroll,Hindi Dub,Shounen,Supernatural,Tamil,Telugu','Year 198 of the Solar Era in Tokyo, special fire brigades are fighting against a phenomenon called spontaneous human combustion where humans beings are turned into living infernos called “Infernals”. While the Infernals are first generation cases of spontaneous human combustion, later generations possess the ability to manipulate flames while retaining human form. Shinra Kusakabe, a youth who gained the nickname Devil’s Footprints for his ability to ignite his feet at will, joins the Special Fire Force Company 8 which composes of other flames users as they work to extinguish any Infernals they encounter. As a faction that is creating Infernals appears, Shira begins to uncover the truth behind a mysterious fire that caused the death of his family twelve years ago.',73);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('fish-hooks','Fish Hooks','https://image.tmdb.org/t/p/w500/gkmlFc6kE2djINsy2RWGVHlex73.jpg',2010,'Animation,Comedy,Hindi Dub,Tamil,Telugu','This inventive animated comedy series, set inside a giant fish tank in Bud’s Pet Shop, presents high school life as seen through the eyes of three BFFs (best fish friends), Bea, Milo and Oscar. Together they experience the typical life challenges and triumphs, including friendship, dating and sports, along with more atypical situations such as giant lobster attacks and, with the use of special land suits, school field trips to the hamster cages. The series was created by children’s book illustrator Noah Z. Jones and features a notable voice cast. It’s produced using an innovative mixture of digital animation and photo collage',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('food-wars-shokugeki-no-soma','Food Wars! Shokugeki no Soma','https://image.tmdb.org/t/p/w500/pZ7ctuVxTdSs09Fpoha5of6ozJm.jpg',2015,'Anime,Comedy,Drama,Ecchi,Gourmet,Hindi Dub,School,Shounen,Zee Cafe','Yukihira Souma’s dream is to become a full-time chef in his father’s restaurant and surpass his father’s culinary skill. But just as Yukihira graduates from middle schools his father, Yukihira Jouichirou, closes down the restaurant to travel and cook around the world. Although downtrodden, Souma’s fighting spirit is rekindled by a challenge from Jouichirou which is to survive in an elite culinary school where only 10% of the students graduate. Can Souma survive?',86);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('g-i-joe-renegades','G.I. Joe: Renegades','https://image.tmdb.org/t/p/w500/sRGqn7kzeQOVUdRdYGRZlYDObdu.jpg',2010,'Action,Adventure,Cartoon,Hindi Dub','GI Joe RenegadesThe adventures of the elite G.I. Joe unit, whose members: Duke, Snake Eyes, Scarlett, Roadblock, Tunnel Rat and Ripcord were charged with crimes they did not commit. In order to clear themselves of the charges, they must expose the real culprits, who belong to the powerful corporation COBRA Industries.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gachiakuta','Gachiakuta','https://image.tmdb.org/t/p/w500/84LdrRRvpWk8g0EaaW7z3eKdfum.jpg',2025,'Action,Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Shounen,Tamil,Telugu','Rudo lives in the slums of a floating town, where the poor scrape by under the shadow of the rich who live a sumptuous life, simply casting their garbage off the side, into the abyss. Then one day, he’s falsely accused of murder, and his wrongful conviction leads to an unimaginable punishment—exile off the edge, with the rest of the trash. Down on the surface, the cast-off waste of humanity has bred vicious monsters, and if Rudo wants to have any hope of discovering the truth and seeking vengeance against those who cast him into Hell, he will have to master a new power and join a group known as the Cleaners who battle the hulking trash beasts of the Pit!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gantz','GANTZ','https://image.tmdb.org/t/p/w500/spyDQ1Cv8m4L8EaXS6iXSpbLWA.jpg',2004,'Action,Anime,Drama,Gore,High Stakes Game,Hindi Dub,Horror,Psychological,Sci-Fi,Survival,Suspense','Knowing that he is risking his life, Kei Kurono makes the uncharacteristic decision to jump onto train tracks to save a homeless man from death, only to perish in the process. But when he comes to, Kei finds himself in a room with several other recently deceased people, as well as a large, mysterious black ball. While the people in the room are trying to make sense of their situation, the ball suddenly opens, revealing a cache of weapons and strange black suits. The ball then instructs everyone that they have to hunt down an alien and teleports them to an unknown location.With very little information to work off of, Kei teams up with his childhood friend Masaru Katou and an unfamiliar woman, and the trio explore their new surroundings. It quickly becomes apparent, however, that they have s',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ghost-in-the-shell-sac_2045','Ghost in the Shell: SAC_2045','https://image.tmdb.org/t/p/w500/A7s3pbj8x8nWcXSp54xfJSiR3xs.jpg',2020,'Action,Adult Cast,Anime,Detective,Hindi Dub,Mecha,Military','Ghost in the Shell SAC 2045After a global financial crisis, the world is engulfed in an AI-driven “sustainable war.” It’s up to Section 9 to counter new forms of cyber threats.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ghost-stories','Ghost Stories','https://image.tmdb.org/t/p/w500/9muUVVBl5gpBzZTGUmvjzKWUge9.jpg',2000,'Animation,Anime,Comedy,Hindi Dub,Horror,Sci-Fi & Fantasy','Satsuki and Keiichirou Miyanoshita are two siblings recovering from the loss of their mother. After moving to their mother’s hometown, they learn that the local school they have transferred is said to be haunted. Despite brushing it off as a silly rumor, the two soon discover that ghosts are indeed real.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('go-go-cory-carson','Go! Go! Cory Carson','https://image.tmdb.org/t/p/w500/atgbow7Z65jSc57N5S1OA0xtpnV.jpg',2020,'Animation,Kids','Beep, beep — go, go! Buckle up for fun and adventure with adorable kid car Cory Carson as he explores the winding roads of Bumperton Hills.',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('goldie-bear','Goldie & Bear','https://image.tmdb.org/t/p/w500/9T8qmeof7eRe2xgXKOWJ6bgIkSK.jpg',2015,'Animation,Hindi Dub,Kids,Tamil,Telugu','You’ve heard the story of Goldilocks and the Three Bears, but did you hear what happened after the story ended? Goldilocks apologized to Bear and now they’re best friends.',46);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('good-bye-dragon-life','Good Bye, Dragon Life','https://image.tmdb.org/t/p/w500/n15iwXmYASiAEWUvkfoVKEIoqWq.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Reincarnation,Tamil,Telugu','Goodbye Dragon LifeLong ago, the most ancient of divine dragons was slain by a human. The mighty dragon accepted its death when suddenly, it was reborn as Dolan, a man who lives in a quiet village. While spending another peaceful day toiling in the fields, he meets Celina, a half-human, half-snake creature looking for a partner. The unlikely duo become friends, but challenges lie ahead that threaten their new bond.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gravity-falls','Gravity Falls','https://image.tmdb.org/t/p/w500/t9inzSLIttATX6RdnmDjL7T4WN7.jpg',2012,'Animation,Cartoon,Comedy,Hindi Dub,Kids,Mystery,Sci-Fi & Fantasy,Tamil,Telugu','Twin brother and sister Dipper and Mabel Pines are in for an unexpected adventure when they spend the summer helping their great uncle Stan run a tourist trap in the mysterious town of Gravity Falls, Oregon.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('green-lantern-the-animated-series','Green Lantern: The Animated Series','https://image.tmdb.org/t/p/w500/eu42AsWNv6fQR92dtjhuGo1tVxM.jpg',2011,'Action,Adventure,Cartoon,Hindi Dub','The Green Lanterns Hal and his partner Kilowog fight against the forces of the Red Lanterns.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('guin-saga','Guin Saga','https://image.tmdb.org/t/p/w500/4bipHVo1teci5N8dc0pe0VO5UHm.jpg',2009,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','グイン・サーガ“The seal will be broken after many years”. In the land of Nospherus, four heroes embark on a patch of destiny that will weave a new legend. The story follows Guin, a powerful swordsman with a leopard head, the adolescent royal twins Remus and Rinda, and the young and ambitious mercenary named Istvan.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('gummy-bear-friends','Gummy Bear & Friends','https://image.tmdb.org/t/p/w500/a08YYW71hdKIJzwtEESiV3u3VcX.jpg',2016,'Action & Adventure,Animation,Cartoon,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','The silly adventures of everyone’s favorite gummy bear character and his friends Kala the cat and Harry the chameleon.',14);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('haddi-mera-buddy','Haddi Mera Buddy (New Dub)','https://image.tmdb.org/t/p/w500/gxdTn5UwvriN1EzDSNnWr5AAQN7.jpg',2001,'Cartoon,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','The Grim Adventures of Billy and MandyBilly Mandy Aur Life Mein HaddiThe exploits of the Grim Reaper, who has been forced into being the best friend of two children. A spin-off of the show Grim & Evil.Please Note That Episode Number and Name Will not Match.',147);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('haikyu','Haikyuu!! (Crunchyroll Dub)','https://image.tmdb.org/t/p/w500/rm39VFnu0giTTccK0vSsPsKiatj.jpg',2014,'Anime,Crunchyroll,Hindi Dub,School,Shounen,Sports,Tamil,Telugu','Haikyu!!Inspired by a small-statured pro volleyball player, Shouyou Hinata creates a volleyball team in his last year of middle school. Unfortunately the team is matched up against the “King of the Court” Tobio Kageyama’s team in their first tournament and inevitably lose. After the crushing defeat, Hinata vows to surpass Kageyama. After entering high school, Hinata joins the volleyball team only to find that Tobio has also joined.',87);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hana-kimi','Hana-Kimi','https://image.tmdb.org/t/p/w500/cWZ6ed6qfkq1Y7cSgWRg22ugLFP.jpg',2026,'Anime,Comedy,Crossdressing,Crunchyroll,Drama,Hindi Dub,Love Polygon,Romance,School,Shoujo,Tamil,Telugu','HanakimiHana KimiJapanese-American track-and-field star Mizuki has gotten herself to transfer to a high school in Japan…but not just any school! To be close to her idol, high jumper Izumi Sano, she’s going to an all-guys’ high school…and disguising herself as a boy! But as fate would have it, they’re more than classmates…they’re roommates! Now, Mizuki must keep her secret in the classroom, the locker room, and her own bedroom. And her classmates–and the school nurse–must cope with a new transfer student who may make them question their own orientation…',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hanaori-san-still-wants-to-fight-in-the-next-life','Hanaori-san Still Wants to Fight in the Next Life','https://image.tmdb.org/t/p/original/h2JZRLaFXWWhh61vAjqgHXeiZd8.jpg',2026,'Anime,Comedy,Crunchyroll,Hindi Dub,Reincarnation,Romance,School,Seinen,Supernatural,Tamil,Telugu','Once the Demon King, now a shut-in NEET—Ryusei Narukami’s second life is anything but peaceful! When Meteor Hanaori, the Hero who once defeated him, suddenly returns as a normal high school girl, his world is thrown into chaos. Determined to change, Ryusei reenters society as a teacher and ends up teaching at her school! Their explosive reunion reignites the past—and sparks an unexpected love!',9);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('handyman-saitou-in-another-world','Handyman Saitou in Another World','https://image.tmdb.org/t/p/w500/xp404PMU2cGsODMTIkkUizbYhcm.jpg',2023,'Adult Cast,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai','Handyman Saito has never been anyone special. All his life, he’s had average grades, ordinary athletic skill, a commonplace job… But his unremarkable path takes a turn when he wakes up in another world. Here, warriors, wizards, and elves accompany him on quests delving deep into dungeons, and Saito realizes for the first time what it’s like to be needed. After all, who other than the handyman could be trusted to open locked treasure chests or repair his allies’ equipment? Beginning with a simple “thank you,” this is the story of an ordinary person’s fulfilling life.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hatim','Hatim','https://image.tmdb.org/t/p/w500/hoTQPG6DJmKkMGaR2idZmUwTbEE.jpg',2003,'Action,Adventure,Drama,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Hatim is an Indian television series that originally aired on STAR Plus channel in 2003-4. It is about an Arab prince Hatim Tai, a pre-Islamic Christian from Yemen and the father of Adi bin Hatim and Safana bint Hatim who was the companions of the Prophet Muhammad, Hatim has to solve seven questions to defeat the evil sorcerer lord Dajjal aided by Najumi. It has elements of fantasy. It was started by director Sagar, based on one of Jeetendra’s films Hatimtai.',47);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hawa-hawai-family','Hawa Hawai Family','https://image.tmdb.org/t/p/w500/rArFXabdxInLa4NRaAo6VwS7J68.jpg',2009,'Animation,Anime,Comedy,Hindi Dub','Kaasan Mom’s LifeA sidesplitting essay in animation that depicts the simple everyday life of career-committed mother and her rather out of standard family set in contemporary Japan.',1);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hazbin-hotel','Hazbin Hotel','https://image.tmdb.org/t/p/w500/aVYHMW8pdzJ9qG1OGRMKyGy9xor.jpg',2024,'Cartoon,Comedy,Crime,Hindi Dub','In attempt to find a non-violent alternative for reducing Hell’s overpopulation, the daughter of Lucifer opens a rehabilitation hotel that offers a group of misfit demons a chance at redemption.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hero-bhakti-hi-shakti-hai','Hero – Bhakti Hi Shakti Hai','https://image.tmdb.org/t/p/w500/xWX66szqmnGFokRzdZJtqCB2paG.jpg',2005,'Action,Adventure,Drama,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Hero – Bhakti Hi Shakti Hai is a live-action superhero TV series that airs in India. The show first aired on Hungama TV on 30 May 2005 on UTV’s Kids channel Hungama TV. It was then aired on Jetix. The show is produced by Zarina Mehta, Ronnie Screwvala and Deven Khote.“Hero has strong emotional appeal and Indian values, which along with the fantasy and comedy elements should make a great viewing experience for kids. Our research shows that kids enjoy the theme of ‘Good winning over evil’ and the struggle that follows”, says Hungama TV head of programming Zarina Mehta.Created by Arif Ali of UTV and directed by Waseem Sabir, the series stars Sumeet Pathak as Hero. Viewers also got an opportunity to be a ‘Hero’ by participating in the ‘Be A Hero Contest’ by watching the show. The winner of the',103);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('he-man-and-the-masters-of-the-universe','He-Man and the Masters of the Universe','https://image.tmdb.org/t/p/w500/khU0nt0PAbX0t6IpBBvTxm1uzoZ.jpg',2021,'Action & Adventure,Animation,Family,Hindi Dub,Sci-Fi & Fantasy','Mighty teen Adam and his heroic squad of misfits discover the legendary power of Grayskull — and their destiny to defend Eternia from sinister Skeletor.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('horimiya','Horimiya','https://image.tmdb.org/t/p/w500/k61vVOnVjyfjgvEG0d2G8K8Mi5c.jpg',2021,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Romance,School,Shounen','Horimiya The Missing PiecesHorimiya PieceHorimiya Missing PiecesA secret life is the one thing they have in common. At school, Hori is a prim and perfect social butterfly, but the truth is she’s a brash homebody. Meanwhile, under a gloomy facade, Miyamura hides a gentle heart, along with piercings and tattoos. In a chance meeting, they both reveal a side they’ve never shown. Could this blossom into something new?',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('hotel-transylvania-the-series','Hotel Transylvania: The Series','https://image.tmdb.org/t/p/w500/mdPDFNqO7NWUtZIt66nMOmji7hg.jpg',2017,'Animation,Cartoon,Comedy,Family,Hindi Dub','Mavis navigates life without her dad, Dracula, around and discovers one of the few common human and monster truths: being a teenager bites.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('i-became-a-legend-after-my-10-year-long-last-stand','I Became a Legend After My 10 Year-Long Last Stand','https://image.tmdb.org/t/p/original/4LaPshxWTFcBhc5ib8xOfYeD9tH.jpg',2026,'Action & Adventure,Animation,Anime,Hindi Dub,Sci-Fi & Fantasy','Luck, an S-rank mage in the hero’s party, makes a last stand against the Demon King to save his companions. When he finally returns victorious, ten years have passed, and the world praises him as a legendary hero who died in battle. Unable to reclaim his former life, Luck conceals his identity and begins again as “Lock,” an F-rank adventurer forging a future in a world that moved on without him.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('i-got-a-cheat-skill-in-another-world','I Got a Cheat Skill in Another World','https://image.tmdb.org/t/p/w500/2kTYmmOU8SsDxSijIDpz9vkT9la.jpg',2023,'Action,Adventure,Crunchyroll,Fantasy,Hindi Dub,Isekai,School','I Got a Cheat Skill in Another World and Became Unrivaled in the Real World, TooA door to another world stretches out before a boy who’s been brutally bullied all his life. This alternate reality grants him access to all sorts of things, like cheat skills and a portal that lets him travel between his old and new worlds! Can this class loser turn his life around back home…?',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('i-left-my-a-rank-party-to-help-my-former-students-reach-the-dungeon-depths','I Left My A-Rank Party to Help My Former Students Reach the Dungeon Depths!','https://image.tmdb.org/t/p/w500/XAKKKNkKjVPgV2LTCLLXNvMdWI.jpg',2025,'Action,Adventure,Anime,Crunchyroll,Fantasy,Harem,Hindi Dub,Romance','Not every party treats you like a hero—especially when you’re a lowly red mage like Yuke. So, after years of constant ridicule by his A-rank party members, he ditches them. Searching for a new party, he reunites with former students Marina, Silk, and Rain, and joins their group. But on a quest to conquer the world’s greatest dungeon, they become entangled in chaos that threatens the world.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('i-parry-everything','I Parry Everything','https://image.tmdb.org/t/p/w500/arYDvPe3MS4lgt6K4gYRlXCJhXS.jpg',2024,'Action,Adventure,Comedy,Fantasy,Hindi Dub','Noor’s dead set on becoming an adventurer, even if the only skills he possesses are useless ones. Sure, he can [Parry] thousands of swords in the span of a single breath, but you need more than that if you want to be an adventurer! Right?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('i-shall-survive-using-potions-hindi','I Shall Survive Using Potions!','https://image.tmdb.org/t/p/w500/gQfeSDEMZ6QgqOR7cHV6y4DoKNP.jpg',2023,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','Kaoru Nagase, a 22-year-old office lady, suddenly finds herself reincarnated in another world. To help her survive in this new world, a being that amounts to its god gives Kaoru a younger body and… the ability to make insanely overpowered potions?! The reincarnated Kaoru must use her knowledge and cheatery to survive!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('idaten-jump','Idaten Jump','https://image.tmdb.org/t/p/w500/uB1v2Ad0tqzMnV3GZ6ZnFzdXJz4.jpg',2005,'Anime,Hindi Dub,Kids,School,Sports,Tamil','The show follows the exciting adventures of Sho Yamato, a boy who loves to race his Idaten bike and ends up getting lost, along with his friends, in a mysterious place called the X-Zone. The kids get involved in many action-packed racing adventures as they try to unlock the secret to getting home.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('if-my-favorite-pop-idol-made-it-to-the-budokan-i-would-die','If My Favorite Pop Idol Made It to the Budokan, I Would Die','https://image.tmdb.org/t/p/w500/n8tBDlRzWOA8ywyQNv3t9EokHVx.jpg',2020,'Animation,Anime,Comedy,Hindi Dub,Tamil,Telugu','Passionate music-lover Eripiyo only wants to see her favorite underground pop group, ChamJam, make it to the big stage at Budokan. Because they’ve enriched her life by their very existence, Eri is willing to dedicate everything she has to see this dream fulfilled—even her health. At their last performance she got a crazy nosebleed. Hey, no one said being a super-fan was easy!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ill-become-a-villainess-who-goes-down-in-history','I’ll Become a Villainess Who Goes Down in History','https://image.tmdb.org/t/p/w500/puEALjAyIJj5MjSJVBfddincKtm.jpg',2024,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Romance,Shoujo,Tamil,Telugu,Villainess','I Will Become a Villainess Who Goes Down in HistoryThis young girl hates all those goodie-two-shoes heroines. So when she’s reincarnated as Alicia, the villain in her favorite fantasy dating sim, it’s like a dream come true! There’s just one problem: the more she tries to be evil, the more the prince seems to fall for her. Alicia will have to work much harder if she ever wants to become the world’s greatest villainess.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('im-standing-on-a-million-lives','I’m Standing on a Million Lives','https://image.tmdb.org/t/p/w500/vdUva7C2B1wZI2D4vjBSWJIc8IG.jpg',2020,'Action,Adventure,Anime,Anime Times,Drama,Fantasy,Hindi Dub,Isekai,Shounen','Ninth grader Yotsuya Yuusuke is practical, friendless, and not active in any clubs. Then one day, he and two female classmates are suddenly sent to another world where they must work together to battle for their lives. Yotsuya is a lone wolf and has always lived his life according to his wants, but how will that work out now that he’s supposed to be a hero?!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('inside-job','Inside Job','https://image.tmdb.org/t/p/w500/qwJUDMJ4i3KBYjeUFK9Js87iJEa.jpg',2021,'Animation,Cartoon,Comedy,Hindi Dub','For employees of the Deep State, conspiracies aren’t just theories — they’re fact. And keeping them a secret is a full-time job.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('invincible','Invincible','https://media.themoviedb.org/t/p/w600_and_h900_face/4tblBrslcKSifMVZ3TmtT2ukMor.jpg',2021,'Action,Adventure,Cartoon,Drama,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Mark Grayson is a normal teenager except for the fact that his father is the most powerful superhero on the planet. Shortly after his seventeenth birthday, Mark begins to develop powers of his own and enters into his father’s tutelage.',32);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('iron-man-anime','Iron Man Anime','https://image.tmdb.org/t/p/w500/zOTJT7JbzSrMBX2OCGPqUnkQA4y.jpg',2010,'Action,Anime,Drama,Hindi Dub,Mecha','When Tony Stark branches his company into Japan, he is opposed by the nefarious Zodiac organization. It’s up to Stark’s Iron Man to defeat the Zodiac, and defend Japan.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('iron-man-armored-adventures','Iron Man: Armored Adventures','https://image.tmdb.org/t/p/w500/uwMIL8PR1jHpHQksIq7kzdeqg2A.jpg',2009,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi','Iron Man: Armored Adventures is a 3D CGI cartoon series based on the Marvel Comics superhero Iron Man. It debuted in the USA on the Nicktoons on April 24, 2009, and has already begun airing on Canadian network Teletoon. Iron Man: Armored Adventures aired on Nickelodeon on July 4, 2009 until September 12, 2009. The series is story edited by showrunner Christopher Yost, who also worked on Wolverine and the X-Men, and numerous other Marvel Animation projects. The television show is not related to the 2007 animated film The Invincible Iron Man; It has a different voice cast, but some story elements are similar and the show uses the same musical score as the film in some instances. It is the first Iron Man television series since Iron Man from 1994–1996, and started airing after the success of ',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('iron-man','Iron Man','https://image.tmdb.org/t/p/w500/nTQWWH6CFtl37x1nPx8HRwbwvGn.jpg',1994,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Iron Man Animated SeriesIndustrialist Tony Stark leads a private team of superheroes as Iron Man against the forces of evil.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ive-been-killing-slimes-for-300-years-and-maxed-out-my-level','I’ve Been Killing Slimes for 300 Years and Maxed Out My Level','https://image.tmdb.org/t/p/w500/oN8fY2He8Fb87uL67I7ctf63mR4.jpg',2021,'Anime,Anime Times,Comedy,Fantasy,Hindi Dub,Isekai','After dying of overwork in the real world, I’m reincarnated as an immortal witch, and I spend 300 years enjoying a relaxing life. At some point, though, I end up at level 99! All those years spent killing slimes to make the money to pay the bills gave me a ton of experience points. Rumors of the level 99 witch spread, and soon I’m up to my ears in curious adventurers, duelist dragons, and even a monster girl calling me her mom! I’ve never been on an adventure, but I’m the strongest in the world… What’s going to happen to my relaxing life?!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jaadugar-a-witch-in-mongolia','Jaadugar: A Witch in Mongolia','https://image.tmdb.org/t/p/original/723NT7KY9xBFLYNNBaEEREbLaPC.jpg',2026,'Animation,Anime,Crunchyroll,Drama,Hindi Dub,War & Politics','After losing her mother and her homeland, Sitara’s despair transforms into determination with the power of knowledge. New possibilities unfold when a family of scholars takes her in, deepening her education. Meanwhile, Genghis Khan’s Mongol Empire conquers nation after nation, nearing Sitara’s new home. After the Fourth Prince of the empire takes her captive, a flame of revenge is ignited.',7);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jack-of-all-trades-party-of-none','Jack-of-All-Trades, Party of None','https://image.tmdb.org/t/p/w500/qRvICaz6LJXz96DaYcpTjQf6QN8.jpg',2026,'Action,Adventure,Anime,Anime Times,Fantasy,Hindi Dub','Betrayed by his childhood friend and cast out of the Hero Party, Orhun Dura—once their loyal Enchanter—is branded by his former comrades as “a jack-of-all-trades but a master of none.” Alone, he sets out to forge a new path as a solo adventurer. His journey sparks explosive battles, deadly rivals, and unexpected allies—and he’ll rise to shatter every expectation. The ultimate solo comeback begins!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jackie-chan-adventures','Jackie Chan Adventures','https://image.tmdb.org/t/p/w500/by2GTFpd2BQ5uJxWPlfcmfrNrfB.jpg',2000,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Tamil,Telugu','Jackie Chan teams up in this animé-style adventure with his 11-year-old niece, Jade, traveling the globe to locate a dozen magical talismans before the sinister Dark Hand does. Helping Jackie and Jade is Uncle, a cantankerous but wise antiquities expert. Though officially Jackie works as an archaeologist, in reality he also assists Captain Black, leader of the covert police squad Section 13.',95);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jentry-chau-vs-the-underworld','Jentry Chau vs the Underworld','https://image.tmdb.org/t/p/w500/gCVwVPOajqfILlAUwKGmNwVZofb.jpg',2024,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','As her 16th birthday approaches, a not-so-average teen rediscovers the fiery powers she’s long suppressed and is forced to face her demons — literally.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('johnny-test','Johnny Test','https://image.tmdb.org/t/p/w500/cGceNrHpUl3utUzE502xSY8l9ST.jpg',2005,'Cartoon,Comedy,Hindi Dub,Kids','Young Johnny is gung-ho and full of courage. Johnny’s brainiac twin sisters, Susan and Mary, use Johnny as their guinea pig for their outrageous scientific experiments. If they can dream it up, Johnny will do it; as long as his genetically engineered super dog, Dukey, can come along.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jojos-bizarre-adventure','JoJo’s Bizarre Adventure','https://image.tmdb.org/t/p/original/1HXdeK67pYSAukeZDhS3GJU8nIC.jpg',2012,'Action,Adventure,Anime,Historical,Shounen,Supernatural,Vampire','Follow the intergenerational feud between the Joestar Family and various forces of evil, the most prominent of which is Dio Brando and his followers.',98);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('jujutsu-kaisen-hindi','Jujutsu Kaisen','https://image.tmdb.org/t/p/w500/dGvJUOS01OrgDntHXGF04tW6oJ5.jpg',2020,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,School,Supernatural,Tamil,Telugu','Yuji Itadori is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a classmate who has been attacked by curses, he eats the finger of Ryomen Sukuna, taking the curse into his own soul. From then on, he shares one body with Ryomen Sukuna. Guided by the most powerful of sorcerers, Satoru Gojo, Itadori is admitted to Tokyo Jujutsu High School, an organization that fights the curses… and thus begins the heroic tale of a boy who became a curse to exorcise a curse, a life from which he could never turn back.',59);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('junji-ito-collection','Junji Ito Collection','https://image.tmdb.org/t/p/w500/umJEelwoLi3x123sbJ9pMTPA5Lt.jpg',2018,'Anime,Drama,Hindi Dub,Horror,Mystery,Psychological,Supernatural,Suspense','In the light of day and in the dead of night, mysterious horrors await in the darkest shadows of every corner. They are unexplainable, inescapable, and undefeatable. Be prepared, or you may become their next victim.Sit back in terror as traumatizing tales of unparalleled terror unfold. Tales, such as that of a cursed jade carving that opens holes all over its victims’ bodies; deep nightmares that span decades; an attractive spirit at a misty crossroad that grants cursed advice; and a slug that grows inside a girl’s mouth. Tread carefully, for the horrifying supernatural tales of theItou Junji: Collectionare not for the faint of heart.',14);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('justice-league','Justice League','https://image.tmdb.org/t/p/w500/caIAQIoM9NLZofT8fz8t47W1gYe.jpg',2001,'Action,Adventure,Cartoon,Hindi Dub','The long-awaited rebirth of the greatest superhero team of all time: Batman, Superman, The Flash, Wonder Woman, Hawkgirl, Green Lantern and Martian Manhunter.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kaguya-sama-love-is-war','Kaguya-sama: Love Is War','https://image.tmdb.org/t/p/w500/lMpWexSeAhtEho2KSSa1rhCUuAd.jpg',2019,'Anime,Comedy,Hindi Dub,Romance,School,Seinen','Considered a genius due to having the highest grades in the country, Miyuki Shirogane leads the prestigious Shuchiin Academy’s student council as its president, working alongside the beautiful and wealthy vice president Kaguya Shinomiya. The two are often regarded as the perfect couple by students despite them not being in any sort of romantic relationship.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kamen-rider-gavv','Kamen Rider Gavv','https://image.tmdb.org/t/p/w500/3iHHmX7txgjptGkdqY3Q6V0r0Fk.jpg',2024,'Action & Adventure,Drama,Kids,Sci-Fi & Fantasy','Granutes are intelligent lifeforms that operate secretly in the human world. They kidnap people for the sake of “Black Market Sweets.” As people are attacked one after another by the Granutes, Shoma, a young man from another world, rises up to save the people. Together with the Gochizo, small monsters born from eating sweets, he transforms into Kamen Rider Gavv with a mouth-like belt!',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kamikatsu-working-for-god-in-a-godless-world','KamiKatsu: Working for God in a Godless World','https://image.tmdb.org/t/p/w500/d82CH1EMSoC2VvYSTxCZHPboJYq.jpg',2023,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Mystery,Sci-Fi','Yukito, the son of a questionable cult leader, lost his life due to the cult’s ridiculous training practices. Now to his surprise, he was reincarnated into another world! It was an ideal world for him without the concept of “God” or “religion” BUT…! A unique “reincarnating in other world” adventure begins: creating a “religion” in a world without God?!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('karna-the-guardian','Karna the Guardian','https://image.tmdb.org/t/p/original/3M7PkwXvT2scTNUoXOaCqlIpfVM.jpg',2026,'Action & Adventure,Animation,Anime,Hindi Dub,Tamil,Telugu','Karna lives as an ordinary boy—until the ancient demon Kalimba breaks free and spreads corruption across the world. When the darkness infects his mother, Karna’s powers awaken, revealing his true identity: the Balancer, a Guardian born to restore harmony to the world. To save his mother and stop Kalimba’s chaos, Karna must train to master the power within him—or risk losing everything.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kick-buttowski-suburban-daredevil','Kick Buttowski: Suburban Daredevil','https://image.tmdb.org/t/p/w500/syxcG3suyf3U00z5HOuLbZ9eozl.jpg',2010,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Kids,Tamil,Telugu','Clarence Buttowski, a young boy, aspires to become the world’s greatest daredevil, as he gets help from Gunther, his loyal friend and partner-in-crime.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kid-cosmic','Kid Cosmic','https://image.tmdb.org/t/p/w500/88HdcCMumGqGAt2kR3vVOr8NYiA.jpg',2021,'Action & Adventure,Animation','A boy’s superhero dreams come true when he finds five powerful cosmic stones. But saving the day is harder than he imagined — and he can’t do it alone.',18);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kid-vs-kat','Kid vs. Kat','https://image.tmdb.org/t/p/w500/1f3DyCY4Xe6ZxN2blj0gNdWhS71.jpg',2008,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Kid vs. Kat is a Canadian-American animated television series developed and produced at Studio B Productions. The show was created and co-directed by Rob Boutilier. The series is distributed by Studio B Productions. The feature revolves around a 10-year-old boy’s constant battle with his sister’s Sphinx cat which, in reality, is a cybernetic alien.The show premiered on YTV in Canada on October 25, 2008, aired on Disney XD in the United States on February 21, 2009, and then ended on June 4, 2011. It ran for 2 seasons, spanning 52 episodes.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kiteretsu','Kiteretsu','https://image.tmdb.org/t/p/w500/rkCwT6NmATLsm1SNLEFNZ3JCzva.jpg',1988,'Anime,Comedy,Drama,Hindi Dub,Kids,Slice of Life,Tamil,Telugu','Kiteretsu EncyclopediaKiteretsu DaihyakkaThe main character is a scientific genius boy named Kiteretsu, who has built a companion robot named Korosuke. He frequently travels in time with his friends and Korosuke in the time machine he built. Miyoko is a girl in his neighborhood who is basically his girlfriend. Tongari is his rival, who happen to share some similar traits of Honekawa Suneo. Buta Gorilla is a typical neighborhood bully, who also share similar traits of Gian except that he often antagonizes Korosuke (though they are in grade school).',156);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('konosuba-an-explosion-on-this-wonderful-world','KONOSUBA – An Explosion on This Wonderful World!','https://image.tmdb.org/t/p/original/68rh8l8RaGujTDF6k87yykxixIy.jpg',2023,'Action & Adventure,Animation,Anime,Comedy,Hindi Dub','This feisty young wizard will stop at nothing to master the spell that saved her life: Explosion! Megumin, the “Greatest Genius of the Crimson Magic Clan,” has chosen to devote her studies to the powerful offensive magic used by her mysterious savior. Then one day, her little sister finds a black kitten in the woods. But this cat isn’t just a new furry friend—she’s the key to awakening a Dark God!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('konosuba-gods-blessing-on-this-wonderful-world','KONOSUBA – God’s blessing on this wonderful world!','https://image.tmdb.org/t/p/original/oRaOeQlwktbGSd2T31FYAcgHZlh.jpg',2016,'Action & Adventure,Animation,Anime,Comedy,Crunchyroll,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','After a traffic accident, Kazuma Sato’s disappointingly brief life was supposed to be over, but he wakes up to see a beautiful girl before him. She claims to be a goddess, Aqua, and asks if he would like to go to another world and bring only one thing with him. Kazuma decides to bring the goddess herself, and they are transported to a fantasy world filled with adventure, ruled by a demon king. Now Kazuma only wants to live in peace, but Aqua wants to solve many of this world’s problems, and the demon king will only turn a blind eye for so long…',31);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kung-fu-panda-legends-of-awesomeness','Kung Fu Panda: Legends of Awesomeness','https://image.tmdb.org/t/p/w500/rkq5Jt7boR5v65bDbELHz3DW7sv.jpg',2011,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Martial Arts','A martial-arts loving panda gets help from his mentor and friends as he becomes a warrior and protects the valley where he lives.',80);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('kunon-the-sorcerer-can-see','Kunon the Sorcerer Can See','https://image.tmdb.org/t/p/w500/kGGdMa1fEwMiyyFB1AnUox5cshy.jpg',2026,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Seinen,Tamil,Telugu','Kunon, a young man who cannot see, has the goal of creating new eyes with water magic. After just five months of learning sorcery, Kunon surpassed his own mentor and honed his talent as he tried to do a feat that’s never been done before. A fantasy about a young man, a blind genius, who opens up the world through curiosity in the pursuit for magic is about to begin.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('legend-of-exorcism','Legend of Exorcism','https://image.tmdb.org/t/p/original/kmElJ49MJNj3sQhKv6GrUqWyPVa.jpg',2020,'Action & Adventure,Amazon Prime,Animation,Anime,Anime Times,Hindi Dub,Sci-Fi & Fantasy','After leaving Yaojin Palace, Kong Hongjun arrives in Chang’an to battle demons and forms a bond with exorcism squad chief Li Jinglong.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lets-play','Let’s Play','https://image.tmdb.org/t/p/w500/sTZuWf7wV99y13VAYw1fBclgFKu.jpg',2025,'Adult Cast,Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Tamil,Telugu','Lets PlaySamara “Sam” Young is a developer in Los Angeles who’s about to achieve her dreams with her first video game, Ruminate. That is, until a popular streamer gives the game a scathing review. Even worse, Sam finds out the troublesome critic is now her new neighbor! Get lost in a comedic, romantic, and all-too-real story about gaming, memes, and social anxiety. Come for the plot, stay for the doggo.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('lilo-stitch-the-series','Lilo & Stitch: The Series','https://image.tmdb.org/t/p/w500/997mXFpYV2zdXK4EOctN3hgciaT.jpg',2003,'Action,Adventure,Cartoon,Comedy,Family,Fantasy,Hindi Dub,Kids,Sci-Fi','This animated series chronicles the further adventures of renegade scientist Dr. Jumba Jookiba’s beloved Experiment 626, who is now living happily as Lilo’s alien buddy Stitch. Jumba’s remaining experiments have landed all over Hawaii in the form of dehydrated pods. Lilo and Stitch’s mission is to catch Stitch’s “cousins” before they fall into the clutches of the evil Dr. Jacques von Hamsterviel!',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('loonatics-unleashed','Loonatics Unleashed','https://image.tmdb.org/t/p/w500/oHGY83FvCpMqBGjftalcBzI6tIx.jpg',2005,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub','Ace Bunny, Tech E. Coyote, Danger Duck, and friends are transformed into superheroes when a meteor hits the planet 700 years in the future. Now they spend their time making jokes while blasting monsters and asteroids with “neutron cannons” and whatever other weapons they have at hand.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('love-death-robots','Love, Death & Robots','https://image.tmdb.org/t/p/w500/cRiDlzzZC5lL7fvImuSjs04SUIJ.jpg',2019,'Cartoon,Fantasy,Hindi Dub,Sci-Fi','Terrifying creatures, wicked surprises and dark comedy converge in this NSFW anthology of animated stories presented by Tim Miller and David Fincher.',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mech-cadets','Mech Cadets','https://image.tmdb.org/t/p/w500/5awFqxnqJHQD0TQCasf8VjAWqTb.jpg',2023,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub','An underdog teen joins a group of young Cadets who’ve been chosen to bond with Robo Mechs from space and defend Earth against alien invaders.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('minnies-bow-toons','Minnie’s Bow-Toons','https://image.tmdb.org/t/p/w500/73iPSqVXjzrkoPwnEo37kLzs6BS.jpg',2011,'Animation,Cartoon,Hindi Dub,Kids,Tamil,Telugu','Minnie Mouse has a passion for fashion, along with good friend Daisy Duck, of Minnie’s Bow-tique, a specialty shop that sells only bows and bow ties.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('miraculous-tales-of-ladybug-cat-noir','Miraculous: Tales of Ladybug & Cat Noir','https://image.tmdb.org/t/p/w500/3bxuTGk0c98gQkgBcKzC6HxQ8B6.jpg',2015,'Action,Adventure,Cartoon,Hindi Dub,Kids','Normal high school kids by day, protectors of Paris by night! Miraculous follows the heroic adventures of Marinette and Adrien as they transform into Ladybug and Cat Noir and set out to capture akumas, creatures responsible for turning the people of Paris into villains. But neither hero knows the other’s true identity – or that they’re classmates!',131);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('miss-kuroitsu-from-the-monster-development-department','Miss Kuroitsu From the Monster Development Department','https://image.tmdb.org/t/p/w500/eilm1SsfGlKrdB4jZfo5stUfbgi.jpg',2022,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu,Workplace','Touka Kuroitsu is a research assistant who belongs to the Monster Development Department of the evil organization Agastia. However, the enemy she has to fight right now isn’t the heroes of justice, but her boss.So long justice exists, evil too, will exist. This is the story of those who fight secretly in the shadows of justice and evil’s confrontation.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mobile-suit-gundam-gquuuuuux','Mobile Suit Gundam GQuuuuuuX','https://image.tmdb.org/t/p/w500/fyPkuoqllQX6k8KbjJvkkEAIgpq.jpg',2025,'Action,Drama,Hindi Dub,Mecha,Sci-Fi,Space','High-school student Amate Yuzuriha lives peacefully in a space colony floating in outer space. But when she meets a war refugee named Nyaan, Amate is drawn into the illegal mobile suit dueling sport known as Clan Battle.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mr-bean-the-animated-series','Mr. Bean: The Animated Series','https://image.tmdb.org/t/p/w500/1V2PSez4pNZ9a4Bbomm7KZiQJ44.jpg',2002,'Cartoon,Comedy,Kids','The animated daily trials and tribulations of clueless yet clever loner Mr Bean (aided by his best friend Teddy of course!) as he stumbles from one mishap to the next, always finding complex solutions to the simplest of problems.',130);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-daemon','My Daemon','https://image.tmdb.org/t/p/w500/5bWTE3CwBM6z8lew9BPykujeNwG.jpg',2023,'Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi','To save his mother, a kind-hearted boy and his tiny daemon friend set out on a journey across post-apocalyptic Japan as dark forces close in.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-dress-up-darling','My Dress-Up Darling','https://image.tmdb.org/t/p/w500/A6mxBwvvv63JXZm3xXKv4SugE0L.jpg',2022,'Anime,Crunchyroll,Hindi Dub,Romance,School,Seinen,Slice of Life,Tamil,Telugu','Sono Bisque Doll wa Koi wo SuruMy Dressup DarlingMy Dress Up DarlingWakana Gojo is a high school boy who wants to become a kashirashi–a master craftsman who makes traditional Japanese Hina dolls. Though he’s gung-ho about the craft, he knows nothing about the latest trends, and has a hard time fitting in with his class. The popular kids–especially one girl, Marin Kitagawa–seem like they live in a completely different world. That all changes one day, when she shares an unexpected secret with him, and their completely different worlds collide.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-hero-academia-vigilantes','My Hero Academia: Vigilantes','https://image.tmdb.org/t/p/w500/iv0cXt6uJGlTryWZNQMGyum4Pme.jpg',2025,'Action,Anime,Crunchyroll,Drama,Hindi Dub,Shounen,Super Power,Tamil,Telugu','After a life-changing incident, timid college student Koichi Haimawari accepts an offer from revered vigilante Knuckleduster to train as his protégé.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-unique-skill-makes-me-op-even-at-level-1','My Unique Skill Makes Me OP Even at Level 1','https://image.tmdb.org/t/p/w500/cIrptxkpf3SNcPty3JaywvWRJ5w.jpg',2023,'Anime,Crunchyroll,Fantasy,Harem,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','Ryota Sato gets the surprise of his life when he’s suddenly transported into another world and nearly clobbered at the hands of the young, pretty adventurer Emily Brown. This new world revolves around defeating monsters and profiting on whatever they drop—food, money, items, etc. Unfortunately for Ryota, he has no skills to speak of…until he learns he has the ability to get rare drops! Suddenly his luck turns around…or does it?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('naruto-shippuden-hindi-tamil-telugu','Naruto Shippūden','https://image.tmdb.org/t/p/w500/rXD6lcg6zhRE8NDRVlQPNkViC3s.jpg',2007,'Action,Adventure,Anime,Fantasy,Hindi Dub,Malayalam,Martial Arts,Shounen,Tamil','After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work. It will not be easy though as he has amassed a few more dangerous enemies, in the likes of the shinobi organization; Akatsuki.',361);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('no-longer-allowed-in-another-world','No Longer Allowed in Another World','https://image.tmdb.org/t/p/w500/mKOeQuH7BRrd6Fu4Exx2r0rJF5b.jpg',2024,'Adventure,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Parody,Tamil,Telugu','Pulled into an otherworldly adventure with cute sidekicks and superpowers, you’d think Osamu hit the jackpot. Nope! From a time before pixels, the early 20th-century gloomy author just wants to find a quiet place to meet his maker, not to rack up XP. Sadly, his poetic demise is constantly thwarted by inconvenient heroics. Dive into the hilariously tragic life of the most reluctant hero!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('one-piece','One Piece','https://image.tmdb.org/t/p/w500/fqOUJhVYQchjaxOPHiBJ6I7Gr1l.jpg',1999,'Action,Adventure,Fantasy,Hindi Dub,Kannada,Malayalam,Shounen,Tamil,Telugu','Years ago, the fearsome Pirate King, Gol D. Roger was executed leaving a huge pile of treasure and the famous “One Piece” behind. Whoever claims the “One Piece” will be named the new King of the Pirates.Monkey D. Luffy, a boy who consumed a “Devil Fruit,” decides to follow in the footsteps of his idol, the pirate Shanks, and find the One Piece. It helps, of course, that his body has the properties of rubber and that he’s surrounded by a bevy of skilled fighters and thieves to help him along the way.Luffy will do anything to get the One Piece and become King of the Pirates!',214);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-concierge','Pokémon Concierge','https://image.tmdb.org/t/p/w500/2k53AsWsLrMtcbFyH0nVOqQjj2x.jpg',2023,'Anime,Family,Fantasy,Hindi Dub,Kids,Tamil,Telugu','Welcome to Pokémon Resort, a peaceful getaway for Pokémon to relax and have fun. Which adorable guest will the new concierge Haru befriend and help first?',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-mega-evolution-special','Pokémon Mega Evolution Special','https://m.media-amazon.com/images/M/MV5BMmVmNjAyMzYtODIxMy00OWRlLTk5MTgtMmQ3NGEzMDE1OTY5XkEyXkFqcGdeQXVyMjQ5NjMxNDA@._V1_FMjpg_UX1000_.jpg',2014,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Tamil,Telugu','Pokemon XY: Mega EvolutionPreviously an assistant of Miare City’s Professor Platane, Alain and his Lizardon set off on a journey to become even stronger, by mastering the powers of mega evolution. Investigating the mysteries of this phenomenon, at the behest of the enigmatic Fleur-de-lis, Alain and Lizardon travel across Kalos and Hoenn in search of capable trainers who can use mega evolution in order to improve, as well as help Fleur-de-lis with his research. Along the way, they meet a young girl named Manon who, with her Harimaron, decide to accompany Alain, to which he reluctantly agrees.Pokemon XY: Mega Evolution follows Alain and Lizardon in their journey to become the strongest users of mega evolution, while also fighting against legendary monsters to protect the ambitions of Fleur-d',4);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-16-bw-adventures-in-unova','Pokémon Season 16 BW Adventures in Unova','https://image.tmdb.org/t/p/w500/pNv5RFdy4WZzIipVnf3hZw5Hycz.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-24-master-journeys','Pokémon Season 24 Master Journeys','https://image.tmdb.org/t/p/w500/wrZARmey5XeSj35rK5hF8rYg8e8.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',42);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-5-master-quest','Pokémon Season 5 Master Quest','https://image.tmdb.org/t/p/w500/4Tr6pjlKidQbSPp6wKf855Sq3L1.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-sun-and-moon','Pokémon Season 20 Sun and Moon','https://image.tmdb.org/t/p/w500/fuOpNNenRUyOA0BjvXqcdzQxo3J.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi,Tamil','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',43);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-ranger-super-megaforce','Power Ranger Season 21 Super Megaforce','https://image.tmdb.org/t/p/w500/rxflGIJHDBDhTF56ZiyGMm4vy27.jpg',2014,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','When Prince Vekar decides to attack the Earth, Gosei arms the Megaforce Rangers with new Morphers and keys that enable them to unlock the Megazords of the past rangers and fight to save the planet.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-dino-super-charge','Power Rangers Season 23 Dino Super Charge','https://image.tmdb.org/t/p/w500/pbMKhCDOAq6QhAmvoSRkNgJGpFX.jpg',2016,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','The Dino Charge Rangers disband after defeating Sledge, but their job isn’t done just yet. One of Sledge’s most dangerous criminals, Heckyl, and his alter ego Snide, are aiming to pick up where Sledge left off and harness the power of the Energems to rule the universe. With new weapons, new allies, new zords, and the new T-Rex Super Charge mode, the Rangers are ready to settle the score against one of their most dangerous enemies!',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-dino-thunder','Power Rangers Season 12 Dino Thunder','https://image.tmdb.org/t/p/w500/gvCxb6qB6e6DQWZIE48nrjbaAtc.jpg',2004,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','A team of unlikely personalities join forces to help save the Earth from the scheming Mesogog, a dinosaur-like villain who wishes to destroy humankind.',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-lightspeed-rescue','Power Rangers Season 8 Lightspeed Rescue','https://image.tmdb.org/t/p/w500/nXOwakqruopTpMTOpf5XSwqdf88.jpg',2000,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Five extraordinary teens carry on the legacy as the Lightspeed Power Rangers, the newest and most powerful team of champions ever, dedicated to fighting evil and protecting all that is good.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-lost-galaxy','Power Rangers Season 7 Lost Galaxy','https://image.tmdb.org/t/p/w500/A8JDTFej7msrh2Rm2zFT0uZQ73I.jpg',1999,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','A group of youngsters set out on a space journey to Terra Venture in search of a new colony to live. Soon, empowered by mystical swords, they prepare themselves to fight evil space villains.',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-ninja-steel','Power Rangers Season 24 Ninja Steel','https://image.tmdb.org/t/p/w500/i07YIo21os120MQwtCcWhZvai7n.jpg',2017,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','An evil Galvanax tries to take over the galaxy with the help of his minions. However, the Power Rangers try to defy him to save Earth from destruction.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-rpm','Power Rangers Season 17 RPM','https://image.tmdb.org/t/p/w500/2oFp5zwFx2z0DkYNEfr72GMNTMD.jpg',2009,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','AI computer virus Venjix is all set to attack Corinth, the only city that has survived the carnage by its droids. The RPM Power Rangers must learn to use the advanced biotech vehicles to save mankind.',32);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-s-p-d','Power Rangers Season 13 S.P.D.','https://image.tmdb.org/t/p/w500/5IMzZOdPZKeOwiJZomiGk6c7Bwn.jpg',2005,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','In the future, the people of Earth welcome extraterrestrial beings to live with them. But peace is short-lived when the alien forces become destructive, driving the Power Rangers SPD into action.',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-samurai','Power Rangers Season 18 Samurai','https://image.tmdb.org/t/p/w500/Dap6XoRYzVOlVZNi2FjCIT6jtQ.jpg',2011,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi,Tamil,Telugu','The five Power Rangers set out to battle against the evil forces. However, they must first learn the ancient Samurai symbols of power to control elements like fire, water, sky, forest, and earth.',23);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-super-ninja-steel','Power Rangers Season 25 Super Ninja Steel','https://image.tmdb.org/t/p/w500/z4Z4diQqOc23JpFJt0QuyqH1Kpu.jpg',2018,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','With the help of their new gear and abilities, the Power Rangers attempt to stop Madame Odious and her minions from gaining control over the mythical Ninja Nexus Prism.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('radiant','Radiant','https://image.tmdb.org/t/p/w500/o19uFUrC9gLa366Sr41kSJM8vRz.jpg',2018,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Seth is a boy who seeks to become a great magician, and a group of witches who seek to travel to the Radiant. Radiant is a mythical land that spawns monsters called “Néméses” which fall to the world from the sky. While traveling, they are also hunted by The Inquisition.',42);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ramayan','Ramayan','https://i.ibb.co/hLZjNqt/image.png',0,'Action,Animation,Hindi Dub','',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ranking-of-kings-the-treasure-chest-of-courage','Ranking of Kings: The Treasure Chest of Courage','https://image.tmdb.org/t/p/w500/9txbeJIHla2QXW3bGi3pgjIsVp5.jpg',2023,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Get ready for a new collection of stories from Ranking of Kings!',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('release-that-witch','Release that Witch','https://image.tmdb.org/t/p/w500/ygXvdkB7Ue9ELUUlQe7wFh5fdJa.jpg',2026,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Tamil,Telugu','Roland, a modern man reborn as a prince in the dangerous Border Town, rescues the witches Anna and Nana Pine from the Church. Harnessing their extraordinary powers, he fuses magic and technology to craft weapons, armies, and steam engines to defend his people. As the Demon Moon rises and conspiracies close in on his family, Roland must lead a revolution to protect his allies and reshape the world.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('relife','ReLIFE','https://image.tmdb.org/t/p/w500/aRK64bB8hMsuZZnitebPyKqOR5d.jpg',2016,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Romance,School','Arata Kaizaki (27) quit the job he landed after graduation in only three months. His life did not go well after that. Now his parents are threatening to stop sending money, and want him to come back to the country. He has no friend or girlfriend to share his troubles with…as he hits rock bottom a strange man named Ryou Yoake appears. He invites Arata to join a societal rehabilitation program for NEETs called ReLife. This program uses a mysterious drug to make him look younger, and sends him back to high school for a year…Season 2/OVA’s are in Hindi Subtitles With English-Japanese Dual Audio.',17);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('rezero-starting-life-in-another-world','Re:ZERO -Starting Life in Another World-','https://image.tmdb.org/t/p/original/oHqYrPAsIiTD5m4DuxumV4er8BU.jpg',2016,'Anime,Anime Times,Comedy,Drama,Hindi Dub,Isekai,Psychological,Suspense,Time Travel','Re ZeroRezeroNOTE: Season 1 – The “Director’s Cut” of the first season has longer episodes, that are mostly two from the original combined into one. This alternate version also extends certain scenes, fixes a few censorship issues, and has everything (including the OVA) in chronological order.Natsuki Subaru, an ordinary high school student, is on his way home from the convenience store when he finds himself transported to another world. As he’s lost and confused in a new world where he doesn’t even know left from right, the only person to reach out to him was a beautiful girl with silver hair. Determined to repay her somehow for saving him from his own despair, Subaru agrees to help the girl find something she’s looking for.',67);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('robotan','Robotan','https://image.tmdb.org/t/p/w500/tUEIWMizOxPCKPICIz6x4AZ0PA6.jpg',1966,'Animation,Anime,Comedy,Hindi Dub','The story about robot named Robotan who came from outside the earth, he met with a kid then they become friends but they always stuck with some troubles because of bad people who chase after Robotan however our hero win the fight every time.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('roboticsnotes','Robotics;Notes','https://image.tmdb.org/t/p/w500/4OPubWATWt2crtoE4Ik9Z60w2mk.jpg',2012,'Anime,Drama,Hindi Dub,Mystery,School,Sci-Fi,Tamil,Telugu','In 2019, Kaito Yashio and Akiho Senomiya are the sole members of the Robotics Club at Central Tanegashima High School in Kyushu, Japan. Kaito is a laid back student and a skilled gamer who is just trying to help Akiho, his childhood friend. She is an energetic positive-thinking girl who yearns to complete the ongoing project of the club: building a functional replica of Gunvarrel, the main robot of a once popular TV series. As they gather new members and try to assemble the robot, Kaito starts stumbling upon secret reports that might reveal a conspiracy of large proportions. Unaware of what he is actually dealing with, Kaito little by little starts discovering clues laid by the mysterious Ko Kimijima.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('scooby-doo-and-guess-who','Scooby-Doo and Guess Who?','https://image.tmdb.org/t/p/w500/g7vQXsELihik4oHJwqhL6WuTJ3j.jpg',2019,'Animation,Comedy,Family,Mystery','ScoobyDoo and Guess Who?Scooby Doo and Guess Who?The Mystery Inc. gang solve bigger mysteries while also encountering many memorable celebrities.',47);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sentenced-to-be-a-hero','Sentenced to Be a Hero','https://image.tmdb.org/t/p/w500/k8bh5mvHDx3czHSF56v9lRyulLC.jpg',2026,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu','In a world where heroism is a punishment, Xylo Forbartz, a condemned goddess killer, battles endless hordes of monstrous abominations as part of Penal Hero Unit 9004. Death is no escape, only a cycle of resurrection and relentless combat. But when Xylo encounters a mysterious new goddess, their unlikely alliance sparks a rebellion that could shatter the chains of eternal punishment.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('shaggy-scooby-doo-get-a-clue','Shaggy & Scooby-Doo Get a Clue!','https://image.tmdb.org/t/p/w500/5pGwh9BKmw6Ciy5EvXqm9aKPZWT.jpg',2006,'Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Shaggy and Scooby Doo Get a Clue!Shaggy and ScoobyDoo Get a Clue!When Shaggy’s rich Uncle Albert goes missing and is presumed dead, Shaggy receives an inheritance, which he uses to upgrade the Mystery Machine so it can transform itself into other types of vehicles. Before disappearing, Uncle Albert made some enemies and it is up to Shaggy and his trusty canine, Scooby-Doo, to defeat those enemies, the most dangerous of whom is evil Dr. Phineas Phibes. Armed with the upgraded Mystery Machine, a loyal robot servant and their new riches, Shaggy and Scooby must stop Dr. Phibes’ evil plans and save the world.',15);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sherazade-the-untold-stories','Sherazade: The Untold Stories','https://image.tmdb.org/t/p/w500/iLE3XxtSXCyLd9m422E1AYTY1BH.jpg',2017,'Action & Adventure,Animation,Comedy','The true story of the classic Arabian Nights tales. We follow Sherazade, the real hero of the famous stories, on her quest to find the Tree of Life and save the Prince of the Golden City, who has been turned into a blue-haired monster.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('shin-chan-all','Shinchan','https://image.tmdb.org/t/p/w500/byaQpxzuzO1PDZ7yvA9zyB7krdn.jpg',1992,'Anime,Comedy,Ecchi,Hindi Dub,Kids,Tamil,Telugu','Shin ChanShin-chanShin-chan, the boy next door, is a walking disaster, creating chaos wherever he goes. With the body of a child and the mind of an adult, Shinchan is wreaking more havoc than any child before. Shin-chan is carefree, optimistic and gets excited about everything. This 5 year-old likes to do things his way.',925);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('skeleton-knight-in-another-world','Skeleton Knight in Another World','https://image.tmdb.org/t/p/w500/jMhzjbRI1iL2ENtMnS3Zm3DBAJw.jpg',2022,'Action,Adventure,Anime,Drama,Fantasy,Hindi Dub,Isekai,Muse India','One day, a gamer played video games until he fell asleep…and when he woke up, he found himself in the game world—as a skeleton! Equipped with the powerful weapons and armor of his avatar but stuck with its frightening skeletal appearance, Arc has to find a place for himself in this new, fantastical land. All his hopes for a quiet life are dashed when he crosses paths with a beautiful elven warrior, setting him on a journey full of conflict and adventure.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sofia-the-first','Sofia the First','https://image.tmdb.org/t/p/w500/AjtUB1siU3hvqNEA85VLOmuXu2I.jpg',2013,'Action,Adventure,Cartoon,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Set in the storybook world of Enchancia, this is the story of Princess Sofia, an adventurous little girl who is learning how to adjust to royal life after her mom marries the king and she becomes a princess overnight.',56);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('star-trek-lower-decks','Star Trek: Lower Decks','https://image.tmdb.org/t/p/w500/2gVVCoxtNtU5fTTyGU1nGwrFl2f.jpg',2020,'Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','The lives of the support crew serving on one of Starfleet’s least important ships, the U.S.S. Cerritos, in 2380. Ensigns Mariner, Boimler, Rutherford and Tendi have to keep up with their duties and their social lives, often while the ship is being rocked by a multitude of sci-fi anomalies.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('summer-time-rendering','Summer Time Rendering','https://image.tmdb.org/t/p/w500/9qFqCxPr1ebHbOmZ1vEmPAHLIM4.jpg',2022,'Anime,Drama,Hindi Dub,Mystery','Upon hearing of Ushio’s death, Shinpei returns to his hometown of Wakayama City on Hitogashima and reunites with his childhood friend’s family. The funeral goes smoothly, but under the surface something strange is brewing on the island. What mysteries await him on this secluded summer island?',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('takopis-original-sin-hindi','Takopi’s Original Sin','https://image.tmdb.org/t/p/w500/xPXDVhVKt0XM34ihoUVMHtLYTw8.jpg',2025,'Anime,Anime Times,Drama,Hindi Dub,Psychological,Sci-Fi,Shounen,Time Travel','A Happy alien, Takopi, lands on Earth with one mission: to spread happiness! When he meets Shizuka, a lonely fourth grader, he vows to bring back her smile using his magical Happy Gadgets. But as he uncovers the pain in her life, Takopi learns that true happiness may require more than gadgets.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('taarak-mehta-kka-chhota-chashmah','Taarak Mehta Kka Chhota Chashmah','https://image.tmdb.org/t/p/w500/pWynIs9NAuPosUBlhg3aWDCmYuk.jpg',2022,'Animation,Cartoon,Comedy,Hindi Dub','The residents of Gokuldham Society encounter several adventures and misadventures as they navigate the ups and downs of life and overcome their struggles together.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('teenage-mutant-ninja-turtles','Teenage Mutant Ninja Turtles','https://image.tmdb.org/t/p/w500/AOzcRvrIe0lD86x93quSZbucx2.jpg',2012,'Action & Adventure,Animation,Cartoon,Hindi Dub,Kids,Sci-Fi & Fantasy,Tamil,Telugu','The Teenage Mutant Ninja Turtles are back in an all-new animated series on Nickelodeon! Surfacing topside for the first time on their fifteenth birthday, the titular turtles, Leonardo, Michelangelo, Raphael and Donatello, find that life out of the sewers isn’t exactly what they thought it would be. Now the turtles must work together as a team to take on new enemies that arise to take over New York City.',104);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('teogonia','Teogonia','https://image.tmdb.org/t/p/w500/zGHrnnFc0p5Pf25qUaAv95JpnJC.jpg',2025,'Action,Adventure,Anime,Crunchyroll,Drama,Hindi Dub','Humans fight to protect their land from invading demi-human tribes in relentless battles. As his world is engulfed by intense warfare, Kai, a village boy from Lag, joins the fight to defend all he knows. After Kai’s comrades fall one by one and he’s injured, he suddenly recalls memories from another life. A fantasy tale unfolds as a village boy explores a world of magic, mystery, and heroism.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('that-time-i-got-reincarnated-as-a-slime-multi-audio','That Time I Got Reincarnated as a Slime','https://image.tmdb.org/t/p/w500/94MjsZUyxubodMPJdWOVkcJ0bdU.jpg',2018,'Action,Adventure,Anime,Anime Times,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','37-year-old corporate worker Mikami Satoru is stabbed by a random killer, and is reborn to an alternate world. But he turns out to be reborn a slime! Thrown into this new world with the name Rimuru Tempest, he begins his quest to create a world that’s welcoming to all races. Broken free from ordinary, stale past life, his fresh adventure in a fantasy world as a slime monster with unique abilities begins.',90);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('thats-so-raven','That’s So Raven','https://image.tmdb.org/t/p/w500/eohThtvBB4i52fyXI68dkWowdGE.jpg',2003,'Comedy,Sci-Fi & Fantasy','No ordinary teenager; Raven Baxter can see glimpses of the future! Watch her schemes and misadventures as she enlists the help of friends, including best friends Eddie and Chelsea, to change life’s little outcomes. Raven’s younger brother, Cory, is obsessed with money and creates get-rich-quick schemes to try to earn cash.',98);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-adventures-of-tenali-raman','The Adventures of Tenali Raman','https://image.tmdb.org/t/p/w500/ukcxSkZ2JBhFmxZPyMvAJO0k3ZF.jpg',2003,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Kids,Malayalam','The Adventures of Tenali Raman is an Indian animated television series that premiered on Cartoon Network on 14 June 2003. It was based on one of the most popular and best-loved characters of Indian folklore. It was produced by Toonz Animation Studios, Trivandrum. Promoted with the tagline “Get Ready for the Rama Effect”, the series aired every Saturday and Sunday on Cartoon Network in India.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-adventures-of-tintin','The Adventures of Tintin','https://image.tmdb.org/t/p/w500/nsdVuFcjB9ahhBUlkJyzXo0Pudq.jpg',1991,'Action & Adventure,Animation,Cartoon,Hindi Dub','Travel with Tintin, the young and intrepid Belgian reporter, and his faithful dog Snowy as they take you from Tibet to the Moon, or from Egypt to the depths of the sea — solving mysteries, pursuing truth and justice, and gambling with their lives.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-case-study-of-vanitas','The Case Study of Vanitas','https://image.tmdb.org/t/p/w500/fvqoSfyfQG0hH9nJAvubq730ymR.jpg',2021,'Anime,Crunchyroll,Hindi Dub,Historical,Mystery,Shounen,Supernatural,Vampire','In 19th-century Paris, young vampire Noé finds the Book of Vanitas in human hands. Calling himself Vanitas, this doctor wields its power and tempts Noé with a plan to “cure” all vampires. Allying with him may be dangerous, but does he have a choice?',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-exiled-heavy-knight-knows-how-to-game-the-system','The Exiled Heavy Knight Knows How to Game the System','https://image.tmdb.org/t/p/original/bADzMfofNWYdxLnlqNuMkO6du34.jpg',2026,'Action & Adventure,Animation,Anime,Crunchyroll,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Born into a prestigious family of master swordsmen, Elymas Edvaughn’s future shatters when he awakens the so-called “defective” Heavy Knight class. Disowned and cast out, he regains memories of another life—and realizes this world mirrors a VR game he once mastered. Armed with knowledge no one else possesses, he sets out to rewrite his fate and prove the strength of the “weakest” class.',11);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-gorilla-gods-go-to-girl','The Gorilla God’s Go-To Girl','https://image.tmdb.org/t/p/w500/wsVUjE78BP7v2KayDnlAKbiY3Av.jpg',2025,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Romance,School','Sophia Reeler, a timid noble, chose the Gorilla God’s blessing—the ultimate combat power. Now her dream of a peaceful student life is shattered as the royal knights recruit her unrivaled strength. Juggling school, the knight life, and her overwhelming power, Sophia learns the hard way that gorilla strength isn’t so simple.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-last-kids-on-earth','The Last Kids on Earth','https://image.tmdb.org/t/p/w500/lTpGn2hgB0WGFGp6Q6ArkEWWTsk.jpg',2019,'Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','Young teenager Jack Sullivan and a group of friends live in a decked-out tree house, playing video games, eating candy, and fighting zombies in the aftermath of a monster apocalypse.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-life-and-times-of-juniper-lee','The Life and Times of Juniper Lee','https://image.tmdb.org/t/p/w500/8Za5FSOQ06B7eqrhn0HxsPrs2i9.jpg',2005,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub','The Life and Times of Juniper Lee is an American animated television series, created by Judd Winick and produced by Cartoon Network Studios. It premiered on Cartoon Network on May 30, 2005, and ended its run on April 9, 2007.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-many-sides-of-voice-actor-radio','The Many Sides of Voice Actor Radio','https://image.tmdb.org/t/p/w500/733lDek9YYMfxplg0ELoi3mkRuH.jpg',2024,'Anime,Comedy,Crunchyroll,Girls Love,Hindi Dub,Samurai,Showbiz','Yuhi Yugure and Yasumi Utatane, high school classmates and co-hosts of a weekly radio program, paint a picture-perfect friendship for their listeners. Yet, in reality, they couldn’t be more different. Their off-air dynamic is a whirlwind of chaos and insults. As their tumultuous relationship unfolds, they navigate the turbulent waters of friendship and rivalry in the cutthroat realm of showbiz.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-mysterious-cities-of-gold','The Mysterious Cities of Gold','https://image.tmdb.org/t/p/w500/teITE9N4ZlciNSkigrI0RvtWZs.jpg',1982,'Action & Adventure,Animation,Kids,Sci-Fi & Fantasy','The adventures of a young Spanish boy named Esteban who joins a voyage to the New World in search of the lost Cities of Gold and his father.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-new-scooby-doo-mysteries','The New Scooby-Doo Mysteries','https://image.tmdb.org/t/p/w500/fjeuHAHmOzXrWTkEgi27cBc0Sa1.jpg',1984,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Picking up where ‘The New Scooby and Scappy Doo Show’ left off. The main difference being that the team is now occasionally joined by Fred Jones and Velma Dinkley to solve mysteries together.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-penguins-of-madagascar','The Penguins of Madagascar','https://image.tmdb.org/t/p/w500/1fRG81M83HgwupmndtgZQOBHh8o.jpg',2008,'Animation,Comedy','The Penguins of Madagascar is an American CGI animated television series airing on Nickelodeon. It stars nine characters from the DreamWorks Animation animated film Madagascar: The penguins Skipper, Kowalski, Private, and Rico; the lemurs King Julien, Maurice, and Mort; and Mason and Phil the chimpanzees. Characters new to the series include Marlene the otter and a zookeeper named Alice. It is the first Nicktoon produced with DreamWorks Animation.A pilot episode, “Gone in a Flash”, aired as part of “Superstuffed Nicktoons Weekend” on November 29, 2008, and The Penguins of Madagascar became a regular series on March 28, 2009. The series premiere drew 6.1 million viewers, setting a new record as the most-watched premiere.Although the series occasionally alludes to the rest of the franchise, ',30);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-perils-of-penelope-pitstop','The Perils of Penelope Pitstop','https://image.tmdb.org/t/p/w500/tEyhRt3ZlBdrIV03pdiK0OW4oZD.jpg',1969,'Cartoon,Family,Hindi Dub,Kids','The Perils of Penelope Pitstop is an American animated television series produced by Hanna-Barbera Productions that premiered on CBS on September 13, 1969. The show lasted two full seasons, with a total of 17 half-hour episodes produced and released, the last first-run episode airing on January 17, 1970. Repeats aired until September 4, 1971. It is a spin-off of the Wacky Races cartoon, reprising the characters of Penelope Pitstop and the Anthill Mob. This show airs reruns on Cartoon Network classic channel Boomerang.',17);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-shiunji-family-children','The Shiunji Family Children','https://image.tmdb.org/t/p/w500/tvhXMejlXyOUo24we09pXSgKw5j.jpg',2025,'Anime,Comedy,Crunchyroll,Hindi Dub,Love Polygon,Romance,Seinen','The Shiunji family with their seven children reside in a mansion within Tokyo’s Setagaya ward. The eldest son, Arata, is tired of being pushed around by his five sisters and daydreams of a life without them. That is, until Arata’s father reveals a shocking truth—Arata isn’t biologically related to his sisters! The siblings’ relationships will be tested as they navigate life in this new light.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-strongest-tanks-labyrinth-raids','The Strongest Tank’s Labyrinth Raids','https://image.tmdb.org/t/p/w500/3Uf8L7wl4dokMukJ855cBLVxQj5.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub','The Strongest Tank’s Labyrinth Raids -A Tank with a Rare 9999 Resistance Skill Got Kicked from the Hero’s Party-Rud, a shielder with a defense stat of 9999, serves as a tank for the Hero’s Party as they carry out raids in labyrinths. When the tyrannical hero suddenly kicks him out of the party, saying his skill is “useless,” Rud makes his way back to his hometown. Along the way, he saves a young girl, and she reveals the true nature of his skill… which turns out to be incredibly powerful!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('theatre-of-darkness-yamishibai','Theatre of Darkness: Yamishibai','https://image.tmdb.org/t/p/w500/coYJ1i9QLlHZTanckLZ4iceptlj.jpg',2013,'Anime,Hindi Dub,Horror,Supernatural','Yamishibai is a picture-story style of animation whose motif is surrounded and based off the rumors, and urban legends throughout the history of Japan.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('there-was-a-cute-girl-in-the-heros-party-so-i-tried-confessing-to-her','There Was a Cute Girl in the Hero’s Party, So I Tried Confessing to Her','https://image.tmdb.org/t/p/w500/lUIuuvxthqaK4euFHTNIsRmdf3s.jpg',2026,'Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Romance,Tamil,Telugu','Yoki was once a human but reincarnated into a demon. He now holds a middling position serving the Demon King tasked with taking down the hero party. But when he finally faces them, Yoki thinks… “”No way… she’s perfect.”” Of all things, he fell in love at first sight with Cecilia, the priest of the hero party! Her serious gaze, her every little gesture—everything about her is too cute! She’s an angel! And so, Yoki made up his mind that he would confess his feelings to her.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('to-be-hero-x','TO BE HERO X','https://image.tmdb.org/t/p/w500/7ynNG9lYS9HIR8cYMgawO19VPkg.jpg',2025,'Action & Adventure,Animation,Anime,Crunchyroll,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','In a world full of brilliant heroes, it’s the trust of fans that turns heroes into superheroes. If a hero loses the people’s trust, they lose their special abilities. Trust value is collected, quantified, and used to determine a hero’s ranking, displayed on their wrist. Every two years, the top heroes go to a tournament to fight, determine new trust values, and earn their rankings.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-botbots','Transformers: BotBots','https://image.tmdb.org/t/p/w500/hKtDA3GG3puz5DGnieFCNRGPpjK.jpg',2022,'Animation,Kids','When the lights go out at the mall, the BotBots come out to play! Meet a fun-loving crew of everyday objects that morph into robots at closing time.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-war-for-cybertron-siege','Transformers: War for Cybertron: Siege','https://image.tmdb.org/t/p/w500/14B6I4FxCMiDoPOwzj27EcqqY6i.jpg',2020,'Action & Adventure,Animation,Kids,Sci-Fi & Fantasy','On their dying planet, the Autobots and Decepticons battle fiercely for control of the AllSpark in the Transformers universe’s origin story.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tron-uprising','TRON: Uprising','https://image.tmdb.org/t/p/w500/9KuIDiBuWQ5VjezynTZ8YJCPBsL.jpg',2012,'Action & Adventure,Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Taking place some time between ‘Tron’ and ‘Tron: Legacy’, ‘Tron: Uprising’ tells the story of Beck, a young program who becomes the skillful leader of a revolution inside the computer world of The Grid.',18);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tsukimichi-moonlit-fantasy','TSUKIMICHI -Moonlit Fantasy-','https://image.tmdb.org/t/p/w500/oGTihBVxHROSWa1WJnireCbl0KQ.jpg',2021,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Tamil,Telugu','Tsukimichi: Moonlit FantasyMakoto Misumi is just an ordinary high school student living a regular life, but all of a sudden gets summoned to the other world to become a “hero.” The goddess of the other world, however, insults him for being different and strips his “hero” title, before casting him off to the wilderness at the edge of the world. As he wanders the wilderness, Makoto encounters dragons, spiders, orcs, dwarves, and all sorts of non-human tribes. Because Makoto comes from a different world, he is able to unleash unimaginable magical powers and combat skills. But just how will he handle his encounters with various species and survive in his new environment. In this fantasy, Makoto tries to transform the other world into a better place despite the humans and gods having turned the',37);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('vipers-creed','Viper’s Creed','https://image.tmdb.org/t/p/w500/3UiSM3pcJnjKZxJYE70BXueAtCv.jpg',2009,'Action,Animation,Anime,Hindi Dub,Sci-Fi','Viper’s Creed is a Mecha action anime series created by Sony Pictures Entertainment Japan with animation by AIC Spirits and Digital Frontier. Though Hiroyuki Kanbe is the main director of the show, Shinji Aramaki is solely responsible for the creation and conception of the show.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('wacky-races','Wacky Races','https://image.tmdb.org/t/p/w500/rgmUxN8vPB4WvvWKEhEpWs8SR9D.jpg',2017,'Cartoon,Family,Hindi Dub','The Wacky Races are back in action! It’s the return of Dick Dastardly, Muttley, Penelope Pitstop, Peter Perfect, and the Gruesome Twosome. New characters are introduced in this incarnation as well such as; I.Q. Ickly, Brick Crashman, P.T. Barnstorm, and Pandora Pitstop.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('watari-kuns-is-about-to-collapse','Watari-kun’s ****** Is About to Collapse','https://media.themoviedb.org/t/p/w440_and_h660_face/mKcZjgm4nT6wb1neM20P8pfAZaT.jpg',2025,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Love Polygon,Romance,School,Seinen,Tamil,Telugu','Naoto Watari lives solely for his little sister, Suzushiro, until his chaotic childhood friend, Satsuki, storms back into his life. Without uttering a single word, her very presence ignites buried memories and unravels his rigid routine. As tensions rise and secrets surface, Naoto’s devotion to Suzushiro clashes with unresolved pain, threatening to collapse his fragile world.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('welcome-to-demon-school-iruma-kun','Welcome to Demon School! Iruma-kun','https://image.tmdb.org/t/p/w500/gKz8wiKsbgefAkxjpBCmJPnnXJE.jpg',2019,'Anime,Comedy,Fantasy,Hindi Dub,Isekai,Muse India,School,Shounen','Fourteen-year-old Iruma Suzuki has just been abandoned and sold to a demon by his irresponsible parents! Surprisingly, the next thing he knows he’s living with the demon who has adopted him as his new grandson and has been transferred into a school in the Netherworld where his new demon grandfather works as the principal. Thus begins the cowardly Iruma-kun’s extraordinary school life among the otherworldly as he faces his true self, takes on challenges, and rises to become someone great.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('what-if','What If…?','https://image.tmdb.org/t/p/w500/lztz5XBMG1x6Y5ubz7CxfPFsAcW.jpg',2021,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi','FANDUBTaking inspiration from the comic books of the same name, each episode explores a pivotal moment from the Marvel Cinematic Universe and turns it on its head, leading the audience into uncharted territory.',18);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('why-raeliana-ended-up-at-the-dukes-mansion-hindi','Why Raeliana Ended Up at the Duke’s Mansion','https://image.tmdb.org/t/p/w500/gA9tCWV13QWIgDOdynah6FBmuxD.jpg',2023,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Mystery,Sci-Fi,Tamil,Telugu','Living inside a fairy tale may sound like a dream, but for this heroine, it’s more of a nightmare. After her mysterious death, Rinko is reborn as Raeliana—a loved and wealthy character in a novel. But she knows the ending: her murder at the hands of her fiancé. So, she hatches a plan to stay alive, one that involves a devilish duke and a phony engagement. Can she rewrite her story?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('wind-breaker-hindi','WIND BREAKER','https://image.tmdb.org/t/p/w500/f0CZzRXyqCc41NePDJSY23YQ2SS.jpg',2024,'Action,Anime,Crunchyroll,Delinquents,Hindi Dub,School','Haruka Sakura wants nothing to do with weaklings—he’s only interested in the strongest of the strong. He’s just started at Furin High School, a school of degenerates known only for their brawling strength—strength they use to protect their town from anyone who wishes it ill. But Haruka’s not interested in being a hero or being part of any sort of team—he just wants to fight his way to the top!',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('wistoria-wand-and-sword','Wistoria: Wand and Sword','https://image.tmdb.org/t/p/w500/hM00JrQlrfI0wTSweYDMLUMcv8u.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,School,Shoujo,Tamil,Telugu','In a world where magic reigns, Will Serfort can’t cast a spell. Though hardworking, Will’s classmates think less of him for it. However, he has a secret strength: his sword. Can Will defy expectations with muscle over magic and blade over wand? Find out in this epic sword-and-sorcery adventure!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('wolverine-anime','Wolverine Anime','https://image.tmdb.org/t/p/w500/cXPQEgUEbDz5NERfBJxeKFqUGwa.jpg',2011,'Action,Anime,Hindi Dub,Martial Arts,Super Power','Wolverine is a mutant, possessing animal-keen senses, enhanced physical capabilities, three retracting bone claws on each hand and a healing factor that allows him to recover from virtually any wound, disease or toxin at a accelerated rate.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('yaiba-samurai-legend','YAIBA: Samurai Legend','https://image.tmdb.org/t/p/w500/cxD3FQP4hDU5hSABwdQCvGrrnz6.jpg',2025,'Action,Adventure,Anime,Anime Times,Comedy,Hindi Dub,Samurai,Shounen','Yaiba’s journey to becoming a true samurai takes him from his home in the forest to a bustling city full of rivals, friends and ancient powers.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('yu-gi-oh-duel-monsters','Yu-Gi-Oh! Duel Monsters','https://image.tmdb.org/t/p/w500/eQudswX8mdPZxEoLM6ax9PsORDi.jpg',2000,'Action,Adventure,Anime,Fantasy,Hindi Dub,Kids','Bullies often target someone frail and weak—someone exactly like Yûgi Muto. He treasures his Millennium Puzzle, an ancient Egyptian artifact that was brought into his grandfather’s game shop. Believing that solving the puzzle will grant him his wish, he completes the puzzle, unleashing a new personality within him, the soul of the “King of Games.” The new personality named Yami Yûgi is the exact opposite of Yûgi. Upon any injustice toward him, Yami Yûgi takes over Yûgi’s body and forces the opponent into a “Shadow Game”.Only 8 Episodes are available in Hindi',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zinba','Zinba','https://image.tmdb.org/t/p/w500/nM8KdyjBMd4Sw92v46n1qeHJsBr.jpg',2013,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Sci-Fi','The story of Kan, a boy who fights with the monsters known as Zinba.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvel-rising-initiation','Marvel Rising: Initiation','https://image.tmdb.org/t/p/w500/8z8Z7ZwFgatxp33fvxRKLyl2xd9.jpg',2018,'Action & Adventure,Animation,Cartoon,Hindi Dub','Gwen Stacy AKA Ghost-Spider, wrongly accused of a crime she didn’t commit, seeks to clear her name and deliver justice. Unfortunately, her dad is not only Captain of the NYPD, but spearheading the manhunt! To make matters worse, other young heroes—Ms. Marvel, Squirrel Girl, Quake and Patriot—are after Ghost Spider as well. But, as the chase to uncover the truth winds down, a darker threat looms along the horizon, and very soon, these heroes will need to put aside their differences and work together as a team.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvels-hulk-and-the-agents-of-s-m-a-s-h','Hulk and the Agents of S.M.A.S.H.','https://image.tmdb.org/t/p/w500/xxJbuRwU3ssxxrxrI38URtLkf6L.jpg',2013,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Marvel’s Hulk and the Agents of SMASHJoined by the Agents of S.M.A.S.H., a humorously dysfunctional group of teammates who double as family, Hulk tackles threats that are too enormous for any other heroes to handle.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvels-spider-man','Marvel’s Spider-Man','https://image.tmdb.org/t/p/w500/dKdcyyHUR5WTMnrbPdYN5y9xPVp.jpg',2017,'Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy','An insecure but courageous and intelligent teen named Peter Parker, a new student of Midtown High, is bitten by a radioactive spider and given powers. He becomes a hero named Spider-Man after the death of his uncle and he must adapt to this new way of life.',58);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('marvels-spidey-and-his-amazing-friends','Marvel’s Spidey and His Amazing Friends','https://image.tmdb.org/t/p/w500/etO5jDS5WgR4Y1lTyXhQcilJ6u2.jpg',2021,'Animation,Comedy,Hindi Dub,Kids','Follow Peter Parker, Gwen Stacy and Miles Morales and their adventures as the young heroes team up with Hulk, Ms. Marvel and Black Panther to defeat foes like Rhino, Doc Ock and Green Goblin and learn that teamwork is the best way to save the day.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('may-i-ask-for-one-final-thing','May I Ask for One Final Thing?','https://image.tmdb.org/t/p/w500/7WVc8kFsHDKYp2U3tZgv3n9BCoG.jpg',2025,'Action,Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Romance,Villainess','In the middle of a ball, Scarlet’s fiancé, Kyle, suddenly calls off their engagement. She’s falsely accused of being a bully and people unfairly call her a “Villainess.” The aristocrats and noble families all denounce her. For years, she had to put up with his abuse and idiocy, but she can’t take anymore of it! At her wit’s end, she asks for one last favor; to give him a good fist in the face. So begins Scarlet’s story of revenge against Kyle and his cronies! A fantasy about an elegant yet rebellious fighter, who doesn’t let anyone take advantage of her!!',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('maya-and-the-three','Maya and the Three','https://image.tmdb.org/t/p/w500/zUBixNeHU0cbSUH7JMktl9OMEMV.jpg',2021,'Action & Adventure,Animation,Cartoon,Comedy,Family,Hindi Dub','A spirited princess with the heart of a warrior embarks on a mission to fulfill an ancient prophecy and save humanity from the wrath of vengeful gods.',9);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mech-x4','MECH-X4','https://image.tmdb.org/t/p/w500/acHYpTfMVKHxpI91Y6qjR4w75VC.jpg',2016,'Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy','Ryan Walker mysteriously awakens MECH-X4, a giant robot built to defend Bay City against impending doom. When monsters begin to descend, Ryan recruits his two best friends and his brother to help pilot the robot that is their only hope of saving their town from mass destruction.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('megas-xlr','Megas XLR','https://image.tmdb.org/t/p/w500/d4Mc687WE8wFAk5nlmJJh4qNuIO.jpg',2004,'Action,Cartoon,Comedy,Hindi Dub,Sci-Fi','Megas XLR is a series about an overweight couch potato named Coop who stumbles across a giant robot in a junkyard. He soon discovers that the robot was sent from the future when a woman named Kiva returns to the past to claim what is rightfully hers, though Coop made so many modification to the machine so he’s the only one who can fully operate it. Things also heat up when Coop learns that an alien race called the Glorft are also after his MEGAS robot, so he teams up with Kiva and his best friend Jamie to fight them off, though mostly so he can keep his new toy.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mf-ghost','MF GHOST','https://image.tmdb.org/t/p/w500/63cDEEjJw1x7RXPi3DxKdQ2Q7oK.jpg',2023,'Anime,Drama,Hindi Dub,Racing,Seinen','Japan adopts self-driving electric automobiles and renders most gas engines obsolete by 202X. The fastest cars find new life in the MFG, a racing circuit held on Japanese motorways. Drivers from around the world race for a shot at the title. Kanata Rivington returns from Britain to Japan for the MFG—and to find his father. Can he win the title and find answers? Buckle up and push it to the limit!',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mickey-mouse-clubhouse','Mickey Mouse Clubhouse','https://image.tmdb.org/t/p/w500/gHtEhlAZHxMawOiPq7JoKwkmETQ.jpg',2006,'Animation,Family,Hindi Dub,Kids,Tamil,Telugu','Mickey and his friends Minnie, Donald, Pluto, Daisy, Goofy, Pete, Clarabelle and more go on fun and educational adventures.',127);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mickey-mouse','Mickey Mouse','https://image.tmdb.org/t/p/w500/aAJ5T2Ab28vbbP9s6wWqdtK3arQ.jpg',2013,'Animation,Cartoon,Hindi Dub,Kids,Tamil,Telugu','In this series of cartoon shorts, Mickey Mouse finds himself in silly situations all around the world! From New York to Paris to Tokyo, Mickey experiences new adventures with his friends!',19);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mighty-cat-masked-niyander','Mighty Cat Masked Niyander','https://animedekho.app/wp-content/uploads/2023/03/Mighty-Cat-Masked-Niyander.webp',2000,'Anime,Family,Hindi Dub,Kids,Tamil,Telugu','Mighty Cat Masked Niyander is a 2000 children’s superhero anime series produced by Sunrise, loosely based on children’s book of the same name by author Takashi Yanase. It is directed by Tsutomu Shibayama and written by Mitsuki Nakamura.',138);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('milo-murphys-law','Milo Murphy’s Law','https://image.tmdb.org/t/p/w500/cUoMoeOm2ALLtPrbP4WwEzj4lO3.jpg',2016,'Animation,Cartoon,Comedy,Family,Hindi Dub','Milo Murphy is the personification of Murphy’s Law where anything that can go wrong will go wrong. Suffering from Extreme Hereditary Murphy’s Law condition (EHML), Milo always looks to make the best of the cards he’s been dealt and his endless optimism and enthusiasm can turn any catastrophe into a wild adventure. Together, he and his friends will learn that it’s all about a positive attitude and not to sweat the big stuff… and it’s all big stuff.',41);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('more-than-a-married-couple-but-not-lovers','More Than a Married Couple, But Not Lovers','https://image.tmdb.org/t/p/w500/hGX7VLj1LbjnpWoLTjbhFG5nzKD.jpg',2022,'Anime,Crunchyroll,Hindi Dub,Love Polygon,Romance,Samurai,Seinen','The story centers on third-year high school student Jiro Yakuin, who gets saddled with his gyaru classmate Akari Watanabe for the class’s “marriage training” project about practicing to be a married couple. Jiro is the complete opposite of Akari, but the two know that if they do well they will be able to switch partners to end up with their respective crushes, and so they force themselves to act like the perfect married couple.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-dad-the-bounty-hunter','My Dad the Bounty Hunter','https://image.tmdb.org/t/p/w500/cWSPHOTFFf5hs77gamKeLDhxNvm.jpg',2023,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub','An intergalactic bounty hunter takes dad duty to new extremes when his two kids accidentally hitch a ride with him to outer space and crash his mission.',19);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-one-hit-kill-sister','My One-Hit Kill Sister','https://image.tmdb.org/t/p/w500/hQEgYVrTUxV0yXqLxdwdXIaofGt.jpg',2023,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi','Asahi, a boy who loves video games is killed in a traffic accident and ends up in another world. He tries to enjoy the otherworldly adventuring life he’s always dreamed of, but his stats are on the level of an NPC’s. He is in big trouble and is being chased by a monster when he hears, “Fear not, little brother!” and the monster is killed in one hit by Asahi’s older sister, Maya, who followed Asahi to this world. So Maya has acquired some seriously OP skills, but she takes her adoration of her younger brother to extremes. Thus begins their story about an overpowered older sister with a brother complex and a younger brother with the weakest of stats in another world.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-tiny-senpai','My Tiny Senpai','https://image.tmdb.org/t/p/w500/7zSPXGCvXjkVCR7797UbRDPfV2B.jpg',2023,'Adult Cast,Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Tamil,Telugu','When Shinozaki started his new job, he didn’t expect his superior to be so…cute!? He struggled to learn the ropes until Katase, his tiny and kind senpai, took him under her wing. But as they grow closer, he hopes her attention might mean something more.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('oggy-and-the-cockroaches-next-generation','Oggy and the Cockroaches: Next Generation','https://image.tmdb.org/t/p/w500/6f6v4pU4xTex8nfSpR8qZIF3k2f.jpg',2022,'Animation,Cartoon,Comedy,Hindi Dub,Kids','Oggy is welcoming a guest for vacation: Piya , a 7 year old elephant, the daughter of his Indian friends. Tender hearted, happy go lucky, and full of energy, the elephant will completely derail Oggy’s daily grind, and the blue cat will learn how to be a surrogate parent. It’s a dream come true for the roaches, who see Piya as a new way to make Oggy’s life miserable.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('once-upon-a-witchs-death','Once Upon a Witch’s Death','https://image.tmdb.org/t/p/w500/5Gr2mDFSGHhiEYrNfP6vbYtuNrT.jpg',2025,'Adventure,Anime,Crunchyroll,Drama,Fantasy,Hindi Dub','Meg Raspberry is just an apprentice witch celebrating her 17th birthday. That is, until Faust, her magic teacher and Perennial Witch of the Seven Sages, suddenly reveals she is going to die. To stop the Death Sentence curse, Meg must create the Seed of Life using tears of joy from 1,000 people. Join Meg on her travels as she collects the happy tears from everyone she meets to gain eternal life!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('one-punch-man','One Punch Man','https://image.tmdb.org/t/p/w500/dT10AxJIXVvRwFAew4tt2RhzJrD.jpg',2015,'Action,Adult Cast,Anime,Comedy,Hindi Dub,Parody,Seinen,Super Power,Tamil,Telugu','Saitama is a hero who only became a hero for fun. After three years of “special” training, though, he’s become so strong that he’s practically invincible. In fact, he’s too strong — even his mightiest opponents are taken out with a single punch, and it turns out that being devastatingly powerful is actually kind of a bore. With his passion for being a hero lost along with his hair, yet still faced with new enemies every day, how much longer can he keep it going?',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-horizons-the-series','Pokémon Season 26 Horizons: The Series','https://image.tmdb.org/t/p/w500/amemXW39lMbNBJFRMJ5W7q9mLP2.jpg',2023,'Action,Adventure,Anime,Comedy,Fantasy,Hindi Dub,Kids,Tamil,Telugu','Pokémon Horizons: The SeriesFollow Liko and Roy as they unravel the mysteries that surround them and encounter Friede, Captain Pikachu, Amethio, and others during their exciting adventures!',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-1-indigo-league','Pokémon Season 1 Indigo League','https://image.tmdb.org/t/p/w500/eGQ5eJMQR20TZsWMFxiXPKR1M2c.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',82);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-14-black-white','Pokémon Season 14 Black & White','https://image.tmdb.org/t/p/w500/kmfsJG0y9q6y27whVTs8PZWKq4L.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',48);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-6-advanced','Pokémon Season 6 Advanced','https://image.tmdb.org/t/p/w500/1dNnm3ghzcnxM9M80NnBnDGmnZI.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-9-battle-frontier','Pokémon Season 9 Battle Frontier','https://image.tmdb.org/t/p/w500/6BDDH5EHiAHjfVGhi8FQc2xuDG0.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',47);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-xyz','Pokémon Season 19 XYZ','https://image.tmdb.org/t/p/w500/cx06NhIZHD3naq3bpXpqKZx2J1A.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',48);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('possibly-the-greatest-alchemist-of-all-time','Possibly the Greatest Alchemist of All Time','https://image.tmdb.org/t/p/w500/4TyTS9O7ECH3mXpazQ6GpJXCqNm.jpg',2025,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Tamil,Telugu','Iruma Takumi finds himself caught up in a hero summoning, even though he’s not a hero. Summoned by mistake to Mildgard, a fantasy world of swords and magic, Takumi is given a chance to start over. Though he dreams of a peaceful life, the goddess Nolyn grants him “alchemy,” an ultra-powerful skill that allows him to create anything from holy swords to flying ships. His reluctant adventure begins!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-ranger-megaforce','Power Ranger Season 20 Megaforce','https://image.tmdb.org/t/p/w500/fZpbXVXXZrS68n8eVmJi48v9eyp.jpg',2013,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','When Earth is under attack by the evil Warstar aliens, the teenage Power Rangers take it upon themselves to fight them and save the planet.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-beast-morphers','Power Rangers Season 26 Beast Morphers','https://image.tmdb.org/t/p/w500/pw9Za2j51TFbkQr23IuWfpKCXrk.jpg',2019,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','A secret agency creates a new team of Power Rangers by combining a recently identified substance with animal DNA. Soon, the Rangers are tasked with defeating a computer virus from another dimension.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-dino-fury','Power Rangers Season 28 Dino Fury','https://image.tmdb.org/t/p/w500/lkMsbqWzUieRqko5qGAuHeSsFKB.jpg',2021,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','When an army of powerful alien beings is unleashed on Earth threatening life as we know it, a brand-new team of Power Rangers, fueled by the prehistoric power of the dinosaurs, are recruited to deal with the threat.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-time-force','Power Rangers Season 9 Time Force','https://image.tmdb.org/t/p/w500/UCgePnFVfl6Zo2RYV0cAIOW9TV.jpg',2001,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Power Rangers Time Force is a television series and the ninth season of the Power Rangers franchise, based on the 24th Super Sentai series Mirai Sentai Timeranger, running for 40 half-hour episodes from February to November 2001. It was the last season to be distributed by Saban Entertainment',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('quality-assurance-in-another-world','Quality Assurance in Another World','https://image.tmdb.org/t/p/w500/toNVPhr8BpCbJ4LUGdiOGJpcy80.jpg',2024,'Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu,Video Game','When a dragon attacks a peaceful village, it’s not the beast that perplexes resident Nikola, but the man who comes to their aid. Haga, member of a secret royal team of investigators, intrigues her with his eccentric ways. It may be due to the fact he’s a real-life QA debugger and this world is a VR game! With Haga by her side, Nikola’s inspired to venture out and learn her world’s true nature.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ranking-of-kings','Ranking of Kings','https://image.tmdb.org/t/p/w500/pU3PK0yG5cMWNwvkJcEljDndGrd.jpg',2021,'Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu','Ousama RankingUnable to hear, speak, or wield a sword, Prince Bojji doesn’t seem like a typical heir to the throne—and his kingdom agrees. But his fateful encounter with Kage, a shadow on the ground, gives him his first true friend. The two set off on a grand adventure and, together, form a bond that can overcome any obstacle…even being king.',23);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('rapunzels-tangled-adventure','Rapunzel’s Tangled Adventure','https://image.tmdb.org/t/p/w500/s12Z2uGrvjj5sA7LsBStTtfTYjC.jpg',2017,'Animation,Kids','Set between “Tangled” and “Tangled Ever After,” this animated adventure/comedy series unfolds as Rapunzel acquaints herself with her parents, her kingdom and the people of Corona.',28);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('reborn-to-master-the-blade-from-hero-king-to-extraordinary-squire-_','Reborn to Master the Blade: From Hero-King to Extraordinary Squire ♀','https://image.tmdb.org/t/p/w500/zrnUnV0PFWnJ1G6wDvzkQL2HL9d.jpg',2023,'Action,Anime,Fantasy,Hindi Dub,Reincarnation','After living a life devoted to serving his country and people, Inglis’ one wish to be free of a king’s burden and to train was actually heard, but as a beautiful girl! Reborn in the far future as a daughter to renowned knights, Inglis can now focus on mastering the martial arts. A wish has been granted, and Inglis will be on the front lines fulfilling the dream of becoming the strongest knight.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('remonster','Re:Monster','https://image.tmdb.org/t/p/w500/wD8w0K3ZvZMwbukdeC4NJVz5izR.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','Re MonsterRemonsterAfter meeting an untimely death, Tomokui Kanata is reincarnated as a lowly goblin, but he’s worked up a monstrous appetite. Thanks to his new ability that allows him to grow stronger the more he feeds, his feeble status quickly changes, and he rises to become the goblin leader. With a mix of his past memories, new body, and strong stomach, he’s taking a bite out of this new fantastical world!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('rent-a-girlfriend','Rent-a-Girlfriend','https://image.tmdb.org/t/p/w500/lHt3j91jV7Kh6MuRJ4w8KmK3Xav.jpg',2020,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Shounen','Rent a GirlfriendKinoshita Kazuya is a 20-year-old failure of a college student. He managed to kiss his girlfriend once, but was dumped after a month. Completely spiteful, Kazuya uses a certain method to date a girl. He goes to their meeting place and a beautiful girl brushing her long, black hair behind her ear was there, smiling at him. Her name was Mizuhara Chizuru. Something real is born after just a single rental! A reckless rom-com filled with love and excitement is about to begin!',48);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ronja-the-robbers-daughter','Ronja the Robber’s Daughter','https://image.tmdb.org/t/p/w500/pTnFZlLettuek3T9nSDQv1MAfjL.jpg',2014,'Adventure,Anime,Comedy,Family,Hindi Dub,Malayalam,Tamil,Telugu','Ronja is the only daughter of Mattis, a bandit leader who lives in a castle in the middle of a large forest. When Ronja grows old enough, she ventures into the forest to interact the strange and magical creatures that live there. She learns to live in the forest through her own strength, with the occasional rescue from her parents. Ronja’s life begins to change, however, when she happens upon a boy her own age named Birk.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sabrina-the-animated-series','Sabrina: The Animated Series','https://image.tmdb.org/t/p/w500/qWO7Abwft8GyHBtGx96AFRPUpFZ.jpg',1999,'Animation,Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy','Sabrina: The Animated Series is an American animated television series based on the Archie Comics character Sabrina, the Teenage Witch. It was produced by Savage Studios Ltd. and Hartbreak Films in association with DIC Entertainment, which was owned by Disney at the time. The cartoon series is a spin-off of the popular live action series that ran on ABC. Later, a movie, Sabrina: Friends Forever, and a spin-off series, Sabrina’s Secret Life, were produced by DiC, this time without the ownership of Disney. Reruns currently air on the “This Is for Kids” block on the TV channel This.',5);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('scooby-doo-and-scrappy-doo','Scooby-Doo and Scrappy-Doo','https://image.tmdb.org/t/p/w500/ctxdYzdqSlrfKrqEo3bLSrrMLSP.jpg',1979,'Animation,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery','The original thirty-minute version of Scooby-Doo and Scrappy-Doo constitutes the fourth incarnation of the Hanna-Barbera Saturday morning cartoon Scooby-Doo. It premiered on September 22, 1979 and ran for one season on ABC as a half-hour program. A total of sixteen episodes were produced. It was the last Hanna-Barbera cartoon series to use the studio’s laugh track. Cartoon Network’s classic channel Boomerang reruns the series.',55);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('scott-pilgrim-takes-off','Scott Pilgrim Takes Off','https://image.tmdb.org/t/p/w500/nHROk2C6bv8LqtvyYd0tCMURbxC.jpg',2023,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub','Scott Pilgrim meets the girl of his dreams, Ramona Flowers, only to find out her seven evil exes stand in the way of their love.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('scum-of-the-brave','Scum of the Brave','https://image.tmdb.org/t/p/w440_and_h660_face/kSJv65fW98dUqRD5f0ahLLYoZQN.jpg',2026,'Action,Anime,Anime Times,Comedy,Crime,Hindi Dub,Super Power','In the mid-21st century, Tokyo’s mafia can turn into ether-enhanced Demon Lords, and Braves hunt them down. Yashiro, the Grim Reaper, reluctantly takes a new apprentice named Aki Jogamine, a high school girl training to become a Brave. He soon finds himself dragged into one troublesome case after another. The supernatural story of a scumbag master and his self-proclaimed apprentice begins!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sgt-frog','Sgt. Frog','https://image.tmdb.org/t/p/w500/9cgmkJnUVawW1o6jmmy8kqIl5IJ.jpg',2004,'Animation,Comedy,Sci-Fi & Fantasy','Alien frogs come to take over the planet & get into all kinds of trouble while living under the roof of a small family.',51);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('she-professed-herself-pupil-of-the-wise-man','She Professed Herself Pupil of the Wise Man','https://image.tmdb.org/t/p/w500/eDSsaZZVQD0rjrMazEIWrYUJHPk.jpg',2022,'Adventure,Crunchyroll,Fantasy,Hindi Dub,Isekai','Sakamori Kagami was one of the top players in the VRMMO Ark Earth Online as Danblf, a veteran summoner with the gravitas to match his elite status. When he falls asleep playing one day, he’s transported to a world where the game is reality—but instead of his all-powerful avatar, he’s stuck in the body of a cute young girl! He can’t let anyone know that this little cutie is really Danblf, so he takes the name “Mira” and claims to be Danblf’s disciple. If this gets out, he’ll never live it down!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('shoot-goal-to-the-future','Shoot! Goal to the Future','https://image.tmdb.org/t/p/w500/3jMImKHLU9zoB2K2hDEe6fu1Emn.jpg',2022,'Anime,Hindi Dub,Shounen,Sports,Tamil,Telugu','Atsushi Kamiya is a former captain at Kakegawa High School and the world-renowned “courageous captain” for a famous Italian soccer team. Hideto Tsuji, a student at Kakegawa High School seems uninterested in the now-weakened soccer team. Their meeting is the start of a new legend.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('smoking-behind-the-supermarket-with-you','Smoking Behind the Supermarket with You','https://image.tmdb.org/t/p/w500/gHVfuuOXPVs0ltFbOZQjxpXtSSH.jpg',2026,'Animation,Anime,Comedy,Crunchyroll,Drama,Hindi Dub','Sasaki is an overworked salaryman drifting through the corporate grind, sustained by cigarettes and the cheerful service and smile of Yamada, the clerk at his favorite supermarket. But one night after a grueling shift, he arrives late to find Yamada nowhere to be seen. With nowhere left to smoke, his spirits sink—until a pierced young woman calls out to him: “You can smoke here.”',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('snowball-earth','SNOWBALL EARTH','https://image.tmdb.org/t/p/w500/rLin4VCC1QK7MDmeaSBZqw7SWRu.jpg',2026,'Adventure,Anime,Crunchyroll,Hindi Dub,Mecha,Sci-Fi,Seinen','Yukio was destroyed in battle and Tetsuo survived in an escape pod. After eight years in cold sleep, the escape pod finally lands back on Earth. But when Tetsuo emerges he finds a world in ruins, entirely frozen beneath a blanket of ice and snow—snowball Earth! What happened to humanity, how did the planet freeze over, and will Tetsuo be able to keep his last promise to Yukio?',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('star-wars-rebels','Star Wars Rebels','https://image.tmdb.org/t/p/w500/iR2713W3mjlwJXvc5oJfyGbUQsY.jpg',2014,'Action & Adventure,Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Set between the events of Star Wars: Episodes III and IV, the story unfolds during a dark time when the evil Galactic Empire is tightening its grip of power on the galaxy. Imperial forces have occupied a remote planet and are ruining the lives of its people. The motley but clever crew of the starship Ghost — cowboy Jedi Kanan, ace pilot Hera, street-smart teenager Ezra, the “muscle” Zeb, warrior firebrand Sabine, and cantankerous old astromech droid Chopper — is among a select few who are brave enough to stand against the Empire. Together, they will face threatening new villains, encounter colorful adversaries, embark on thrilling adventures, and become heroes with the power to ignite a rebellion.',74);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('stillwater','Stillwater','https://image.tmdb.org/t/p/w500/t6tcFn0LiyKRqR76XwNfErK81cw.jpg',2020,'Animation,Cartoon,Hindi Dub,Kids','Siblings Karl, Addy and Michael have a very special next-door neighbor: a wise panda named Stillwater. His friendship and stories give them new perspectives on the world, themselves, and each other.',11);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('steven-universe','Steven Universe','https://image.tmdb.org/t/p/w500/gKUuGaeZ9qiJ9Spoq0LrANQSN5x.jpg',2013,'Action & Adventure,Animation,Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','A young boy takes his mother’s place in a group of gemstone-based beings, and must learn to control his powers.',76);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('suicide-squad-isekai','Suicide Squad Isekai','https://image.tmdb.org/t/p/w500/jV0Ii5rsBn3B1MBkztlyMZ4Tg0W.jpg',2024,'Action,Adult Cast,Anime,Fantasy,Hindi Dub,Isekai','In the crime-ridden city of Gotham, Amanda Waller, the head of A.R.G.U.S., assembles a group of notorious criminals—Harley Quinn, Deadshot, Peacemaker, Clayface and King Shark—for a mission into an otherworldly realm that’s connected to this world through a gate. It’s a realm of swords and magic where orcs rampage and dragons rule the skies. Can Harley Quinn and her crew conquer this perilous realm?',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('supa-strikas','Supa Strikas','https://image.tmdb.org/t/p/w500/nx2OyMPYJZlgvK29mjovqy4WYnJ.jpg',2009,'Animation,Cartoon,Hindi Dub','With dreams of becoming Super League champions, a talented striker named Shakes and his football team take on rivals while going on global adventures.',91);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('supah-ninjas','Supah Ninjas','https://image.tmdb.org/t/p/w500/8flRUKqsUOpYFhEmuUS0umgzMkX.jpg',2011,'Action & Adventure,Hindi Dub,Live-Action','Supah Ninjas is an American action-comedy superhero series, created by Leo Chu and Eric Garcia. The series premiered as a special preview on Nickelodeon on January 17, 2011 in the United States and started airing regularly on April 16, 2011. On March 15, 2012, it was the announced that the series was renewed for a second season. The second season premiered on February 9, 2013, after a new episode of Marvin Marvin. It was announced on May 7, 2013 that the show will not be renewed for a third season.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('super-giant-robot-brothers','Super Giant Robot Brothers!','https://image.tmdb.org/t/p/w500/1ysuYGkRtZgaP4mL9nbRmCU3vMd.jpg',2022,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub','Two squabbling robot brothers battle bloodthirsty kaijus, supernatural disasters and mundane personal issues as they adapt to the trials of growing up.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('super-monsters','Super Monsters','https://image.tmdb.org/t/p/w500/uB0Nxqva9znFojlLBgBJtEx6wIB.jpg',2017,'Animation,Hindi Dub,Kids','Preschool kids whose parents are the world’s most famous monsters try to master their special powers while preparing for kindergarten.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('superbook','Superbook','https://image.tmdb.org/t/p/w500/4gxPU54vvA5ZGaICzwDXAQY5SvR.jpg',2011,'Animation,Cartoon,Family,Hindi Dub,Kids','Chris Quantum is your typical Middle School student — except if you take into account one of his best friends is a robot named Gizmo. Add his best friend Joy Pepper into the mix and you have a recipe for adventure. The adventures begin for this trio when a mysterious device appears and takes them on journeys throughout the Bible. Travel back in time and get ready for the journey of a lifetime!',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sword-art-online','Sword Art Online','https://image.tmdb.org/t/p/w500/mK9zGGk90VmHLOnK79sqlGFjZjW.jpg',2012,'Action,Adventure,Anime,Fantasy,Romance,Video Game','In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game’s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now…',49);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('terror-in-resonance','Terror in Resonance','https://image.tmdb.org/t/p/w500/wc1PaImHVXIESClpEDwNI1mlYuC.jpg',2014,'Anime,Anime Times,Detective,Drama,Hindi Dub,Mystery,Psychological,Suspense','In an alternate version of the present, Tokyo has been decimated by a shocking terrorist attack, and the only hint to the identity of the culprit is a bizarre video uploaded to the internet. The police, baffled by this cryptic clue, are powerless to stop the paranoia spreading across the population. While the world searches for a criminal mastermind to blame for this tragedy, two mysterious children – children who shouldn’t even exist – masterfully carry out their heinous plan. Cursed to walk through this world with the names Nine and Twelve, the two combine to form “Sphinx,” a clandestine entity determine to wake the people from their slumber – and pull the trigger on this world.',11);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-ancient-magus-bride-hindi','The Ancient Magus’ Bride','https://image.tmdb.org/t/p/w500/vUm0WIGGgAnXYOSBeB36FKDpBjI.jpg',2017,'Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Mythology,Romance,Tamil,Telugu','Fifteen-year-old Chise has nothing and no one to live for. But that changes when she becomes the apprentice and future wife of inhuman mage, Elias.',54);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-angel-next-door-spoils-me-rotten','The Angel Next Door Spoils Me Rotten','https://image.tmdb.org/t/p/w260_and_h390_face/bTUV7GOz3eAfvpD5VNrbN9QyWuV.jpg',2023,'Anime,Crunchyroll,Hindi Dub,Romance,School','Amane lives alone in an apartment, and the most beautiful girl in school, Mahiru, lives just next door. They’ve almost never spoken—until the day he sees her in distress on a rainy day and lends her his umbrella. To return the favour, she offers him help around the house, and a relationship slowly begins to blossom as the distance between them closes…',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-bad-guys-breaking-in','The Bad Guys: Breaking In','https://image.tmdb.org/t/p/w500/12ybD4BvgSpmhSjknFPvf1Nu7CC.jpg',2025,'Animation,Cartoon,Hindi Dub','How did the Bad Guys break into the bad guy business in the first place? Find out in this hilarious prequel series set before the hit films.',19);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-deep','The Deep','https://image.tmdb.org/t/p/w500/3aoRvpHjuRmn76P2AVXZIBDoCdg.jpg',2015,'Action & Adventure,Animation,Family,Kids','The adventures of the Nekton family, a family of daring underwater explorers who live aboard a state-of-the-art submarine, The Aronnax, and explore uncharted areas of the earth’s oceans to unravel the mysteries of the deep.',18);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-drops-of-god','The Drops of God','https://image.tmdb.org/t/p/original/e0HIphKTbM0YjWCASdCsjYtESHG.jpg',2026,'Animation,Anime,Crunchyroll,Drama,Hindi Dub,Mystery,Tamil,Telugu','When world-renowned wine critic Toyotaka Kanzaki passes away, he leaves behind an enviable collection. The will promises his estate to whoever correctly guesses the brand and year of the 12 greatest wines he selected, and the legendary wine that stands atop them all, “Drops of God.” The challengers are Toyotaka’s son, Shizuku Kanzaki, and a young critic, Issei Tomine, who was adopted by Toyotaka.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-elusive-samurai','The Elusive Samurai','https://image.tmdb.org/t/p/original/wVJjyUbns2USXo1bolF2vGanvf6.jpg',2024,'Adventure,Anime,Comedy,Crunchyroll,Hindi Dub,Historical,Samurai,Shounen','Set between the Kamakura and Muromachi periods, during the Kenmu Restoration, the story follows the tale of Hojo Tokiyuki, a boy on the run after his family is overthrown by Ashikaga Takauji. With his only allies being a shady priest and his followers, the young lord must seek revenge and regain his glory, with his only weapon: a superhuman ability to flee and hide.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-first-order','The First Order','https://image.tmdb.org/t/p/original/LM1wtCmWKg0NoifRvBCQ9nJBMf.jpg',2023,'Action & Adventure,Animation,Anime,Drama,Hindi Dub,MX Player','The world where humanity no longer dominates due to experiencing a nuclear winter. In this setting, species have mutated, and survival resources are scarce. Faced with an unpredictable future and environment, crises occur frequently. To protect themselves, humans have built barriers, but many people still live outside these fortifications, relying on hunting in the wilderness for survival.(Cgpt)',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-frontier-lord-begins-with-zero-subjects','The Frontier Lord Begins with Zero Subjects','https://image.tmdb.org/t/p/original/vHTHQZy3JhgoVMkbXlOot5gOUzZ.jpg',2026,'Action & Adventure,Animation,Anime,Anime Times,Comedy,Hindi Dub,Sci-Fi & Fantasy','The war is over, and hero Dias is finally rewarded with land of his own—only to discover it’s a barren frontier with no people, no villages, and no sign of civilization. With nothing but endless grassland ahead of him, Dias sets out to build a domain from the ground up. But after meeting Alna, a mysterious girl with a blue horn, his lonely frontier is about to spring to life.',3);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-iceblade-sorcerer-shall-rule-the-world','The Iceblade Sorcerer Shall Rule the World','https://image.tmdb.org/t/p/w500/xBlJYF8ROyYppm6RbZ1Ga8nERWs.jpg',2023,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,School','The Arnold Academy of Magic is a school for the elite…and Ray White is just your ordinary guy. In fact, he doesn’t seem particularly skilled with magic at all, and is a bit of a klutz. Which is why he has nothing to do with the rumor that one of the great magicians, the Iceblade Sorcerer, is a member of the incoming class…right?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-jungle-book-the-adventures-of-mowgli','The Jungle Book: The Adventures of Mowgli','https://image.tmdb.org/t/p/w500/zXKAeQfnzvUdcCtN4gsyux4xvj9.jpg',1989,'Action,Adventure,Cartoon,Hindi Dub,Kids','Jungle Book Shōnen Mowgli is an anime adaptation of Rudyard Kipling’s original collection of stories, The Jungle Book. It aired in 1989, and consists of a total of 52 episodes.The series, a compromise between the original Mowgli stories and the Walt Disney version, received international acclaim and was aired in different countries around the world.',53);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-jungle-bunch-to-the-rescue','The Jungle Bunch: To the Rescue','https://image.tmdb.org/t/p/w500/pWdTyH2q4SCyCuV6VLhXKo13MX6.jpg',2013,'Animation,Kids','Maurice, a penguin raised in the jungle who thinks he is a tiger, leads a group of misfit animals on missions to rescue their fellow animals, no matter what their trouble is.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-lion-guard','The Lion Guard','https://image.tmdb.org/t/p/w500/AtDL8ZrOZxW1jakT2R3LcMdLvQD.jpg',2016,'Animation,Cartoon,Hindi Dub,Kids,Tamil,Telugu','Simba’s son, Kion, assembles a group of animals to protect the Pride Lands, known as the Lion Guard.',58);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-little-mermaid','The Little Mermaid','https://image.tmdb.org/t/p/w500/behIhyn2QMpudx3h82RZbGGRtKP.jpg',1992,'Animation,Cartoon,Family,Hindi Dub,Kids','Disney’s The Little Mermaid is an American animated television series produced by Walt Disney Television Animation based on the 1989 Disney film of the same name. It features the adventures of Ariel as a mermaid prior to the events of the film. This series is the first Disney television series to be spun off from a major animated film. Some of the voice actors of the film reprise their roles in the series, among them Jodi Benson as Ariel, Samuel E. Wright as Sebastian, Kenneth Mars as King Triton, and Pat Carroll as Ursula.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-looney-tunes-show','The Looney Tunes Show','https://image.tmdb.org/t/p/w500/zZuQ4RHiy52r6EyXOT4AwmBroZQ.jpg',2011,'Cartoon,Comedy,Family,Hindi Dub,Tamil,Telugu','Bugs Bunny, Daffy Duck and the rest of the “Looney Tunes” characters are back with more adventures for a new generation of viewers. The animated series features roommates Bugs and Daffy moving out of the woods and into the suburbs, interacting with their neighbors, who happen to be other “Looney Tunes” favorites — including Sylvester, Tweety, Porky Pig and Foghorn Leghorn.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-maid-i-hired-recently-is-mysterious','The Maid I Hired Recently Is Mysterious','https://image.tmdb.org/t/p/w500/iGv5HouvyQvWF1SCEzzMtej9zhP.jpg',2022,'Anime,Comedy,Crunchyroll,Hindi Dub','There’s something really strange about the maid I just hired! No normal person could be so beautiful, or cook such amazingly delicious food, or know exactly what I want before I even ask. She must be using magic—right, a spell is the only thing that can explain why my chest feels so tight whenever I look at her. I swear, I’m going to get to the bottom of what makes this maid so…mysterious!',11);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-new-adventures-of-peter-pan','The New Adventures of Peter Pan','https://image.tmdb.org/t/p/w500/o1ZhgwAHX2OqdG3XyF7GryKKTUp.jpg',2013,'Adventure,Animation,Cartoon,Hindi Dub,Kids','Featuring first-in-class animation, comedy and adventure, The New Adventures of Peter Pan transports Peter Pan, Wendy, John, Michael and the Lost Boys and Girls to wondrous places that often turn out to be far more dangerous than anyone would have ever expected! In order to keep Neverland safe from Captain Hook, Peter and his friends fly head on into adventure to protect their right to never grow up.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-ramparts-of-ice','The Ramparts of Ice','https://image.tmdb.org/t/p/original/rke9UC2QrogvxiQD9TGpbvqDosi.jpg',2026,'Anime,Comedy,Drama,Hindi Dub,Netflix,Romance,School','Weighed down by memories she can’t shake, high schooler Koyuki Hikawa keeps everyone at arm’s length — until three schoolmates draw her out of her shell.',14);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-red-ranger-becomes-an-adventurer-in-another-world','The Red Ranger Becomes an Adventurer in Another World','https://image.tmdb.org/t/p/w500/6Mh3iaUrL4ZPvpmbCJKBICBEbNi.jpg',2025,'Action,Adventure,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Shounen','Togo Asagaki was the Red Ranger in a heroic Ranger squad. During their final battle against an evil organization, he gave his life to guarantee their triumph. But fate had other plans, and he found himself reborn in an entirely different world. Embracing his new role as an adventurer, he transforms into Kizuna Red and continues his pursuit of justice, helping those in need.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-suite-life-of-zack-cody','The Suite Life of Zack & Cody','https://image.tmdb.org/t/p/w500/vKOdc6fWHaSTsVjUALFm5S4Vup0.jpg',2005,'Comedy,Family,Hindi Dub,Kids','Meet Zack and Cody, 11 year-old identical twins and the newest residents of Boston’s swanky Tipton Hotel. Living in a suite with their mom Carey, the boys treat the Tipton like their own personal playground.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-warrior-princess-and-the-barbaric-king','The Warrior Princess and the Barbaric King','https://image.tmdb.org/t/p/w500/hO5fLLMqteEopcYy5r0gQB1pWl.jpg',2026,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Romance,Shounen,Tamil,Telugu','Serafina, the West’s fiercest knight, expected torture when captured by barbarians. Instead, she got a marriage proposal! Marrying her sworn enemy is a hard no! But after seeing her wedding captor’s culture and very pretty face, she may be tempted to swap her sword for a wedding veil. Get ready for the ultimate enemies-to-maybe-lovers arc.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-worlds-finest-assassin-gets-reincarnated-in-another-world-as-an-aristocrat','The World’s Finest Assassin Gets Reincarnated in Another World as an Aristocrat','https://image.tmdb.org/t/p/w500/2MqT2IspOAPm7c1dCMF78GHiXMT.jpg',2021,'Action,Anime,Drama,Fantasy,Hindi Dub,Isekai,Mystery,Reincarnation,Romance','The world’s number one assassin has been reincarnated as the eldest son of a family of aristocrat assassins. In exchange for being reincarnated in another world, a goddess has imposed upon him one condition. “Kill the Hero who is prophesied to destroy the world.” This was to be the mission in his new life. The synergistic effect of the vast knowledge and experience he gained that made all manner of assassinations possible in the modern world, and the secret techniques and magic of the fantasy world’s most powerful family of assassins turn him into the greatest assassin of all time.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('thomas-friends','Thomas & Friends','https://image.tmdb.org/t/p/w500/s8RtAklJqHo6iMtKz1FIVBm92R2.jpg',1984,'Animation,Hindi Dub,Kids','Thomas & Friends is a British children’s television series, which had its first broadcast on the ITV network on 4 September 1984. It is based on The Railway Series of books by the Reverend Wilbert Awdry and his son, Christopher Awdry. These books deal with the adventures of a group of anthropomorphised locomotives and road vehicles who live on the fictional Island of Sodor. The books were based on stories Wilbert told to entertain his son, Christopher during his recovery from measles. From Series one to four, many of the stories are based on events from Awdry’s personal experience.',60);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tobot','Tobot','https://image.tmdb.org/t/p/w500/r3yvmr33vWRfOGBoIed5hl3QnDa.jpg',2010,'Action & Adventure,Animation,Cartoon,Hindi Dub','',28);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('toilet-bound-hanako-kun','Toilet-Bound Hanako-kun','https://image.tmdb.org/t/p/w500/qp2XSpNzopObSPkSAi7sujAsdh3.jpg',2020,'Anime,Comedy,Crunchyroll,Hindi Dub,Mystery,Mythology,School,Shounen,Supernatural','The famous “Seven Wonders” that every school seems to have are a staple of Japanese urban legends. One of the most well-known of these tales is that of Hanako-san: the ghost of a young girl who haunts the school’s bathrooms.Kamome Academy has its own version of Hanako-san’s legend. Rumors claim that if one successfully manages to summon Hanako-san, she will grant her summoner any wish. Lured by the gossip, many people have tried to call upon her, yet every attempt has failed. However, when Nene Yashiro, a girl hoping for romantic fortune, dares to summon Hanako-san, she discovers that the rumored “girl” is actually a boy!After a series of unfortunate events involving Nene’s romantic desires, she is unwillingly entangled in the world of the supernatural, becoming Hanako-kun’s assistant. Soo',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tojima-wants-to-be-a-kamen-rider','Tojima Wants to Be a Kamen Rider','https://image.tmdb.org/t/p/w500/bD80ugDX7krshLcWxnqRYCOQPoo.jpg',2025,'Action,Adult Cast,Anime,Comedy,Drama,Hindi Dub,Mystery,Seinen,Super Power,Tamil,Telugu','Even after turning 40 years old, Tojima Tanzaburo still seriously wants to be a Kamen Rider. Just when it seems like his dream may never come true, he gets caught up in a series of infamous Shocker-inspired robberies… Shibata Yokusaru, the author of Air Master and 81 Diver, presents a story about adults who love Kamen Rider a little too much, and start playing pretend… for real!',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tokyo-24th-ward','Tokyo 24th Ward','https://image.tmdb.org/t/p/w500/3NYB8HfKALKQ4cHGx8Rx4Dhd0YE.jpg',2022,'Action,Anime,Crunchyroll,Hindi Dub,Mystery,Sci-Fi,Super Power','The Far Eastern Special Administrative Region, also known as the 24th Ward, is a man-made island. Shuta, Ran, and Koki were born and raised on the island. Their family backgrounds, preferences, and personalities are completely different, but they always stuck together. However, one incident changed their relationship forever. A year afterward, the three friends are reunited by chance at a memorial service held for the incident. All three of their phones suddenly ring simultaneously. Their friend, who is supposed to be dead, is calling and demands that they make a decision about the future.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tokyo-ghoul-crunchyroll-dub','Tokyo Ghoul (Crunchyroll Dub)','https://image.tmdb.org/t/p/w500/1m4RlC9BTCbyY549TOdVQ5NRPcR.jpg',2014,'Animation,Anime,Crunchyroll,Drama,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Ken Kaneki, a bookworm college student, meets Rize, a girl his own age with whom he shares many interests.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-rescue-bots','Transformers: Rescue Bots','https://image.tmdb.org/t/p/w500/rPxGxcPaKgnFvwMQU0XYnie7X2G.jpg',2012,'Action & Adventure,Animation,Hindi Dub,Kids,Sci-Fi & Fantasy','A team of specialized Autobots not quite ready for prime-time battles against the Decepticons is given a vital mission by Optimus Prime. The goal for the Bots is to learn about mankind and how to help others to find out what it really means to be a hero.',105);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-robots-in-disguise','Transformers: Robots In Disguise','https://image.tmdb.org/t/p/w500/aDjBBKEkveUvlBSrNGvmUjhe8OS.jpg',2015,'Cartoon,Hindi Dub,Kids,Tamil,Telugu','Years after the events of Predacons Rising, Bumblebee is summoned back to Earth to battle several of Cybertron’s most wanted Decepticons that escaped from a crashed prison ship and assembles a team of young Autobots that includes Sideswipe (a rebel “bad boy bot”), Strongarm (an Elite Guard cadet), Grimlock (a bombastic Dinobot), and Fixit (a hyperactive Mini-Con with faulty wiring).Season 1 is Not Available in Tamil-Telugu',71);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-war-for-cybertron-kingdom','Transformers: War for Cybertron: Kingdom','https://image.tmdb.org/t/p/w500/r2IouRpN9IXMyY8RX0YnJhkCirE.jpg',2021,'Action & Adventure,Animation,Sci-Fi & Fantasy','The frantic race to locate the Allspark first culminates on a strange planet as the future comes crashing through to the present day.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('trapped-in-a-dating-sim-the-world-of-otome-games-is-tough-for-mobs','Trapped in a Dating Sim: The World of Otome Games Is Tough for Mobs','https://image.tmdb.org/t/p/w500/zQInUzmgvT4MgysqSiW95YBkz1w.jpg',2022,'Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Mecha,Reincarnation,School,Tamil,Telugu','An ordinary office worker is reincarnated as Leon into a particularly punishing dating sim video game, where women reign supreme and only beautiful men have a seat at the table. But Leon has a secret weapon: he remembers everything from his past life, which includes a complete playthrough of the very game in which he is now trapped. Watch Leon spark a revolution to change this new world in order to fulfill his ultimate desire…of living a quiet, easy life in the countryside!',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('trigun-stampede','TRIGUN STAMPEDE','https://image.tmdb.org/t/p/w500/h1AvI9Mt6v15q5ynb3t9Dp4czBm.jpg',2023,'Action,Adult Cast,Adventure,Anime,Crunchyroll,Hindi Dub,Sci-Fi,Shounen,Tamil,Telugu','Vash the Stampede’s a joyful gunslinging pacifist, so why does he have a $$6 million bounty on his head? That’s what’s puzzling rookie reporter Meryl Stryfe and her jaded veteran partner when looking into the vigilante only to find someone who hates blood. But their investigation turns out to uncover something heinous—his evil twin brother, Millions Knives.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('valkyria-chronicles','Valkyria Chronicles','https://image.tmdb.org/t/p/w500/dhhUR4iDsM0ODztgzOOc8KoG0jP.jpg',2009,'Action,Adventure,Anime,Hindi Dub,War & Politics','When Imperial forces attack the small border town of Bruhl, Welkin Gunther, son of late General Belgen Gunther, is forced to fight for his life alongside Town Watch captain Alicia Melchiott. Along with Welkin’s adopted sister Isara, the three escape to Gallia’s capitol and subsequently join the country’s militia forces. As members of the newly-formed Squad 7, they must work to repel the invading Imperial forces and discover the true purpose of the invasion itself.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('vampire-dormitory','Vampire Dormitory','https://image.tmdb.org/t/p/w500/jmfNa7BQfI7DN1kFSx6jkBwYDGG.jpg',2024,'Anime,Crossdressing,Crunchyroll,Hindi Dub,Romance,Shoujo,Supernatural,Vampire','After Mito loses her parents and is fired from her job, she must fend for herself on the streets disguised as a boy. She comes across a stranger named Ruka and learns his dark secret—he’s a vampire! Ruka invites Mito, still in disguise, to live in an all-boys dorm. Mito exchanges her blood for a place to stay, but a budding romance and her true identity threaten all that hangs in the balance.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('vicky-vetaal','Vicky & Vetaal','https://image.tmdb.org/t/p/w500/6Qfx2HT0kSeutXmZe7Y8sThrJr9.jpg',2006,'Comedy,Fantasy,Hindi Dub,Live-Action,Sci-Fi','Vicky and Vetaal is a children’s comedy series produced by and aired on Disney Channel India. It was launched on October 7, 2006 as the first major original production of the network, and Disney’s first locally produced live action Hindi language series. The show was planned to be the first of a string of five local productions due to get released within a year’s span, and has since been followed by Dhoom Machaao Dhoom. The series stars Dev Kantawala as Vicky and Vishal Malhotra as Vetaal.The show is based on the Baital Pachisi collection of tales about the semi-legendary King Vikram, identified as Vikramāditya, and the Vetala, a huge vampire-like being.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zak-storm','Zak Storm','https://image.tmdb.org/t/p/w500/ugpb8OtFaS2JrLogXFJWvzJFhF8.jpg',2016,'Action,Adventure,Cartoon,Comedy,Family,Fantasy,Hindi Dub,Sci-Fi','The adventures of Zak Storm – a headstrong and adventurous kid swept into the Bermuda Triangle while trying to win a surfing competition. Once inside, Zak partners up with a magical sword that allows him to transform into a swashbuckling, renegade hero to face the numerous perils of the unique and diverse Seven Seas of the Triangle.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mobile-suit-gundam-the-witch-from-mercury-hin','Mobile Suit Gundam: The Witch from Mercury','https://image.tmdb.org/t/p/w500/gBkDlMaAVOVMRWWlRUHhkLAhNE3.jpg',2022,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi','A.S. (Ad Stella) 122― An era when a multitude of corporations have entered space and built a huge economic system. A lone girl from the remote planet Mercury transfers to the Asticassia School of Technology, run by the Beneritt Group which dominates the mobile suit industry. Her name is Suletta Mercury. With a scarlet light burning in her pure heart, this girl walks step by step through a new world.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mushoku-tensei-jobless-reincarnation','Mushoku Tensei: Jobless Reincarnation','https://image.tmdb.org/t/p/original/lDS7WuWrq6i1XC1AaKlf9qvJBVi.jpg',2021,'Adventure,Anime,Drama,Ecchi,Fantasy,Hindi Dub,Isekai,Reincarnation','A 34-year-old hikikomori is kicked out of his home by his family after the death of his parents. After his eviction, he saves a group of teenagers from being killed by a speeding truck, but loses his life in the process. When he comes to, he realizes he has been reborn as Rudeus Greyrat, in a world of swords and sorcery.',54);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-clueless-first-friend','My Clueless First Friend','https://image.tmdb.org/t/p/w500/9tZHZz4WC2GOKVat2igukegVaSi.jpg',2023,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Love Status Quo,School,Shounen,Tamil,Telugu','One lonely, gloomy fifth-grade girl is the target of her classmates’ relentless bullying and teasing—that is, until a new kid arrives on the scene. Friendly Takada is as clueless as he is well-meaning, but somehow he possesses the magic ability to start drawing “Grim Reaper” Nishimura out of her shell. As the elementary schoolers experience all the fun of a childhood summer together—from going to the pool to picking sunflowers to watching fireworks—an unusual friendship blossoms!',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-love-story-with-yamada-kun-at-lv999-hin','My Love Story With Yamada-kun at Lv999','https://image.tmdb.org/t/p/w500/zOlHvHcpwU3iY7i97SEvspYht41.jpg',2023,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Video Game','Recently dumped, Akane is just about to quit the game she used to play with her boyfriend, when she meets Yamada in the same RPG. Yamada in real life turns out to be somewhat of a legend. The only problem is – he is ONLY interested in the game. As Akane’s feelings grow, will Yamada’s focus stay on the game?',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('naruto','Naruto','https://image.tmdb.org/t/p/w500/xppeysfvDKVx775MFuH8Z9BlpMk.jpg',0,'Action,Adventure,Anime,Bengali,Fantasy,Hindi Dub,Malayalam,Shounen,Tamil,Telugu','In another world, ninja are the ultimate power, and in the Village Hidden in the Leaves live the stealthiest ninja in the land. Twelve years earlier, the fearsome Nine-Tailed Fox terrorized the village and claimed many lives before it was subdued and its spirit sealed within the body of a baby boy. That boy, Naruto Uzumaki, has grown up to become a ninja-in-training who’s more interested in pranks than in studying ninjutsu.. but Naruto is determined to become the greatest ninja ever!',220);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('new-saga','New Saga','https://image.tmdb.org/t/p/w500/dmZ74VyWi3I8ZqJ1m3Fmcc1etgp.jpg',2025,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Time Travel','Tsuyokute New SagaAfter a brutal war, magic swordsman Kyle defeats the Demon King but is left dying. A crimson crystal sends him four years into the past to his once-destroyed hometown where he finds his lost loved ones alive. Armed with future knowledge, Kyle vows to prevent the coming tragedy and rewrite fate.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('nina-the-starry-bride','Nina the Starry Bride','https://image.tmdb.org/t/p/w500/dCO0ihJjo7y7ptzbdHuJ3UEA8MI.jpg',2024,'Anime,Crunchyroll,Fantasy,Hindi Dub,Romance,Tamil,Telugu,Thriller','Nina had a rough start to life, stealing to survive—and eventually being sold into slavery by her own brother. But to her surprise, her captor, Prince Azure, ordained that she would live the life of a princess…specifically, that of the recently deceased princess-priestess, Alisha. But despite her changing fortune, Nina won’t give up her old life without a fight…and Azure might just be the one to finally match her wits. But how much can she trust Azure? And can she stop the feelings budding in her heart, knowing she must eventually marry another…?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ninja-boy-rantaro','Ninja Boy Rantaro','https://image.tmdb.org/t/p/w500/raKlXyICQBeTxYavErIRybR6g8d.jpg',1993,'Action,Anime,Comedy,Hindi Dub,Kids','Nintama RantaroRantarō, Shinbei and Kirimaru are ninja apprentices in the Ninja Gakuen, where first grade ones are called “Nintamas”. They must learn everything a ninja must know, but as for our heroes, money, food or playing are more interesting. The series show the everyday adventures of our heroes.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ninja-hattori-returns','Ninja Hattori Returns','https://image.tmdb.org/t/p/w500/gt0jlGyGW11Q1HQ7AtFAvioKOV9.jpg',2012,'Action,Adventure,Anime,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','11-year-old Kenichi Mitsuba is an average kid who goes to secondary school and struggles with his studies, he is very stubborn and is very lazy and therefore always ends up frustrating his parents and teacher. He loves to find an easy way of things. He befriends Hattori Kanzo, a ninja from the Iga Clan, and he becomes part of the Mitsuba family along with his brother, Shinzo and his ninja dog, Shishimaru. Hattori helps Kenichi with his problems, and constantly keeps an eye on him, as a good friend. The main antagonist Kemumaki, a Koga ninja and his ninja cat, Kagechiyo always troubles Kenichi, mainly because of their feud over one girl, Yumeko. Kenichi asks Hattori to take revenge as a recurring storyline in many episodes. Although Hattori is a good friend, Kenichi sometimes fights with Ha',156);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ninja-hattori','Ninja Hattori','https://image.tmdb.org/t/p/w500/gdboplmkBiObBYFB1V15nYIDZSd.jpg',1981,'Action,Adventure,Anime,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','11-year-old Kenichi Mitsuba is an average kid who goes to secondary school and struggles with his studies, he is very stubborn and is very lazy and therefore always ends up frustrating his parents and teacher. He loves to find an easy way of things. He befriends Hattori Kanzo, a ninja from the Iga Clan, and he becomes part of the Mitsuba family along with his brother, Shinzo and his ninja dog, Shishimaru. Hattori helps Kenichi with his problems, and constantly keeps an eye on him, as a good friend. The main antagonist Kemumaki, a Koga ninja and his ninja cat, Kagechiyo always troubles Kenichi, mainly because of their feud over one girl, Yumeko. Kenichi asks Hattori to take revenge as a recurring storyline in many episodes. Although Hattori is a good friend, Kenichi sometimes fights with Ha',224);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('oggy-and-the-cockroaches','Oggy and the Cockroaches','https://image.tmdb.org/t/p/w500/aFAN9aKm0OblOr30ROejJCV8rGf.jpg',1999,'Animation,Comedy,Family,Kids','Oggy, an anthropomorphic cat, would prefer to spend his days watching television and eating, but is continuously pestered by three roaches: Joey, Marky and Dee Dee. The cockroaches’ slapstick mischief ranges from plundering Oggy’s refrigerator to hijacking the train he just boarded. In many situations Oggy is also helped by Jack, who is more violent and short-tempered than him and is also annoyed by the cockroaches. Bob, a short-tempered bulldog, also appears in the show, and is Oggy’s neighbor.',111);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('onimusha','Onimusha','https://image.tmdb.org/t/p/w500/lfRmDHegR8OpU3859lBz9YHgD79.jpg',2023,'Action,Adventure,Cartoon,Hindi Dub','With a demonic, soul-consuming weapon in hand, can a legendary swordsman and a samurai brotherhood defeat a bloodthirsty zombie uprising?',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('overlord','Overlord','https://image.tmdb.org/t/p/w500/wwblGcJWowz6aIhR0PoqIDTuyKq.jpg',2015,'Action,Adventure,Anime Times,Fantasy,Hindi Dub,Isekai','In the year 2138, virtual reality gaming is booming. Yggdrasil, a popular online game is quietly shut down one day. However, one player named Momonga decides to not log out. Momonga is then transformed into the image of a skeleton as “the most powerful wizard.” The world continues to change, with non-player characters (NPCs) beginning to feel emotion. Having no parents, friends, or place in society, this ordinary young man Momonga then strives to take over the new world the game has become.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('perman-remastered','Perman [Remastered]','https://image.tmdb.org/t/p/w500/lCGbsqKiOvRICllC4AgZ67zjrSL.jpg',1983,'Anime,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','Mitsuo encountered Superman, an alien who is a part of a federation that tries to maintain peace in the galaxy. He then received a helmet (that also serves as a mask) that gives superhuman strength, a cape that enables the wearer to fly, and a badge that allows him to breathe underwater and communicate with his fellow comrades whom he met soon after he utilized these gifts. Superman made it clear to all Permans that their identity must be kept a secret or their brain will be destroyed should it ever be revealed and they are given a special doppelganger robot that can replace them while they are away to achieve this feat, although it is not entirely foolproof nor is it free from potential problems. These equipments then allowed them to be young Permans who try to maintain peace and help the',276);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('perman','Perman','https://image.tmdb.org/t/p/w500/lCGbsqKiOvRICllC4AgZ67zjrSL.jpg',1983,'Comedy,Family,Hindi Dub,Kids,School,Super Power','Mitsuo encountered Superman, an alien who is a part of a federation that tries to maintain peace in the galaxy. He then received a helmet (that also serves as a mask) that gives superhuman strength, a cape that enables the wearer to fly, and a badge that allows him to breathe underwater and communicate with his fellow comrades whom he met soon after he utilized these gifts. Superman made it clear to all Permans that their identity must be kept a secret or their brain will be destroyed should it ever be revealed and they are given a special doppelganger robot that can replace them while they are away to achieve this feat, although it is not entirely foolproof nor is it free from potential problems. These equipments then allowed them to be young Permans who try to maintain peace and help the',379);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('phineas-and-ferb','Phineas and Ferb','https://image.tmdb.org/t/p/w500/f4QCYoBcJib8BprM4DUIQBMckeQ.jpg',2007,'Cartoon,Comedy,Family,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','Each day, two kindhearted suburban stepbrothers on summer vacation embark on some grand new project, which annoys their controlling sister, Candace, who tries to bust them. Meanwhile, their pet platypus plots against evil Dr. Doofenshmirtz.Please Note That Episode Numbers and Name Will not Match Because Episode List is Imported From TheMovieDatabse But Episodes are Ripped From JIO & Hotstar (Different Order)',137);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-10-diamond-and-pearl','Pokémon Season 10 Diamond and Pearl','https://image.tmdb.org/t/p/w500/9abTHX6IcyiZAXiVDQMM5jKWQDy.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',51);
