INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('popeye-the-sailor','Popeye the Sailor','https://image.tmdb.org/t/p/w500/tQPDl1S1pRg2jzCQWtVUuauZSqa.jpg',1960,'Adventure,Cartoon,Comedy,Hindi Dub,Kids','Follows the adventures of the famed spinach-eating sailor man.Popeye is one of the most popular cartoon characters of all time. This spunky but loveable spinach-eating sailor continues to delight young and old with his comic adventures, and the entire gang is around to provide plenty of rousing fun and action: Olive Oyl, Swee’Pea, Wimpy and Bluto.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-dino-charge','Power Rangers Season 22 Dino Charge','https://image.tmdb.org/t/p/w500/ti6ROtpWKnrQTyigSlsOVHwFUyN.jpg',2015,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','An alien bounty hunter is in search of the powerful Energems to destroy the Earth. Soon, the Power Rangers find the gems and activate the arsenals with their Dino Chargers to fight the monsters.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-dino-fury-season-2','Power Rangers Season 29 Dino Fury Season 2','https://image.tmdb.org/t/p/w500\/lkMsbqWzUieRqko5qGAuHeSsFKB.jpg',2022,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','A team of teenagers with attitude are recruited to save Angel Grove from the evil witch, Rita Repulsa, and later, Lord Zedd, Emperor of all he sees, and their horde of monsters.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-in-space','Power Rangers Season 6 in Space','https://image.tmdb.org/t/p/w500/hzHBxK4ZmPaCkurbv66dgHGD5Ay.jpg',1998,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Rita, Lord Zedd, the Machine Empire and Divatox, join forces with the Dark Specter. Soon, the Power Rangers fight an army of evil forces to save Zordon, who is imprisoned by Dark Specter.',43);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-mystic-force','Power Rangers Season 14 Mystic Force','https://image.tmdb.org/t/p/w500/wc6hvTOfxvrQ0AiBrM1Tafe5aeX.jpg',2006,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Years ago, a powerful spell sealed the evil forces within the Underworld. However, in the present day, when an earthquake jolts the Earth and sets them free, five teenagers try to save the world.',32);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-ninja-storm','Power Rangers Season 11 Ninja Storm','https://image.tmdb.org/t/p/w500/b19GjQRSxOUTKQyW9AMxnWhxTUb.jpg',2003,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Three rebellious students are the last ones remaining at their ninja academy after evil aliens attack the Earth. With mankind at the brink of destruction, the fate of the world lies in their hands.',38);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-super-samurai','Power Rangers Season 19 Super Samurai','https://image.tmdb.org/t/p/w500/wgbiPKdWKLeY5MMNwqvrBkbi2TE.jpg',2012,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','The Samurai Power Rangers must defeat the wicked Master Xandred and his army of Nighloks, who keep becoming stronger. However, using the power from the Black Box, the power Rangers plan their attack.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-wild-force','Power Rangers Season 10 Wild Force','https://image.tmdb.org/t/p/w500/tTfEWTgVaiWxsT7L5kfUUOttuLu.jpg',2002,'Action,Adventure,Family,Hindi Dub,Kids,Live-Action,Sci-Fi','After Cole Evans becomes the new leader of the Wild Force Power Rangers, he strives to fight against the evil forces of the Orgs.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('reborn-as-a-vending-machine-i-now-wander-the-dungeon','Reborn as a Vending Machine, I Now Wander the Dungeon','https://image.tmdb.org/t/p/original/2F7zlgOtk9z0FGn2EjOFWDjGcBP.jpg',2023,'Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation','A middle-aged man with only one passion in his life meets a fitting end in a traffic accident. That’s where most stories would end, but instead, this is when his story begins when he’s reborn as what he admired the most in life–a vending machine! But his new lease on life happens in the worst place possible–what can a vending machine do in a monster-infested dungeon when he can’t speak or even move on his own?',37);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('rimba-racer','Rimba Racer','https://image.tmdb.org/t/p/w500/nRJNSpPsuue1QiMsYAXfZ51uEpb.jpg',2015,'Action & Adventure,Animation,Cartoon,Hindi Dub,Tamil,Telugu','Rimba Racer is an action-packed animation series revolving around Tag, a talented rookie racer and newcomer to the prestigious RIMBA Grand Prix, a racing competition full of tough rivals, dangerous challenges and hidden agendas.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('roll-no-21','Roll No. 21','https://image.tmdb.org/t/p/w500/dUpMEgyDL8uSx1uCt3oEBARSl7w.jpg',2012,'Animation,Comedy,Kids','Kris is an intelligent and naughty kid who stays at an orphanage along with his friends, Pinky and Bablu. An Evil demon King, posing as principal Kanishk is out to create havoc in the school. He has an ulterior motive of taking over the world with his army of zombie demons. To save his friends and the school from annihilation, Kris prays to Lord Krishna and is blessed with super powers.',142);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('rurouni-kenshin','Rurouni Kenshin','https://image.tmdb.org/t/p/w500/9qvWdco2AsLvl6xIwUEh0MbyG4E.jpg',2023,'Action,Adventure,Anime,Crunchyroll,Hindi Dub,Historical,Samurai,Shounen','Ten years have passed since the end of Bakumatsu, an era of war that saw the uprising of citizens against the Tokugawa shogunate. The revolutionaries wanted to create a time of peace, and a thriving country free from oppression. The new age of Meiji has come, but peace has not yet been achieved. Swords are banned but people are still murdered in the streets. Orphans of war veterans are left with nowhere to go, while the government seems content to just line their pockets with money.',47);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('samurai-jack','Samurai Jack','https://image.tmdb.org/t/p/w500/aBig8NqD8IQrZ1OV258MqHvsAsF.jpg',2001,'Action & Adventure,Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy','A great warrior is displaced to the distant future by the evil shape-shifting wizard Aku. The world has become a bleak place under the rule of Aku, segregated into fantastic tribes and ruled by Aku’s evil robot warlords. Jack travels this foreign landscape in search of a time portal that can return him to his home time so he can “undo the future that is Aku!”.',62);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sausage-party-foodtopia','Sausage Party: Foodtopia','https://image.tmdb.org/t/p/w500/cPLk5uvh0Am0UQlxRP4xqNcVQD3.jpg',2024,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub,Kannada,Malayalam,Sci-Fi & Fantasy,Tamil,Telugu','After killing off all of humanity, Food attempts to create their own utopia.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('scooby-doo-mystery-incorporated','Scooby-Doo! Mystery Incorporated','https://image.tmdb.org/t/p/w500/mu8zU2jQfPbGO5bC6RHYrSypxUd.jpg',2010,'Cartoon,Family,Hindi Dub,Mystery','This incarnation of the popular cartoon series finds Scooby and the gang living in Crystal Cove, a small town with a long history of ghost sightings, monster tales and other mysteries ripe for the sleuths to solve once and for all. But the longstanding Crystal Cove residents, who bank on the town’s reputation to attract tourists, are prepared to do what it takes to protect their turf.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('scooby-doo-where-are-you','Scooby-Doo, Where Are You!','https://image.tmdb.org/t/p/w500/lTzUSCtXR77CmGmEHcaxpxu2b4h.jpg',1969,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Fred, Daphne, Velma, Shaggy, and the talking dog, Scooby-Doo, travel on the Mystery Machine van, in search of weird mysteries to solve.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sea-of-love','Sea of Love','https://image.tmdb.org/t/p/w500/rpFUgmuMfMySh2A3DceENRLr3Na.jpg',2022,'Cartoon,Comedy,Hindi Dub,Kids','Sea animal friends Bruda, Bobbi, Wayu and Puri go on mini adventures in the ocean, where relatable, everyday moments come with a splash of magic.',15);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('shangri-la-frontier-hindi','Shangri-La Frontier','https://image.tmdb.org/t/p/w500/aCGdpgNkgz66R1winFkTFsMAhlC.jpg',2023,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu','Shangri La Frontier: Crappy Game Hunter Challenges God-Tier Game, ShanfroRakuro Hizutome only cares about one thing: beating crappy VR games. He devotes his entire life to these buggy games and could clear them all in his sleep. One day, he decides to challenge himself and play a popular god-tier game called Shangri-La Frontier. But he quickly learns just how difficult it is. Will his expert skills be enough to uncover its hidden secrets?',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('shin-chan-specials','Shin Chan Specials','https://image.tmdb.org/t/p/w500/eX1wf1DLKCIQmVM66kpKWcjYojA.jpg',1992,'Anime,Comedy,Ecchi,Hindi Dub,Seinen,Tamil,Telugu','Shin-chan, the boy next door, is a walking disaster, creating chaos wherever he goes. With the body of a child and the mind of an adult, Shinchan is wreaking more havoc than any child before. Shin-chan is carefree, optimistic and gets excited about everything. This 5 year-old likes to do things his way.',9);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sk8-the-infinity','SK8 the Infinity','https://image.tmdb.org/t/p/w500/kZHnqxP16mb2pVYthJfT4buYk4P.jpg',2021,'Anime,Crunchyroll,Hindi Dub,Racing,Sports','“S” is a dangerous, top secret, no-holds-barred downhill skateboarding race down an abandoned mine. When avid skateboarder Reki takes Langa to the mountain where “S” is held, Langa, who’s never been on a skateboard in his life, finds himself sucked into the world of “S”, and…?!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('slugterra','Slugterra','https://image.tmdb.org/t/p/w500/hbAHSGKr0aJStev8w5ebWWZboh1.jpg',2012,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Sci-Fi','Following his father’s death, 15-year-old Eli Shane embraces his destiny to follow in his dad’s footsteps to a secret, subterranean world called Slugterra where he is determined to be the greatest Slugslinging hero of them all!',56);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sparks-of-tomorrow','Sparks of Tomorrow','https://media.themoviedb.org/t/p/w440_and_h660_face/yDTcX4l5D3OFeYGsQVI5Jqxx1D7.jpg',2026,'Animation,Anime,Drama,Hindi Dub,Netflix,Sci-Fi & Fantasy','In an alternate past, an unlikely duo team up to look for a missing catalog that could bring electricity to the smoke-filled streets of Kyoto.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('star-vs-the-forces-of-evil','Star vs. the Forces of Evil','https://image.tmdb.org/t/p/w500/dKFL1AOdKNoazqZDg1zq2z69Lx1.jpg',2015,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','Intergalactic warrior Star Butterfly arrives on Earth to live with the Diaz family. She continues to battle villains throughout the universe and high school, mainly to protect her extremely powerful wand, an object that still confuses her.',55);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('star-wars-young-jedi-adventures','Star Wars: Young Jedi Adventures','https://image.tmdb.org/t/p/w500/oqTS9LOmp8ibRY1nsjBjP660mCb.jpg',2023,'Action,Adventure,Cartoon,Hindi Dub,Sci-Fi','Set during the High Republic era and the prime of the Jedi Order, follow Jedi younglings as they study the ways of the Force, explore the galaxy, help citizens and creatures in need, and learn valuable skills needed to become Jedi along the way.',7);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('superman-the-animated-series','Superman: The Animated Series','https://image.tmdb.org/t/p/w500/7lhG7XSz0VkbUtXoXtUVdjDrUx6.jpg',1996,'Action,Adventure,Cartoon,Drama,Hindi Dub','Superman, an incredibly powerful alien from the planet Krypton, defends Metropolis from supercriminals. Superman hides his identity behind the glasses of Clark Kent; a mild-mannered reporter for the newspaper the Daily Planet. At the Daily Planet Superman works with fellow reporter Lois Lane and photographer Jimmy Olsen.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('talespin','TaleSpin','https://image.tmdb.org/t/p/w500/gObO6CMSRbQNehvJyF4CwOHC5VI.jpg',1990,'Animation,Cartoon,Family,Hindi Dub,Kids,Tamil,Telugu','Baloo the Bear stars in an adventurous comedy of love and conflict with his friend Kit Cloudkicker. Rebecca Cunningham and her daughter Molly purchase Baloo’s failing company and Baloo must fly transport runs to clear his debt while dodging Don Karnage and his sky pirates.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tamons-b-side','Tamon’s B-Side','https://image.tmdb.org/t/p/w440_and_h660_face/1iTCxEIK1xlmIXjHcLjt0UyOU8w.jpg',2026,'Ani-One India,Anime,Comedy,Hindi Dub,Idols,Romance,Shoujo','Utage Kinoshita is a high school girl who works part-time as a housekeeper. She has devoted her life to her favorite idol, Tamon Fukuhara, from the group F/ACE. Then one day, Utage ends up being assigned to Tamon’s house! There she discovers that off-stage, he is nothing like his wild idol persona. A gloomy, introverted boy with no self-confidence, Utage still finds herself falling for him anyway.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('teen-titans','Teen Titans','https://image.tmdb.org/t/p/w500/Amf77y1dohmt3M0lgz1CHogPgyc.jpg',2003,'Action & Adventure,Animation,Cartoon,Hindi Dub,Super Power','The Teen Titans are five heroes under one roof. Their names: Robin, Starfire, Raven, Cyborg, and Beast Boy They live in a large tower in the shape of a T that they call Titan Tower. No secret identities. No school. Just superheroes being superheroes. They must go up against their arch nemesis, Slade, and his evil minions. What he really plans to do is unknown but one thing’s for sure… he’s an evil madman.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-amazing-world-of-gumball','The Amazing World of Gumball','https://image.tmdb.org/t/p/w500/VYnnyA2hyxi3VUPgCA71mMtt69.jpg',2011,'Animation,Comedy,Family,Sci-Fi & Fantasy','The life of Gumball Watterson, a 12-year old cat who attends middle school in Elmore. Accompanied by his pet, adoptive brother, and best friend Darwin Watterson, he frequently finds himself involved in various shenanigans around the city, during which he interacts with various family members: Anais, Richard, and Nicole Watterson, and other various citizens.',58);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-avengers-earths-mightiest-heroes','The Avengers: Earth’s Mightiest Heroes','https://image.tmdb.org/t/p/w500/vhgNwUBjkT1I8cCreEwVyuYM5xO.jpg',2010,'Action & Adventure,Animation,Family,Sci-Fi & Fantasy','When the powers of a single hero are not enough to save the world, the world’s greatest heroes—Iron Man, Thor, Captain America, The Hulk, Ant-Man/Giant Man and Wasp—assemble to form the Avengers.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-beginning-after-the-end','The Beginning After the End','https://image.tmdb.org/t/p/original//d23Lspt2mbVP8WwJNgb5Sg4Kdhu.jpg',2025,'Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation','After a mysterious death, King Grey is reborn as Arthur Leywin on the magical continent of Dicathen. Although he enters his second life as a baby, his previous wisdom remains. He begins to master magic and forge his own path as the years go by, seeking to correct the mistakes of his past life.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-boys-presents-diabolical','The Boys Presents: Diabolical','https://image.tmdb.org/t/p/w500/kZKfZWwFOAicgoKS2IO7oM1GuHZ.jpg',2022,'Action & Adventure,Animation,Cartoon,Hindi Dub,Tamil,Telugu','From some of the most unhinged and maniacal minds in Hollywood today comes this animated anthology series, a collection of irreverent and emotionally shocking animated short films. Each episode plunges elbow-deep into unseen crevices of The Boys Universe.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-detective-is-already-dead','The Detective Is Already Dead','https://image.tmdb.org/t/p/w500/8gCOlj0bXa2cQnXSl4wRX5tVIA0.jpg',2021,'Anime,Crunchyroll,Drama,Hindi Dub,Mystery,Romance','Kimizuka Kimihiko is a crisis-magnet. So it is no surprise when his rather mundane flight suddenly enters a state of emergency with a dire need of a detective onboard. Unfortunately, his attempt at avoiding trouble is foiled by a beautiful girl with silver hair who goes by the codename Siesta. Declaring herself a detective, she unceremoniously drags Kimizuka into the case as her assistant. That incident spelled the beginning of an adventure around the globe that went beyond his wildest imagination. Putting their lives on the line, the two took down criminal organizations, prevented disasters, and saved thousands. But the curtain closed to their epic journey with Siesta’s untimely death three years later. Resolving to live an ordinary high school life this time, Kimizuka spends a year maint',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-god-of-high-school','The God of High School','https://image.tmdb.org/t/p/w500/AnXFYG7y2A65dr5noYvZSdVq8l3.jpg',2020,'Action,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Martial Arts,Tamil,Telugu','When an island half-disappears from the face of the earth, a mysterious organization sends out invitations for a tournament to every skilled fighter in the world. “If you win you can have ANYTHING you want,” they claim. They’re recruiting only the best to fight the best and claim the title of The God of High School. Jin Mori, a Taekwondo specialist and a high school student, soon learns that there is something much greater beneath the stage of the tournament.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-grim-adventures-of-billy-and-mandy','Haddi Mera Buddy (Old Dub)','https://image.tmdb.org/t/p/w500/aTtVM7JqPf2jLBrY4Al7CgPvFVi.jpg',2001,'Cartoon,Comedy,Family,Hindi Dub,Kids','The Grim Adventures of Billy and MandyBilly Mandy Aur Life Mein HaddiThe exploits of the Grim Reaper, who has been forced into being the best friend of two children. A spin-off of the show Grim & Evil.Please Note That Episode Number and Name Will not Match.',66);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-grimm-variations','The Grimm Variations','https://image.tmdb.org/t/p/w500/jjk6nHiZGlRu2f6fWyjNWL0hp0k.jpg',2024,'Anime,Fantasy,Hindi Dub,Horror,Suspense','Inspired by the classic Brothers Grimm stories, this anthology features six fairy tales with a dark twist, exposing the shadowy side of human desire.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-incredible-hulk','The Incredible Hulk','https://image.tmdb.org/t/p/w500/wa60s9NSvrH87NFCArmobnIyNnh.jpg',1996,'Action & Adventure,Animation,Cartoon,Drama,Hindi Dub,Tamil,Telugu','The Incredible Hulk is an American animated television series starring the Marvel Comics character the Hulk. It ran two seasons, for 21 episodes, on the television network UPN from 1996 to 1997. Lou Ferrigno, who portrayed Universal’s version of the Hulk on the 1970s live-action TV series, provided the Hulk’s voice for the true version from Marvel.The show often featured cameo appearances by characters from other Marvel cartoons of the period. In the second season, the show’s format, after UPN decided that Season 1 was too dark, was changed, and to give “female viewers a chance”, the network ordered that She-Hulk be made a regular co-star. As a result, the series was officially renamed The Incredible Hulk and She-Hulk. The second season also featured the Grey Hulk.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-legend-of-karna','The Legend of Karna','https://image.tmdb.org/t/p/original//jzVP9rqT2YH2nTx3l3csmmU9B1q.jpg',2026,'Action & Adventure,Animation,Anime,Bengali,Drama,Hindi Dub,Kannada,Malayalam,Marathi,SonyLiv','A warrior from the Mahabharata who is born to Kunti and the Sun God Surya but raised in a charioteer’s household. He possesses the gift of bow mastery that rivals the greatest warriors of his age, compelling him to enter a grand tournament usually reserved only for kings and princes, altering the course of an empire forever.',3);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-magical-girl-and-the-evil-lieutenant-used-to-be-archenemies','The Magical Girl and the Evil Lieutenant Used to Be Archenemies','https://image.tmdb.org/t/p/w500/r5mp5XoWP9q8fTvx4rLZbC8qtgj.jpg',2024,'Anime,Comedy,Hindi Dub,Kannada,Romance,Shoujo,Shounen,Tamil,Telugu','An evil organization invades and destroys everything in its path. The brains of the brutal operation is the king’s right-hand man, an evil lieutenant named Mira. Everything changes when a magical girl named Byakuya Mimori tries to stop the evil group in their tracks. When Mira confronts her, he knows it’s love at first sight. What will become of Mira and Byakuya, stuck between orders and love?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-mighty-nein','The Mighty Nein','https://image.tmdb.org/t/p/w500/qJTZanXDiJKABLNGRM9LmSg8YT7.jpg',2025,'Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy','When a powerful arcane relic known as “The Beacon” falls into dangerous hands, a group of fugitives and outcasts, bound by secrets and scars, must learn to work together to save the realm and stop reality itself from unraveling.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-new-adventures-of-winnie-the-pooh','The New Adventures of Winnie the Pooh','https://image.tmdb.org/t/p/w500/iJFbF43bN1HX5EZl4OFAVmJDl1u.jpg',1988,'Cartoon,Comedy,Family,Hindi Dub,Kids,Tamil,Telugu','An American animated children’s television series inspired by A. A. Milne’s Winnie-the-Pooh stories.',32);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-new-scooby-doo-movies','The New Scooby-Doo Movies','https://image.tmdb.org/t/p/w500/slBx9Vkh0ET9m2lgrD8KxJDL5T9.jpg',1972,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Aside from doubling the length of each episode, The New Scooby-Doo Movies differed from its predecessor in the addition of a rotating special guest star slot; each episode featured real-life celebrities or well known fictional characters joining the Mystery, Inc. gang in solving the mystery of the week. Some episodes, in particular the episodes guest-starring the characters from The Addams Family, Batman, and Jeannie, deviated from the established Scooby-Doo format of presenting criminals masquerading as supernatural beings by introducing real ghosts, witches, monsters, and other such characters into the plots.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-powerpuff-girls','The Powerpuff Girls','https://image.tmdb.org/t/p/w500/4CMPCuP6ihU5UvTStv23aGEEMuC.jpg',1998,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Kids,Tamil,Telugu','The Powerpuff Girls is a animated television series about Blossom, Bubbles, and Buttercup, three kindergarten-aged girls with superpowers, as well as their “father”, the brainy scientist Professor Utonium, who all live in the fictional city of Townsville, USA. The girls are frequently called upon by the town’s childlike and naive mayor to help fight nearby criminals using their powers.Episode Numbers and Name Will not Match.',131);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-rising-of-the-shield-hero','The Rising of the Shield Hero','https://image.tmdb.org/t/p/w500/yjq2n0agGJfmZQ9NpbYIhuBofcq.jpg',2019,'Action,Adventure,Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Isekai,Tamil,Telugu','Iwatani Naofumi, a run-of-the-mill otaku, finds a book in the library that summons him to another world. He is tasked with joining the sword, spear, and bow as one of the Four Cardinal Heroes and fighting the Waves of Catastrophe as the Shield Hero. Excited by the prospect of a grand adventure, Naofumi sets off with his party. However, merely a few days later, he is betrayed and loses all his money, dignity, and respect. Unable to trust anyone anymore, he employs a slave named Raphtalia and takes on the Waves and the world. But will he really find a way to overturn this desperate situation?',62);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-sylvester-tweety-mysteries','The Sylvester & Tweety Mysteries','https://image.tmdb.org/t/p/w500/b8AkMeacC71nABALm5GgT1x5nMo.jpg',1995,'Animation,Comedy,Crime,Mystery','Sylvester and Tweety help out when Granny opens a detective agency.',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-thundermans','The Thundermans','https://image.tmdb.org/t/p/w500/1tIYEyjK1LLcX0jYK3ZouT7601o.jpg',2013,'Action & Adventure,Comedy,Family,Sci-Fi & Fantasy,Super Power,Supernatural','Meet The Thundermans, a typical suburban family that happens to have astounding superpowers. At the center of the action are the 14-year-old Thunderman twins, who share the same bathroom, the same school, and the same annoying little siblings. Their only difference? The sister is a super student with a super sunny disposition who super looks forward to being a superhero someday, and her twin brother is a super villain.EPISODES NOT ARRANGED ACORDING TO VootKids',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-tom-and-jerry-show','The Tom and Jerry Show','https://image.tmdb.org/t/p/w500/41EWXLXTZO4MLb2BL28mWZuydyq.jpg',2014,'Animation,Cartoon,Comedy,Family,Hindi Dub','The iconic cat and mouse rivals are back in a fresh take on the classic series. Preserving the look, characters and sensibility of the original, this series shines a brightly colored, high-definition lens on the madcap slapstick and never-ending battle that has made Tom and Jerry two of the most beloved characters of all time.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tokyo-revengers','Tokyo Revengers','https://image.tmdb.org/t/p/w500/arB3L9pZZBSzUPSC8BEv8c3X0bF.jpg',2021,'Action,Anime,Crime,Delinquents,Drama,Hindi Dub,Shounen,Time Travel','Takemichi Hanagaki is a freelancer that’s reached the absolute pits of despair in his life. He finds out that the only girlfriend he ever had, in middle school, Hinata Tachibana, had been killed by the ruthless Tokyo Manji Gang. The day after hearing about her death, he’s standing on the station platform and ends up being pushed over onto the tracks by a herd of people. He closes his eyes thinking he’s about to die, but when he opens his eyes back up, he somehow had gone back in time 12 years. Now that he’s back living the best days of his life, Takemichi decides to get revenge on his life.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tomb-raider-king','Tomb Raider King','https://image.tmdb.org/t/p/original/xDW6cor12UD0b2IqboQWnrIn0UO.jpg',2026,'Action & Adventure,Animation,Anime,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Chaos ensues overnight when mysterious tombs suddenly surface, filled with divine relics granting overwhelming power, triggering a global power struggle to claim them for dominion. Among the havoc, a raider, Jooheon Suh, is betrayed and left for dead until a second chance brings him back years before the relics. Fueled by fury and future knowledge, he sets out to raid each tomb before they arise.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tomo-chan-is-a-girl','Tomo-chan Is a Girl!','https://image.tmdb.org/t/p/w500/h9TN2BltJ9Q7FZ5BYGQcHfYfEGp.jpg',2023,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,School,Tamil,Telugu','Tomboy Tomo couldn’t have picked a more awkward high school crush ’cause it’s on her childhood friend, Junichiro, but he only sees her as one of the guys. Despite her pretty looks and signals, nothing gets through to this meathead! Will Junichiro ever realize Tomo’s into him and see her for the cutesy girl she actually is?!',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tower-of-god-hindi','Tower of God','https://image.tmdb.org/t/p/w500/y1AqUftsCLNGRNE7McJzGqLFEdu.jpg',2020,'Action,Adventure,Animation,Anime,Crunchyroll,Drama,Fantasy,Hindi Dub,Mystery,Tamil,Telugu','Reach the top, and everything will be yours. At the top of the tower exists everything in this world, and all of it can be yours. You can become a god. This is the story of the beginning and the end of Rachel, the girl who climbed the tower so she could see the stars, and Bam, the boy who needed nothing but her.',39);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-animated','Transformers: Animated','https://image.tmdb.org/t/p/w500/uEKVNu69urMrXSuAdeK54HOtvo4.jpg',2007,'Action & Adventure,Animation,Family,Sci-Fi & Fantasy','The evil Decepticons have appeared in Detroit. With the all powerful Allspark, Megatron can use it to turn all of Earth’s robots into Decepticons. However, Optimus Prime and his Autobots arrive and plan to stop Megatron and his evil plan in Transformers Animated.',42);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-prime','Transformers: Prime','https://image.tmdb.org/t/p/w500/ilOKsGRHYc78R2tSMusAd3xGJWq.jpg',2010,'Action & Adventure,Animation,Hindi Dub,Kids','Roll out with Optimus Prime, Bumblebee, Arcee, Ratchet, Bulkhead, and the rest of the heroic Autobots as they battle the evil Decepticons. Now that big bad Megatron has returned with a mysterious and dangerous element, Team Prime must prepare for an epic battle.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-rescue-bots-academy','Transformers: Rescue Bots Academy','https://image.tmdb.org/t/p/w500/osq5D28OW66VjwO4jjtxU5JarRv.jpg',2018,'Action & Adventure,Animation,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy','Five students of the Rescue Bots Training Academy from Cybertron—Hot Shot, Whirl, Medix, Hoist and Wedge—learn to respond to emergency situations and become heroes.',104);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-war-for-cybertron-earthrise','Transformers: War for Cybertron: Earthrise','https://image.tmdb.org/t/p/w500/63E619RuPL9EUjPzVTWCs2jUChl.jpg',2020,'Action & Adventure,Animation,Sci-Fi & Fantasy','While Megatron takes drastic measures to save the Decepticons, the Autobots fight to save all of Cybertron from both on the planet and aboard the Ark.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('trese','Trese','https://image.tmdb.org/t/p/w500/zNYPSo9nhrLyy453s5SsC0MCTuz.jpg',2021,'Animation,Crime,Mystery,Sci-Fi & Fantasy','In Manila, where dark supernatural forces pervade the criminal underworld, it’s up to Alexandra Trese to keep the peace — but there’s a storm brewing.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('trollhunters-tales-of-arcadia','Trollhunters: Tales of Arcadia','https://image.tmdb.org/t/p/w500/9VZmMzINVdO3ZYGsKItU39pNO2l.jpg',2016,'Action,Adventure,Cartoon,Comedy,Family,Fantasy,Hindi Dub,Sci-Fi','After uncovering a mysterious amulet, an average teen assumes an unlikely destiny and sets out to save two worlds.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tying-the-knot-with-an-amagami-sister','Tying the Knot with an Amagami Sister','https://image.tmdb.org/t/p/w500/aPJ4E6QL9lGlRYQ0ms60JZISZsD.jpg',2024,'Anime,Comedy,Crunchyroll,Harem,Hindi Dub,Romance,Shounen,Tamil,Telugu','Uryu Kamihate is a high school student hoping to enroll in Kyoto University’s medical school. After being taken in by the chief priest at Amagami Shrine, he is told he must marry one of three maiden sisters—Yae, Yuna, or Asahi—to live at, and one day inherit, the Amagami Shrine. Kamihate will need to sweep one of the maidens off her feet in this story of romance, friendship, and fun.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ultraman-z','Ultraman Z','https://image.tmdb.org/t/p/w500/9xE0tlBJjWZNjY7BbY0fRaNCe9p.jpg',2020,'Action,Adventure,Comedy,Hindi Dub,Sci-Fi','The newest Ultra Hero is Ultraman Zett, the disciple of Ultraman Zero, who is now celebrating his tenth anniversary! An admirer of Zero, Zett worked hard to become a member of the “Inter Galactic Defense Force.” With a passion inherited from his teacher Zero, Zett is an Ultraman who always looks forward and forges ahead.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ultraviolet-code-044','Ultraviolet: Code 044','https://image.tmdb.org/t/p/w500/kn3hzWSL3HIrrApz0UsXvnZFNHh.jpg',2008,'Action & Adventure,Animation,Hindi Dub,Sci-Fi & Fantasy','044 becomes the strongest female soldier excelling in combat through gene manipulation using a virus. However, in exchange for her abilities, her days become numbered.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('unicorn-academy','Unicorn Academy','https://image.tmdb.org/t/p/w500/iuxH52TvBkPTBvdjgOEJ6RKvOPR.jpg',2023,'Animation,Cartoon,Hindi Dub,Kids,Sci-Fi & Fantasy','When a dark force threatens to destroy Unicorn Island, a brave teen and her five schoolmates must rise up to protect their beloved magical academy.',9);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('viral-hit','Viral Hit','https://image.tmdb.org/t/p/w500/1kZBsmNYgjRxFPBfrFxkQGwS7xX.jpg',2024,'Action,Anime,Crunchyroll,Hindi Dub,Martial Arts,School','Scrawny high school student Hobin Yu is probably the last guy you’d expect to star in a NewTube channel that revolves around fighting. But after following some advice from a mysterious NewTube channel, Hobin is soon knocking out guys stronger than him and raking in more money than he could have ever dreamed of. Can Hobin keep this up, or will he eventually meet his match?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('vtuber-legend','VTuber Legend','https://image.tmdb.org/t/p/w500/c6eB42kmJWGZgKecme6jhDeNMQr.jpg',2024,'Anime,Comedy,Crunchyroll,Hindi Dub,Otaku Culture','VTuber Legend How I Went Viral After Forgetting to Turn Off My StreamYuki Tanaka is a VTuber at Live-On, one of Japan’s largest VTuber companies, as the polite and ladylike Awayuki Kokorone. One day, she forgets to end the stream, and viewers see her real personality—irreverent, improper, and prone to imbibing after a long day. Yuki is surprised to find that her accident caused her rankings to multiply, so she doubles down and gets to work. She’ll be a star yet!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('whatever-happened-to-robot-jones','Whatever Happened to… Robot Jones?','https://image.tmdb.org/t/p/w500/pLl9mC1Kkb0VLAmsJqJletKexv.jpg',2002,'Animation,Comedy','Robot Jones, a robotic teenager, attends a suburban middle school.',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('with-you-our-love-will-make-it-through','With You, Our Love Will Make It Through','https://image.tmdb.org/t/p/w500/hqx5GLLcv1SuW3AAmv2ZFa7l7bF.jpg',2025,'Anime,Anthropomorphic,Crunchyroll,Drama,Fantasy,Hindi Dub,Romance,School,Tamil,Telugu,Urban Fantasy','When high schooler Mari runs late for school, she never expects to fall for Tsunagu—a gentle, sensitive, beastfolk! In a world where beastfolk are segregated behind walls, Mari and Tsunagu show their differences are truly bridges. Can their love overcome the divide between beastfolk and humanity?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('you-are-ms-servant','You are Ms. Servant','https://image.tmdb.org/t/p/w500/2cy3OBNvkcdJD2r7h7DxeLXbmrh.jpg',2024,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,Tamil,Telugu','Hitoyoshi, a high school kid who lives alone, hears a knock on his door. He opens it to find a strange girl offering to be his maid. She has beautiful black hair, graceful manners, and…a dark past as an assassin. But despite her deadly background and lack of household skills, Hitoyoshi takes her in. As she adjusts to her new life, she begins to experience emotions she’s never felt before.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('young-justice','Young Justice','https://image.tmdb.org/t/p/w500/hcAfE4HCCenhF09vhkd9uxEVkMr.jpg',2010,'Action,Adventure,Cartoon,Fantasy,Hindi Dub,Sci-Fi','Teenage superheroes strive to prove themselves as members of the Justice League.',72);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('yuri-on-ice','Yuri!!! on Ice','https://image.tmdb.org/t/p/w500/oxenakJNCj06JrWHENjvwaWGcSz.jpg',2016,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Performing Arts,Sports,Tamil,Telugu','While on the verge of retirement, skater Yuri Katsuki meets Yuri Plisetsky and Victor Nikiforov, two skaters who rekindle his competitive fire.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zatch-bell-remastered','Zatch Bell! (Remastered)','https://image.tmdb.org/t/p/w500/cBcHLTG8UgtKi1i1iN0XVcRAB78.jpg',2003,'Animation,Anime,Comedy,Hindi Dub,Kids','Takamine Kiyomaro, a depressed don’t-care-about-the-world guy, was suddenly given a little demon named Zatch Bell to take care of. Little does he know that Zatch is embroiled in an intense fight to see who is the ruler of the demon world.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zatch-bell','Zatch Bell!','https://image.tmdb.org/t/p/w500/cBcHLTG8UgtKi1i1iN0XVcRAB78.jpg',2003,'Anime,Comedy,Hindi Dub,Mythology,Shounen,Supernatural','Takamine Kiyomaro, a depressed don’t-care-about-the-world guy, was suddenly given a little demon named Zatch Bell to take care of. Little does he know that Zatch is embroiled in an intense fight to see who is the ruler of the demon world.Episodes 66, 89, 99, 104, 106, 109, 111, 116, 120-150 are not available in Hindi',150);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zenshu','ZENSHU','https://image.tmdb.org/t/p/w500/vuKujQdZWoYsJjiDb2LJTaa1S2u.jpg',2025,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Isekai,Tamil,Telugu','After graduating from high school, Natsuko Hirose starts her career as an animator. Her talent quickly flourishes, and she makes her debut as a director in no time. Her first anime becomes a massive hit, sparking a social phenomenon and earning her recognition as an up-and-coming genius director. Her next project is set to be a romantic comedy movie themed around first love! However, having never been in love herself, Natsuko struggles to understand the concept of first love, and as a result, she’s unable to create the storyboard, causing the movie production to come to a standstill.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('madan-senki-ryukendo','Madan Senki Ryukendo','https://image.tmdb.org/t/p/w500/k2Zu19nKv7bT2TBw8mpYaqhUEYy.jpg',2006,'Action & Adventure,Cartoon,Drama,Family,Hindi Dub,Hindi Sub,Kids,Sci-Fi & Fantasy','Akebono City is a peaceful community overflowing with humanity. Since there was a Power Spot that released the magical power in the community, the people were distressed by the threat of the demon army Jamanga who are gathering Minus Energy (マイナスエネルギー Mainasu Enerugī) from the frightened masses for a sinister purpose. The secret organization S.H.O.T. was formed to protect the people of the community from the Jamanga, concealing their existence as ordinary members of the Akebono Police Station, which considers demons beyond their jurisdiction. Kenji Narukami, a student of the Narukami Dragon God Style (鳴神龍神流 Narukami Ryūjinryū) for fighting demons, arrives at Akebono to fight the demons, eventually getting his wish when he is transformed to RyuKenDo and faces off against Jamanga’s forces to',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('makeine-too-many-losing-heroines','Makeine: Too Many Losing Heroines!','https://image.tmdb.org/t/p/w500/oRsm8wiA9QJHT4YNpU7jzsyujAS.jpg',2024,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,School,Tamil,Telugu','Meet the girls on the losing side of romance! First is Anna Yanami, the girl-next-door type who can’t say no to delicious food. Then there’s Lemon Yakishio, a beautiful and spirited athlete. Last but not least is Chika Komari, the cute yet shy heroine with gentle charm. Together, they navigate awkward setbacks hoping to finally find love!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('masamune-kuns-revenge','Masamune-kun’s Revenge','https://image.tmdb.org/t/p/w500/50jjmuwSwMxlXAP1jQ48kr1xrcN.jpg',2017,'Anime,Comedy,Crunchyroll,Drama,Harem,Hindi Dub,Romance,School','As a child, Masamune Makabe once suffered greatly at the hands of a wealthy and beautiful girl named Aki Adagaki, who nicknamed him “Piggy” due to his chubby appearance. Seeking revenge against his tormentor, Masamune works hard to improve himself and returns as an incredibly handsome, albeit narcissistic, high school student. When he encounters Aki once again, he is prepared to exact vengeance.With the aid of the rich girl’s maid, Yoshino Koiwai, Masamune slowly begins to build his relationship with Aki, intending to break her heart when the time is right. However, as his friendship with Aki begins to grow, Masamune starts to question the objectives of his devious plans, and if bringing them to fruition is what his heart truly desires.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mechamato-the-animated-series','Mechamato The Animated Series','https://image.tmdb.org/t/p/w500/1rkM4tLoNKC33sLVyAWgogZGo3B.jpg',2021,'Action,Adventure,Cartoon,Hindi Dub,Kids,Tamil,Telugu','This series tells the story of a kind and creative boy named Amato, who comes across a prison spaceship housing many evil robots. One of them is MechaBot, who has the ability to mechanize everyday objects into high tech devices. Amato outsmarts MechaBot and becomes his master. The two bond together as friends over the course of the series and team up in the form of a superhero named Mechamato to locate and capture the evil robots that had escaped the fallen spacecraft.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('mickey-and-the-roadster-racers','Mickey and the Roadster Racers','https://image.tmdb.org/t/p/w500/3D4275Ck9eXdMlXEQgNrOsikmMS.jpg',2017,'Action & Adventure,Animation,Kids','Mickey Mouse and his pals Minnie, Pluto, Goofy, Daisy and Donald take their unique transforming vehicles on humorous high-spirited races around the globe as well as hometown capers in Hot Dog Hills.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('murder-drones','Murder Drones','https://image.tmdb.org/t/p/w500/wXwiNeXa4lY7AWb72XdAdnIK9lC.jpg',2021,'Action & Adventure,Animation,Sci-Fi & Fantasy','A heart warming story of “destroy all humans.” Uzi, a sardonic teen worker robot gone rogue befriends N, an excitable optimistic disassembly drone sent to destroy her, creating what we can assume is a very bad relationship for mankind.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-hero-academia','My Hero Academia','https://image.tmdb.org/t/p/w500/5LeDYSGE2axfdj3BMWhWBcb9Dmv.jpg',2016,'Action,Anime,Hindi Dub,Malayalam,School,Shounen,Super Power,Tamil,Telugu','Boku no Hero AcademiaIn a world where eighty percent of the population has some kind of super-powered Quirk, Izuku was unlucky enough to be born completely normal. But that won’t stop him from enrolling in a prestigious hero academy. Now, he’ll get his first taste of brutal rivalry from other schools as he braves the cutthroat, no-holds-barred provisional license exam.',176);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('my-status-as-an-assassin-obviously-exceeds-the-heros','My Status as an Assassin Obviously Exceeds the Hero’s','https://image.tmdb.org/t/p/w500/oQk3aXYEa4TMd9rAYgzDpAYTU8P.jpg',2025,'Action,Adventure,Anime,Fantasy,Hindi Dub,Isekai,Tamil,Telugu','Akira Oda and his high school classmates are summoned to another world! While the other students are granted cheat abilities through the summoning, Akira merely gains the abilities of a mediocre “assassin.” However, his status soon surpasses “hero,” the strongest profession. After Akira becomes suspicious of the King behind the summoning, he is falsely framed for a crime and forced to flee.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('niko-and-the-sword-of-light','Niko and the Sword of Light','https://image.tmdb.org/t/p/w500/AsiXFOliQUKM6bOO4FfkGDAffko.jpg',2017,'Action & Adventure,Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy','A plague of shadows has swept across the land, turning innocent creatures into terrible monsters. One champion remains to battle the darkness and return the world to the light: Niko. Armed with his magic sword and guided by a determined Princess, young Niko journeys to the Curse-ed Volcano to face the evil sorcerer Nar Est and free his people from their magic prison.',23);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('nippon-sangoku-the-three-nations-of-the-crimson-sun','NIPPON SANGOKU: The Three Nations of the Crimson Sun','https://image.tmdb.org/t/p/w500/ygzii2w2ln459CJFPbXigDAV3SE.jpg',2026,'Amazon Prime,Anime,Drama,Hindi Dub,Military','A revolution sparked by nuclear war, natural disaster, and misrule leads to the collapse of Japanese society. The country splits into three nations vying for hegemony, and the Sangoku era begins. Aoteru Misumi, a former agricultural officer, vows to reunify Japan. He rises through the ranks with only his knowledge and eloquence. Witness the legend of the man later hailed as a genius strategist.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('oscars-oasis','Oscar’s Oasis','https://image.tmdb.org/t/p/w500/wk7dZ7qoocFZqzvr37SfO5nKncr.jpg',2010,'Animation,Cartoon,Comedy,Hindi Dub','Oscar, a lizard in the middle of the desert, finds himself misadventures wherever he goes.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('oshi-no-ko','【OSHI NO KO】','https://image.tmdb.org/t/p/w440_and_h660_face/auDtj9Dwe5VptOWPuZzDMoy66HB.jpg',2023,'Anime,Drama,Hindi Dub,MX Player,Reincarnation,Seinen,Showbiz','OSHI NO KOA small-town doctor gets sucked into the ruthless world of show business when he crosses paths with a popular teen idol who holds a secret.',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('paradox-live-the-animation','Paradox Live THE ANIMATION','https://image.tmdb.org/t/p/w500/tlPG08mmtFPb6K0PpymddXvuzzt.jpg',2023,'Anime,Anime Times,Drama,Hindi Dub,Kannada,Music,Sci-Fi,Tamil,Telugu','Saturated in hip hop culture comes the birth of a new movement known as “Phantom Live.” Each of the artists have a metal accessory known as “Phantom Metal” which chemically reacts to the wearer’s emotions to produce an image, setting a magnificent stage for enthusiastic youths. With legendary club “CLUB paradox” hosting the mysterious Paradox Live, four teams: BAE, The Cat’s Whiskers, cozmez and Akanyatsura each receive an invitation to participate, each with their own genre of music in a race to the top.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('penn-zero-part-time-hero','Penn Zero: Part-Time Hero','https://image.tmdb.org/t/p/w500/cCk9Lf8SL4yQqNsphC34NL7rCtL.jpg',2014,'Action & Adventure,Animation,Cartoon,Comedy,Hindi Dub,Sci-Fi & Fantasy','Penn Zero is not your average kid – every day he’s zapped into another dimension with his friends to save the world.',21);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('pokemon-season-13-dp-sinnoh-league-victors','Pokémon Season 13 DP Sinnoh League Victors','https://image.tmdb.org/t/p/w500/l5GEKuCEV27tKdZV42GWJT4i7m4.jpg',1997,'Action,Adventure,Anime,Fantasy,Hindi Dub,Sci-Fi','Join Ash accompanied by his partner Pikachu, as he travels through many regions, meets new friends and faces new challenges on his quest to become a Pokémon Master.',34);
