INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-cosmic-fury','Power Rangers Season 30 Cosmic Fury','https://image.tmdb.org/t/p/w500/vQIMQ5rYiRLOVh3Vi2K0ymYZh5j.jpg',1993,'Action,Adventure,Hindi Dub,Live-Action,Sci-Fi','A team of teenagers with attitude are recruited to save Angel Grove from the evil witch, Rita Repulsa, and later, Lord Zedd, Emperor of all he sees, and their horde of monsters.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-jungle-fury','Power Rangers Season 16 Jungle Fury','https://image.tmdb.org/t/p/w500/gJXN4Dmg2qaaETgwg7BPOSqzhrT.jpg',2008,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','When the evil Dai Shi escapes and hatches a plan which will allow animals to rule the human world, the Power Rangers set out on a mission to stop him.',32);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-operation-overdrive','Power Rangers Season 15 Operation Overdrive','https://image.tmdb.org/t/p/w500/zOOvRQ8Sl3lNHRVFUppcP2UX6FJ.jpg',2007,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi,Tamil,Telugu','Five teenagers set out to protect ancient jewels which hold great powers from the hands of two evil brothers who want to use it for selfish reasons.',32);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers-turbo','Power Rangers Season 5 Turbo','https://image.tmdb.org/t/p/w500/hM3MxdOXVUEsamywO5aR4ZLPRy3.jpg',1997,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','Divatox has begun her invasion on Earth and the Power Rangers trade in their Zeo crystal powers for Turbo technology powers to combat this new threat.',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('power-rangers','Power Rangers Season 4 Zeo','https://image.tmdb.org/t/p/w500/Ar7xSvIfUNnJCOhAIFNyVGL4oaJ.jpg',1993,'Action,Adventure,Fantasy,Hindi Dub,Kids,Live-Action,Sci-Fi','A team of teenagers with attitude are recruited to save Angel Grove from the evil witch, Rita Repulsa, and later, Lord Zedd, Emperor of all he sees, and their horde of monsters.',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ragna-crimson','Ragna Crimson','https://image.tmdb.org/t/p/w500/ba7Mav3rU1FSyt7ZJRFHlVJ9N8K.jpg',2023,'Action,Anime,Fantasy,Hindi Dub,Shounen','Ragna teams up with the enigmatic Crimson to stand against the dragons menacing the world. Although Crimson’s motivations are mysterious, his goal and Ragna’s perfectly align, and together they’ll vanquish the dragons once and for all.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('reign-of-the-seven-spellblades','Reign of the Seven Spellblades','https://image.tmdb.org/t/p/w500/kqjLHtt539Sm6aasMvlJ7tuBr4i.jpg',2023,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,School','It’s springtime at Kimberly Magic Academy, and new students are beginning their first year. Among them are a skilled and studious boy, Oliver, and a headstrong samurai girl, Nanao. They soon form a unique bond in the halls of Kimberly, but this picturesque school isn’t what it seems. Dark secrets and endless danger lurk behind every corner. Can these wizards make it to graduation alive?!',15);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ridley-jones','Ridley Jones','https://image.tmdb.org/t/p/w500/6BzkRAldoqpolMuAmNa9XnbMw83.jpg',2021,'Animation,Kids','Curious kid Ridley and her friends protect the Museum of Natural History’s treasures and keep its magical secret safe: Everything comes alive at night!',6);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('rise-of-the-teenage-mutant-ninja-turtles','Rise of the Teenage Mutant Ninja Turtles','https://image.tmdb.org/t/p/w500/4LZxcn6nWG1yWBKG0RD98HY13b4.jpg',2018,'Action & Adventure,Animation,Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy','Rise up! The Teenage Mutant Ninja Turtles get an all-new look, new weapons, and awesome new powers! Join the legendary heroes, Raph, Leo, Donnie and Mikey as these brothers discover a Hidden City beneath New York, learn amazing mystic ninja skills, battle absurd mutants… and always find time for a slice of their favorite pizza! Cowabunga!',45);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('roll-over-and-die-i-will-fight-for-an-ordinary-life-with-my-love-and-cursed-sword','ROLL OVER AND DIE: I Will Fight for an Ordinary Life with My Love and Cursed Sword!','https://image.tmdb.org/t/p/w500/uzRpWknriZnd8fxkse5sfVaQwJn.jpg',2026,'Action,Adventure,Anime,Crunchyroll,Drama,Fantasy,Girls Love,Hindi Dub','Flum wasn’t chosen for her strength—she has none. No magic, no skill, only an ability called “Reversal” that even she doesn’t understand. So why did God place her in the hero’s party? After being betrayed and sold into slavery, Flum is abused and eventually thrown to monsters for entertainment. Now faced with death, Flum must choose: be devoured or take up a cursed sword said to kill its wielder.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('secret-level','Secret Level','https://image.tmdb.org/t/p/w500/n2X5fVCoiunjC1lKnqOrIzSBI8U.jpg',2024,'Action & Adventure,Animation,Sci-Fi & Fantasy','Adult animated series of original short stories which are set within the worlds of beloved video games. Each episode serves as a gateway to a new adventure, unlocking exciting worlds from beloved gaming classics and highly anticipated new titles.',15);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('simple-samosa','Simple Samosa','https://image.tmdb.org/t/p/w500/fOarDWqFzp3525gLhtpPUeyuTPQ.jpg',2018,'Animation,Cartoon,Hindi Dub,Kids,Tamil,Telugu','',30);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('solo-leveling-hindi','Solo Leveling','https://image.tmdb.org/t/p/w500/rsOApVLbIQEcNkqSlOxNPyg3FyI.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Tamil,Telugu','They say whatever doesn’t kill you makes you stronger, but that’s not the case for the world’s weakest hunter Sung Jinwoo. After being brutally slaughtered by monsters in a high-ranking dungeon, Jinwoo came back with the System, a program only he could see, that’s leveling him up in every way. Now, he’s inspired to discover the secrets behind his powers and the dungeon that spawned them.',25);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('spider-man','Spider-Man','https://image.tmdb.org/t/p/w500/1BX1HZZqDoLDx9Ry4oET6dA9293.jpg',1994,'Action & Adventure,Animation','SpidermanBitten by a radioactive spider, Peter Parker develops spider-like superpowers. He uses these to fight crime while trying to balance it with the struggles of his personal life.',65);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('spongebob-squarepants','SpongeBob SquarePants','https://image.tmdb.org/t/p/w500/zDuKxQkG8EemvLdBn43ChdM0MJL.jpg',1999,'Animation,Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy','Sponge Bob Square PantsLanguage: Hindi – English – Tamil – Telugu – Assamese – Bengali – Gujarati – Kannada – Malayalam – Marathi – Odia – Punjabi [Org. JC WEB Stereo Audio]Deep down in the Pacific Ocean in the subterranean city of Bikini Bottom lives a square yellow sponge named SpongeBob SquarePants. SpongeBob lives in a pineapple with his pet snail, Gary, loves his job as a fry cook at the Krusty Krab, and has a knack for getting into all kinds of trouble without really trying. When he’s not getting on the nerves of his cranky next door neighbor Squidward, SpongeBob can usually be found smack in the middle of all sorts of strange situations with his best buddy, the simple yet lovable starfish, Patrick, or his thrill-seeking surfer-girl squirrel pal, Sandy Cheeks.',79);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('spy-x-family','SPY x FAMILY','https://image.tmdb.org/t/p/w500/7NAvPYPAu7MeHwP8E9sn81PqsRh.jpg',2022,'Action,Comedy,Crunchyroll,Hindi Dub,Shounen,Tamil,Telugu','World peace is at stake and secret agent Twilight must undergo his most difficult mission yet—pretend to be a family man. Posing as a loving husband and father, he’ll infiltrate an elite school to get close to a high-profile politician. He has the perfect cover, except his wife’s a deadly assassin and neither knows each other’s identity. But someone does, his adopted daughter who’s a telepath!',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('star-wars-forces-of-destiny','Star Wars: Forces of Destiny','https://image.tmdb.org/t/p/w500/a5d2y264VgYUvpKUNNT6EbL1Cwb.jpg',2017,'Action & Adventure,Animation,Cartoon,Family,Hindi Dub,Sci-Fi & Fantasy','An animated micro-series starring Rey, Jyn Erso, Princess Leia, Ahsoka Tano, and more. Small moments and everyday decisions shape a larger heroic saga.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('star-wars-resistance','Star Wars Resistance','https://image.tmdb.org/t/p/w500/xul6SG8rar3wkHPY8YusUtxcdlZ.jpg',2018,'Action & Adventure,Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy','Kazuda Xiono, a young pilot for the Resistance, is tasked with a top secret mission to investigate the First Order, a growing threat in the galaxy.',20);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('starbeam','StarBeam','https://image.tmdb.org/t/p/w500/ijJruqW5r7YtxUfWHbcV49y8NJ8.jpg',2020,'Animation,Cartoon,Hindi Dub,Kids','Zoey is excited to tackle second grade, but when danger beckons, she sneaks away and with her signature call out and transforms into StarBeam, the speediest, most powerful and most enthusiastic superhero to ever sip from a juicebox.',41);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('super-robot-monkey-team-hyperforce-go','Super Robot Monkey Team Hyperforce Go!','https://image.tmdb.org/t/p/w500/gcTY3iHLC1wm9wB4pKn2vvCxCfK.jpg',2004,'Action & Adventure,Animation,Cartoon,Family,Hindi Dub','Super Robot Monkey Team Hyperforce Go! is an American/Japanese animated television series, and was created by Ciro Nieli, one of the directors of Teen Titans, with animation being done by a Japanese studio known as The Answer Studio. Set mainly on the fictional planet of Shuggazoom, the series follows the adventures of five cyborg monkeys and a human boy named Chiro as they struggle to protect their planet – and the rest of the universe – from the forces of evil.As is obvious from the visual appearance of the show, there is a significant anime influence present, despite being produced for American television. It was also influenced by Star Trek, Super Sentai, Voltron, and Star Wars. The show also contains various references to pop culture, a notable example being the episode “Season of the',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('super-shiro','Super Shiro','https://image.tmdb.org/t/p/w500/iDYOQEXxAx3t8sJXABVSNbwQfwh.jpg',2019,'Animation,Anime,Comedy,Hindi Dub','The Nohara family dog Shiro becomes a superhero and protects the legendary bone “Bobobobobone” from the evil inventor dog Dekapoo and his ambitions of world domination.',48);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sword-art-online-alternative-gun-gale-online','Sword Art Online Alternative: Gun Gale Online','https://image.tmdb.org/t/p/w500/mkFSXuWzPemM1Ok0sBHl0SAsFbX.jpg',2018,'Action,Anime,Hindi Dub,Military,Video Game','A shy university student in Tokyo, Karen Kohiruimaki stands in stark contrast to her in-game avatar—in fact, she happens to stand above everyone else too, much to her dismay. Towering above all the people around her, Karen’s insecurities over her height reach the point where she turns to the virtual world for an escape. Starting game after game in hopes of manifesting as a cute, short character, she finally obtains her ideal self in the world of Gun Gale Online. Overjoyed by her new persona, she pours her time into the game as LLENN, garnering her reputation as the legendary player killer. However, when one of LLENN’s targets gets the best of her, she ends up meeting Pitohui, a skilled yet eccentric woman. Pitohui insists that LLENN participates in Squad Jam, a battle royale. Thrust into t',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-smurfs','The Smurfs','https://image.tmdb.org/t/p/w500/cezQyM5cO454vUdLiLOkv78K64D.jpg',1981,'Animation,Cartoon,Family,Hindi Dub,Kids,Sci-Fi & Fantasy','Classic Saturday-morning cartoon series featuring magical blue elf-like creatures called Smurfs. The Smurfs, named for their personalities, inhabit a village of mushroom houses in an enchanted forest. These loveable creatures are led by Papa Smurf and live carefree… except for one major threat to their existance: Gargamel, an evil but inept wizard who lives in a stone-built house in the forest; and his feline companion, the equally nasty Azrael.',57);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('sword-of-the-demon-hunter','Sword of the Demon Hunter','https://image.tmdb.org/t/p/original/8BNGnDKMaDvpmkTd6z9pQL97Upe.jpg',2025,'Amazon Prime,Animation,Anime,Anime Times,Drama,Hindi Dub,Sci-Fi & Fantasy','Jinta journeys through a century-spanning epic, all while questioning why he wields a sword.',24);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tatsuki-fujimoto-17-26','Tatsuki Fujimoto 17-26','https://animedekho.app/wp-content/uploads/2025/11/filters_quality95formatwebp-1024x894.jpeg',2025,'Action,Anime,Comedy,Drama,Hindi Dub,Romance,School,Shounen,Supernatural','Six studios and seven directors adapt the early works of Tatsuki Fujimoto, the mastermind behind “Chainsaw Man,” into an anime anthology. Each episode is an anime adaptation of a short story he drew from ages seventeen to twenty-six, including the first manga he ever submitted for competition. Watch as vivid tales of young love, chaos, madness, and the bonds between people unfold in each episode.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('team-zenko-go','Team Zenko Go','https://image.tmdb.org/t/p/w500/jMBXG9yMIzbrJosvMJKjr9CRF1L.jpg',2022,'Adventure,Cartoon,Hindi Dub,Kids','Every good deed is one for this team of kids. Niah, Ari, Ellie and Jax go undercover to help others and secretly solve the city’s problems!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('teen-titans-go','Teen Titans Go!','https://image.tmdb.org/t/p/w500/udaLIJ6Na7GOHjvTlyP9JFPTccv.jpg',2013,'Action & Adventure,Animation,Cartoon,Comedy,Family,Hindi Dub,Sci-Fi & Fantasy,Super Power','Robin, Starfire, Raven, Beast Boy and Cyborg return in all-new, comedic adventures. They may be super heroes who save the world every day … but somebody still has to do the laundry!',130);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-adventures-of-rocky-and-bullwinkle','The Adventures of Rocky and Bullwinkle','https://image.tmdb.org/t/p/w500/hVgLwABK45karNU1gLdfACMl87a.jpg',2018,'Animation,Comedy,Family','The world-famous talking moose and flying squirrel are back in The Adventures of Rocky and Bullwinkle, a comedy about two goofball friends who end up in harrowing situations but end up saving the day time and again. As their silly ambitions dovetail with Fearless Leader’s sinister plans to take over the world, they are set on a collision course with his notorious super spies Boris and Natasha.',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-apothecary-diaries-hindi','The Apothecary Diaries','https://image.tmdb.org/t/p/w500/qGObcxuXKcKhP43BqTeIC7KgRcM.jpg',2023,'Anime,Crunchyroll,Drama,Hindi Dub,Historical,Medical,Mystery,Tamil,Telugu','Maomao lived a peaceful life with her apothecary father. Until one day, she’s sold as a lowly servant to the emperor’s palace. But she wasn’t meant for a compliant life among royalty. So when imperial heirs fall ill, she decides to step in and find a cure! This catches the eye of Jinshi, a handsome palace official who promotes her. Now, she’s making a name for herself solving medical mysteries!',48);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-cuphead-show','The Cuphead Show!','https://image.tmdb.org/t/p/w500/l6nGUyxKCi7ODvyfc8qQShliVEd.jpg',2022,'Animation,Cartoon,Comedy,Family,Hindi Dub','Follow the misadventures of the impulsive Cuphead and his cautious but persuadable brother Mugman in this animated series based on the hit video game.',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-daily-life-of-the-immortal-king-hindi','The Daily Life of the Immortal King','https://image.tmdb.org/t/p/w500/7By0jV3kf9MVvv3X3K8u4mhRUwp.jpg',2020,'Action,Adventure,Anime,Comedy,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi,Tamil,Telugu','As a cultivation genius who has achieved a new realm every two years since he was a year old, Wang Ling is a near-invincible existence with prowess far beyond his control. But now that he’s sixteen, he faces his greatest battle yet – Senior High School. With one challenge after another popping up, his plans for a low-key high school life seem further and further away…',63);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-great-cleric','The Great Cleric','https://image.tmdb.org/t/p/w500/r8kJsQoVkRlUNK9VJMbPiw0CpiD.jpg',2023,'Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','Can a former salaryman become peerless in another world?!A salaryman was shot to death just before earning a promotion, and a god decided to reincarnate him in another world as a fifteen-year-old healer named Luciel. On top of all that, the country he was born into seems to hate healers. Feeling that he’s in danger, Luciel visits the adventurers’ guild in hopes of keeping himself safe. But the training is much harder than he expected, and every day he’s forced to drink a mysterious beverage called “Substance X.” Wait, this life doesn’t seem to have anything to do with being a healer…The day-to-day life of a super-masochistic, back-from-the-dead healer begins, with his very survival on the line!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-guardians-of-justice','The Guardians of Justice','https://image.tmdb.org/t/p/w500/ezZDQ8neVO4GK1CizSdFt1IhsUE.jpg',2022,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Mystery,Thriller','When their seemingly fearless leader self-destructs, a team of troubled superheroes must confront festering evil in the world — and in themselves.',7);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-legend-of-korra','The Legend of Korra','https://image.tmdb.org/t/p/w500/nhP0VGO2GSZbL4PUgmA6Vja48aM.jpg',2012,'Action,Adventure,Cartoon,Drama,Family,Fantasy,Hindi Dub,Malayalam,Sci-Fi,Tamil,Telugu','Avatar Korra, a headstrong, rebellious, feisty young woman who continually challenges and breaks with tradition, is on her quest to become a fully realized Avatar. In this story, the Avatar struggles to find balance within herself.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-powerpuff-girls-new','The Powerpuff Girls New','https://image.tmdb.org/t/p/w500/n8M0tl1V2QYRLbs3hPQfJgQgTgT.jpg',2016,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Kids,Tamil,Telugu','Three colorful, sugarcoated kids trying to juggle school and save the world before bedtime.',40);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-reincarnation-of-the-strongest-exorcist-in-another-world','The Reincarnation of the Strongest Exorcist in Another World','https://image.tmdb.org/t/p/w500/uDHeojoTIG2OVbdBrUhiO2jzVlp.jpg',2023,'Action,Adventure,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation','Betrayed and on the brink of death, genius exorcist Haruyoshi Kuga still has an ace up his sleeve—a reincarnation spell. With a successful incantation taking him to a new world reborn as Seika Lamprogue into a distinguished wizard family, his only wish is to find happiness. But as Seika’s onmyō art exceeds this world’s magic, will he be able to live an easy, happy-go-lucky life?',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-story-of-cinderella','The Story of Cinderella','https://image.tmdb.org/t/p/w500/h7d3rWIk13AD4F90t0D1Q1gSEvP.jpg',1996,'Adventure,Anime,Fantasy,Hindi Dub,Romance','Cinderella is the daughter of a wealthy duke who has remarried to provide her with a mother and sisters. When the Duke travels abroad, Cinderella discovers that her new family is anything but a family. With spoiled stepsisters and a harsh stepmother, Cindrella is forced to cook, clean and manage the household. Yet she remains cheerful, gentle and kind to her family, to her animal friends and to a mysterious boy, named Charles, who seems to have a connection with the prince of Emerald Castle. A whole new story on a classic fairytale.When Cinderella’s cruel stepmother prevents her from attending the Royal Ball, she gets some unexpected help from the lovable mice Gus and Jaq, and from her Fairy Godmother.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-strongest-magician-in-the-demon-lords-army-was-a-human','The Strongest Magician in the Demon Lord’s Army Was a Human','https://image.tmdb.org/t/p/w500/kCOho8tk5Gz0LB9hACQ8uDs1dTg.jpg',2024,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','Ike is a powerful magician and the leader of the Immortal Brigade, part of the Seventh Corps of the Demon Lord’s Army. He single-handedly conquers fortresses and pushes back the armies of humanity. Neither Dairokuten, the Demon Lord, nor Ike’s loyal soldiers know his darkest secret—he is a human in hiding! But can he keep his secret safe and bring peaceful coexistence to demons and humans?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-summer-hikaru-died','The Summer Hikaru Died','https://image.tmdb.org/t/p/w500/x0wiTO87UMiVCUe24nKaHlp7AIc.jpg',2025,'Drama,Hindi Dub,Horror,Mystery,Supernatural','Six months ago, Hikaru vanished for a week. Now, as his best friend Yoshiki senses something amiss and confronts him, the harrowing truth emerges.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-unaware-atelier-meister','The Unaware Atelier Meister','https://image.tmdb.org/t/p/w500/uZ7uXnU2CeJ3vlmzth1Owd2hVm4.jpg',2025,'Action,Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub','Kurt Rockhans is a kind-hearted errand boy for a hero’s party, the Flaming Dragon Fang. One day, he’s banished from the party and finds out he has the lowest rank in combat. In order to make a living, Kurt picks up various jobs and discovers he has astonishing abilities. Though he doesn’t realize it yet, Kurt has SSS-rank skills in anything other than fighting, as he sets off on a new journey.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-weakest-tamer-began-a-journey-to-pick-up-trash-hindi','The Weakest Tamer Began a Journey to Pick Up Trash','https://image.tmdb.org/t/p/w500/fpcB53bIP5h4140ZGliJK1CyfAq.jpg',2024,'Adventure,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,Tamil,Telugu','In Ivy’s world, stars are everything. She’s a Tamer, born to subdue monsters and animals, but she was also born starless! With her life in danger, Ivy flees into the forest where she befriends a weak little slime named Sora—the one creature she can tame. Together, the unlikely pair set off on a journey, salvaging rubbish to survive. Along the way they’ll win hearts, evade danger, and discover there’s more to starless Ivy than meets the eye!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('the-wrong-way-to-use-healing-magic-hindi','The Wrong Way to Use Healing Magic','https://image.tmdb.org/t/p/w500/uQEbcmuUwDfPiVUIRCF6d57eErM.jpg',2024,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai','An ordinary walk home from school turns into an epic journey for Usato. After suddenly being dropped into another world with two fellow students, Usato learns he was summoned there by accident. But things turn around when he discovers a unique aptitude for healing magic! Now, he trains beyond human limitations, using his self-healing abilities to gain absurd strength and unrivaled stamina.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('thunder-3','Thunder 3','https://image.tmdb.org/t/p/original/uVGuFiXA1PocSxpQbMVCHXgGPwr.jpg',2026,'Animation,Cartoon,Hindi Dub,Sci-Fi & Fantasy,Tamil,Telugu','Unremarkably ordinary middle schoolers, Pyontaro, Hiroshi and Tsubame, wander into an extraordinary adventure when Pyontaro’s little sister goes missing.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('thundercats','ThunderCats','https://image.tmdb.org/t/p/w500/76M4IYMDG97W6lvSpGptico0ekS.jpg',2011,'Action & Adventure,Animation,Cartoon,Hindi Dub,Kids,Sci-Fi & Fantasy','The ThunderCats are on the move! After the kingdom of Thundera is attacked by the lizard people, Lion-O leads Tygra, Cheetara and the other heroes on a quest for the Book of Omens and the magic stones of legend. But he’ll have to face villains like Mumm-Ra, the ancient evil sorceror, and Slithe, the dangerous lizard general. Luckily, he has the Sword of Omens and its amazing powers at his disposal.',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('timon-pumbaa','Timon & Pumbaa','https://image.tmdb.org/t/p/w500/sn9PTOwI6ktLHZcysCrP8cqOw1b.jpg',1995,'Animation,Cartoon,Comedy,Family,Hindi Dub,Tamil,Telugu','Set after the events of the “The Lion King,” follow Timon and Pumbaa as they go on misadventures in the jungle, as well as across the globe in various.',46);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tokyo-ghoul','Tokyo Ghoul','https://image.tmdb.org/t/p/w500/3bio8GB2qxcTWshon1iggDXeLWJ.jpg',2014,'Action,Anime,Drama,Fantasy,Hindi Dub,Horror,Seinen,Suspense','A sinister threat is invading Tokyo: flesh-eating “ghouls” who appear identical to humans and blend into their population. Reserved college student Ken Kaneki buries his nose in books and avoids the news of the growing crisis. However, the appearance of an attractive woman named Rize Kamishiro shatters his solitude when she forwardly asks him on a date.While walking Rize home, Kaneki discovers she isn’t as kind as she first appeared, and she has led him on with sinister intent. After a tragic struggle, he later awakens in a hospital to learn his life was saved by transplanting the now deceased Rize’s organs into his own body.Kaneki’s body begins to change in horrifying ways, and he transforms into a human-ghoul hybrid. As he embarks on his new dreadful journey, Kaneki clings to his humanit',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('tottemo-luckyman','Tottemo! Luckyman','https://image.tmdb.org/t/p/w500/ojOOavQH2rNWNhG5NAw2l76czQJ.jpg',1994,'Animation,Anime,Comedy,Family,Hindi Dub,Tamil,Telugu','This gag comedy series focused on the adventures of a bizarre superhero powered by special cooking and fights against various aliens and other enemies threatening the planet Earth.',50);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-armada','Transformers: Armada','https://image.tmdb.org/t/p/w500/tjbBjYfXyISFZMbpNQBNoiKwJp2.jpg',2002,'Action & Adventure,Animation,Sci-Fi & Fantasy','Transformers: Armada, known in Japan as Chō Robot Seimeitai Transformers: Micron Densetsu, is a Transformers animated series, comic series and toy line which ran from 2002–2003. It was originally scheduled for 2001, however was delayed until early-2002. As the first series co-produced between the American toy company, Hasbro, and their Japanese counterpart, Takara, Armada begins a new continuity/universe for Transformers, with no ties to any of the previous series, including the immediately prior Transformers: Robots in Disguise in 2001. It would go on to birth a sequel in the form of Transformers: Energon.',8);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('transformers-cyberverse','Transformers: Cyberverse','https://image.tmdb.org/t/p/w500/fxgzkgFavRmKLawUR4w6MQmWmCl.jpg',2018,'Action & Adventure,Animation,Hindi Dub','When Bumblebee begins to suffer amnesia, his partner, Windblade, comes to the rescue, and repairs his memory chips, enabling him to rediscover his past adventures on Cybertron. Once his memories are repaired, Bumblebee gets a clue that will lead both him and Windblade to complete their current mission and save their friends, unaware that Megatron sent his Decepticon assassins to hunt them down.',36);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('trillion-game','TRILLION GAME','https://image.tmdb.org/t/p/w500/uDOZ9Qhrl7RXBKAAODWIQvlArUr.jpg',2024,'Adult Cast,Anime,Crunchyroll,Drama,Hindi Dub,Seinen,Tamil,Telugu','Old schoolmates Haru and Gaku will do anything to achieve success. And success to them means earning a trillion dollars! But to do so, they’ll need to take full advantage of their own unique skills. Haru is a persuasive and confident speaker who can connect with anyone, while Gaku, although awkward, is an expert programmer. Will their combined talents be enough to make their dream a reality?',26);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('true-beauty','True Beauty','https://image.tmdb.org/t/p/w500/9gpc8kIhNEG7r0VTkyI9aVBxdO3.jpg',2024,'Anime,Comedy,Crunchyroll,Drama,Hindi Dub,Romance,Tamil,Telugu','Once bullied for her looks, Jugyeong transforms herself using the art of makeup. When she joins a new school with a True Beauty goddess competition, offering winners the chance of recruitment by entertainment agencies, she instantly becomes a top candidate! But her new identity is at stake when heartthrob Suho Lee accidentally sees her bare face. Will her elite status be short-lived?',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('turning-mecard','Turning Mecard','https://image.tmdb.org/t/p/w500/3eev0HAIVqDMDEUZNlNBnIlvFHD.jpg',2015,'Action & Adventure,Animation,Comedy,Family,Hindi Dub,Kids,Sci-Fi & Fantasy','Grade-schooler Jason meets a Mecanimal, a transforming minicar from the alternate world of Triforce, named Evan. Jason and Evan are both searching for missing family members, and team up to help each other. Together, they meet more Mecanimals as they battle across dimensions and learn important lessons along the way.',52);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('twilight-out-of-focus','Twilight Out of Focus','https://image.tmdb.org/t/p/w500/21bYoggswt5hFKqqsUBLUx1smHz.jpg',2024,'Anime,Boys Love,Crunchyroll,Hindi Dub,School','A boys’ school film club is the backdrop for three tales of new romance. Mao and Hisashi pair up for a project, make three promises, and draw closer together in the process. The club president, Jin, and a jealous junior named Giichi clash before finding common ground. Shion, a first-year student, joins the film club in search of a boyfriend and butts heads with Rei—until Rei asks him on a date.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('ultimate-spider-man','Ultimate Spider-Man','https://image.tmdb.org/t/p/w500/fmjCL1PCAqO5kr8ztOT5UXTouVw.jpg',2012,'Action,Adventure,Cartoon,Comedy,Hindi Dub,Kids,Tamil,Telugu','SpidermanWhile being trained by S.H.I.E.L.D., Spider-Man battles evil with a new team of teen colleagues.Please Note That Seasons 3-4 are not available in Tamil and Telugu.',104);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('villainess-level-99','Villainess Level 99','https://image.tmdb.org/t/p/w500/45KqPcfk6qrxl5XF7z9Wwtvo0vw.jpg',2024,'Anime,Crunchyroll,Fantasy,Hindi Dub,Isekai,Reincarnation,School','Villainess Level 99: I May Be the Hidden Boss But I’m Not the Demon LordThis college kid wants nothing more than a quiet life. So when she’s reborn as Yumiella, the hidden villainess of an Otome RPG, she’s not exactly thrilled. Still yearning for peace, she abandons her evil duties to live a more discreet life. Until her gamer side kicks in, and she accidentally reaches level 99! Now, everyone suspects that she’s the infamous Demon Lord. What future awaits her?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('welcome-to-the-outcasts-restaurant','Welcome to the Outcast’s Restaurant!','https://image.tmdb.org/t/p/w500/1IJigiaXgp8qvjwlRVFYhP71z8Q.jpg',2025,'Anime,Comedy,Fantasy,Gourmet,Hindi Dub','When superstar adventurer Dennis gets booted from the world’s strongest party, he teams up with runaway Atelier to serve up his true passion—delicious cuisine. But this not-so-average eatery has not-so-average patrons. Dennis will battle his quirky customers’ troubles with his trusty butcher knife and wok. Visit Adventurer’s Restaurant and fill up your heart and stomach!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('why-does-nobody-remember-me-in-this-world','Why Does Nobody Remember Me in This World?','https://image.tmdb.org/t/p/w500/u9C9lYBA6dujAaYXjxlgcEqVc1d.jpg',2024,'Action,Anime,Crunchyroll,Fantasy,Hindi Dub,Sci-Fi','In a world where humans triumphed in a great war, Kai guards sealed crypts containing their enemies. But when “World Rebirth” overwrites history, he’s thrust into an alternate reality where humanity lost the war and he’s been forgotten by everyone he knows. Now, this lost hero must rise to restore the world’s balance!',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('winx-club','Winx Club','https://image.tmdb.org/t/p/w500/2JbdJNwSPJYHQ7X0qS4eMBajxi9.jpg',2004,'Action,Adventure,Bengali,Cartoon,Fantasy,Hindi Dub,Kids,Malayalam,Sci-Fi,Tamil,Telugu','In a magical universe, witches, warriors begin fighting in the name of good .vs. evil! At a magic school, five teenage girls are selected to defend the universe with their magic.Please Note That All Episodes are not available in All Languages.',215);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('witch-hat-atelier','Witch Hat Atelier','https://image.tmdb.org/t/p/original/78m1Tv3suHmUryTI9VNPwKLKjHZ.jpg',2026,'Anime,Drama,Fantasy,Hindi Dub,Netflix,Seinen','In a world where only witches can cast magic, they must avoid being seen by ordinary people while casting. While Coco does her chores, she daydreams of becoming a witch. When a young witch named Qifrey visits her village, Coco uncovers the “absolute secret,” becomes Qifrey’s apprentice, and begins her studies. This is the story of children who encounter despair, yet reach out toward hope.',13);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('x-men-anime','X-Men Anime','https://image.tmdb.org/t/p/w500/sXNDCbP5sjq1FeXBxGovN21VVOG.jpg',2011,'Action,Drama,Hindi Dub,Super Power','X Men AnimeX-Men, still grieving over the death of Phoenix (Jean Grey), are investigating a case of a missing mutant girl in Northern Japan. This leads them to a mysterious virus that turns mutants into monsters. U-Men and the Inner Circle want it.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('yo-kai-watch','Yo-kai Watch','https://image.tmdb.org/t/p/w500/k8EM9rl22UAGtR2YUHNHsnMWggn.jpg',2014,'Anime,Comedy,Hindi Dub,Kids,Mythology,Supernatural,Tamil,Telugu','Yokai WatchYoukai Watch focusing on elementary schooler Keita Amano again. The events take place right after the original season; but still chronologically occur before the now complete Shadow Side events as they take place 30 years in the future.',30);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('you-and-i-are-polar-opposites','You and I Are Polar Opposites','https://image.tmdb.org/t/p/w500/qCymZwe8XksvmBO4MpwZdD2eN2g.jpg',2026,'Anime,Comedy,Crunchyroll,Hindi Dub,Romance,School,Shounen','Suzuki’s a high school girl in love, but the guy she’s fallen for is nothing like her! While she’s cheerful, outgoing, and always trying to fit in, her classmate Yusuke Tani is stoic, quiet, and doesn’t seem to care what people think of him. Will Suzuki be able to overcome her anxieties and ask him out, or will she discover that opposites really don’t attract?',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('your-lie-in-april','Your Lie in April','https://image.tmdb.org/t/p/w500/rRjfH3ckTYz8z8aSkJshFL4VyK9.jpg',2014,'Anime,Comedy,Drama,Hindi Dub,Love Polygon,Music,Performing Arts,Romance,School,Shounen','Kousei Arima was a genius pianist until his mother’s sudden death took away his ability to play. Each day was dull for Kousei. But, then he meets a violinist named Kaori Miyazono who has an eccentric playing style. Can the heartfelt sounds of the girl’s violin lead the boy to play the piano again?',22);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('yowayowa-sensei','Yowayowa Sensei','https://image.tmdb.org/t/p/w500/1WDp9RjN7odYw490WLNw79iceLa.jpg',2026,'Ani-One India,Anime,Comedy,Ecchi,Hindi Dub,Love Status Quo,Romance,School,Shounen','Hiyori Hiwamura is known as the “Scary Teacher,” and if you offend her, she’ll put a curse on you! Or at least that’s what everyone believes. She’s secretly a total softy who’s deeply misunderstood, and once you see her sweet side, she’ll put a different kind of spell on you.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('yu-gi-oh-zexal','Yu-Gi-Oh! Zexal','https://image.tmdb.org/t/p/w500/3aZUtzeHQrLgQQdYNqHSbJqj59G.jpg',2011,'Action,Anime,Comedy,Fantasy,Kids,Shounen,Strategy Game','Yu Gi Oh! Zexal / YuGiOh ZexalWhen aspiring duelist Yuma meets Astral, a mysterious visitor from another universe, it seems like destiny. Yuma needs Astral to teach him how to duel, and Astral needs Yuma to help him regain his memories!',16);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zig-and-sharko','Zig and Sharko','https://image.tmdb.org/t/p/w500/5X3VwmYrkkGpUqcWYLPkzP00nxr.jpg',2010,'Cartoon,Comedy,Family,Hindi Dub,Tamil,Telugu','On a desert island lives a starving hyena with one obsession: devour that delicious mermaid from the rock in the lagoon. But the lovely fish-girl’s best friend is a shark, a shark with a lot of muscle and who loves to sabotage the hyena’s every move.Please Note That Episode Numbers and Name Will not Match Because Episode List is Imported From TheMovieDatabse But Episodes are Ripped From Amazon Prime (Different Order)Season 1-2 is not available in Tamil-Telugu',78);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('we-bare-bears','We Bare Bears','https://image.tmdb.org/t/p/w500/3xWzlLZ0kAD6SkVZTekFM9lxZyP.jpg',2015,'Cartoon,Comedy,Family,Hindi Dub,Kids','Three brother bears awkwardly attempt to find their place in civilized society, whether they’re looking for food, trying to make human friends, or scheming to become famous on the internet. Grizzly, Panda and Ice Bear stack atop one another when they leave their cave and explore the hipster environs of the San Francisco Bay Area, and it’s clear the siblings have a lot to learn about a technologically driven world. By their side on many adventures are best friend Chloe (the only human character in the cast), fame-obsessed panda Nom Nom, and Charlie, aka Bigfoot.',121);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('whats-new-scooby-doo','What’s New, Scooby-Doo?','https://image.tmdb.org/t/p/w500/7sX80eWq4XHvFGUmCg803iifUcG.jpg',2002,'Action,Adventure,Cartoon,Comedy,Family,Hindi Dub,Kids,Mystery,Tamil,Telugu','Scooby-Doo and the Mystery, Inc. gang are launched into the 21st century, with new mysteries to solve.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('wizards-tales-of-arcadia','Wizards: Tales of Arcadia','https://image.tmdb.org/t/p/w500/aAMcPNLzCML40q7qmuB0jrZIcsI.jpg',2020,'Action,Adventure,Cartoon,Comedy,Fantasy,Hindi Dub,Sci-Fi','Merlin’s apprentice joins Arcadia’s heroes on a time-bending adventure in Camelot, where conflict is brewing between the human, troll and magical worlds.',10);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('zom-100-bucket-list-of-the-dead','Zom 100: Bucket List of the Dead','https://image.tmdb.org/t/p/w500/XzOeAppGpnsSAiK82idkg0BoCt.jpg',2023,'Action,Anime,Comedy,Crunchyroll,Hindi Dub,Horror,Seinen,Supernatural,Survival,Suspense,Tamil,Telugu','An overworked 24-year-old finally decides to live a little and create a bucket list, when a zombie outbreak hits the country.',12);
INSERT OR REPLACE INTO anime (id,title,poster,year,genres,synopsis,total_episodes) VALUES ('vinland-saga-hin','Vinland Saga','https://image.tmdb.org/t/p/w500/AuUgiPuvwkBq20kagz4ZcyhkPTY.jpg',2019,'Action,Adventure,Crunchyroll,Drama,Gore,Hindi Dub,Historical,Seinen,Tamil,Telugu,War & Politics','For a thousand years, the Vikings have made quite a name and reputation for themselves as the strongest families with a thirst for violence. Thorfinn, the son of one of the Vikings’ greatest warriors, spends his boyhood in a battlefield enhancing his skills in his adventure to redeem his most-desired revenge after his father was murdered.',48);
COMMIT;
